function autoModeWatcher() {
		const t = localStorage.getItem('theme') as string;
        const themeDarkLink: HTMLLinkElement | null = document.head.querySelector('#theme-dark');
        const themeLightLink: HTMLLinkElement | null = document.head.querySelector('#theme-light');
        const isSupport = isMediaSupport();

		if (t === 'dark') {
            if (isSupport) {
                if (themeDarkLink) {
                    themeDarkLink.media = 'screen and (prefers-color-scheme: light)';
                }
                if (themeLightLink) {
                    themeLightLink.media = 'screen and (prefers-color-scheme: dark)';
                }
                currentTheme.value = 'dark';
            } else {
                if (themeDarkLink) {
                    themeDarkLink.media = 'all';
                }

                if (themeLightLink) {
                    themeLightLink.media = 'not all';
                }
            }
		} else if (!isSupport) {
            if (themeLightLink) {
                themeLightLink.media = 'all';
            }
            if (themeDarkLink) {
                themeDarkLink.media = 'not all';
            }
        }

        let u = localStorage.getItem('altMenu') as string;

        if (u === 'true') {
            useAltMenu.value = true;
        } else {
            useAltMenu.value = false;
        }
	}

function handleWheel(e: MouseEvent) {
        const target = e.target;

        if (target instanceof HTMLInputElement && target.type === 'number') {
            target.blur();
        }
    }

function getSelectedObjectName() {
        let titles: string[] = [];
        let idArray = Array.from(activatedMap.keys());
        let titleText: string = '';

        idArray.sort((a, b) => {
            let aMap = choiceMap.get(a);
            let bMap = choiceMap.get(b);

            if (typeof aMap !== 'undefined' && typeof bMap !== 'undefined') {
                if (aMap.row.index !== bMap.row.index) return aMap.row.index - bMap.row.index;
                return aMap.choice.index - bMap.choice.index;
            }

            return 0;
        });

        if (seperateChoices) {
            let prevRowId = '';

            for (let i = 0; i < idArray.length; i++) {
                let cMap = choiceMap.get(idArray[i]);

                if (typeof cMap !== 'undefined') {
                    const row = cMap.row;
                    const choice = cMap.choice;

                    if (choice.title !== '') {
                        if (row.id !== prevRowId) {
                            if (prevRowId !== '') titles.push('\n');
                            titles.push(`**${row.title !== '' ? row.title : row.debugTitle || ''}**\n`);
                            if (choice.isSelectableMultiple) {
                                titles.push(`${choice.title}(x${choice.multipleUseVariable})`);
                            } else {
                                titles.push(`${choice.title}`);
                            }
                            prevRowId = row.id;
                        } else {
                            if (choice.isSelectableMultiple) {
                                titles.push(`, ${choice.title}(x${choice.multipleUseVariable})`);
                            } else {
                                titles.push(`, ${choice.title}`);
                            }
                        }
                    }
                }
            }
            titleText = titles.join('');
        } else {
            for (let i = 0; i < idArray.length; i++) {
                let cMap = choiceMap.get(idArray[i]);

                if (typeof cMap !== 'undefined') {
                    const choice = cMap.choice;

                    if (choice.title !== '') {
                        if (choice.isSelectableMultiple) {
                            titles.push(`${choice.title}(x${choice.multipleUseVariable})`);
                        } else {
                            titles.push(`${choice.title}`);
                        }
                    }
                }
            }
            titleText = titles.join(', ');
        }
        const tempDiv = document.createElement('div');
        tempDiv.innerHTML = titleText;

        return tempDiv.textContent;
    }

function handleTab(e: KeyboardEvent) {
        if (e.key === 'Tab') {
            e.preventDefault();

            const target = e.target as HTMLTextAreaElement;
            const start = target.selectionStart;
            const end = target.selectionEnd;

            text = text.slice(0, start) + '\t' + text.slice(end);

            requestAnimationFrame(() => {
                target.selectionStart = target.selectionEnd = start + 1;
            });
        }
    }

function exportDesign() {
        if (app.styling) {
            const design: {version: string, styling: Styling} = {version: appVersion, styling: {}};        
            design.styling = app.styling;

            const saveData = JSON.stringify(design);
            const blob = new Blob([saveData], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            const filename = `design_${getTimestamp()}.json`;

            a.href = url;
            a.download = filename;
            a.click();

            URL.revokeObjectURL(url);
        }
    }

function saveProcess() {
        if (cyoaAbortController) {
            cyoaAbortController.abort();
        }
        autoSave();
    }

async function importFont() {
        if (importFromUrl) {
            const idx = app.customFonts.indexOf(importField);
            if (importField !== '') {
                if (idx === -1) {
                    try {
                        const res = await fetch(importField, { method: 'GET', mode: 'cors' });

                        if (res.ok) {
                            const tag = document.createElement('link');
                            tag.id = importField;
                            tag.rel = 'stylesheet';
                            tag.href = importField;
                            tag.crossOrigin = 'anonymous';
                            document.head.appendChild(tag);
                            app.customFonts.push(importField);
                            snackbarVariables.labelText = 'Font imported successfully.'
                        } else {
                            snackbarVariables.labelText = 'Unable to access the URL. Please check the URL.';
                            snackbarVariables.isOpen = true;
                            console.log(res.status);
                        }
                    } catch (error) {
                        snackbarVariables.labelText = 'Unable to access the URL. This might be due to a network issue or CORS restriction.';
                        snackbarVariables.isOpen = true;
                        console.log(error);
                    }
                } else {
                    snackbarVariables.labelText = 'This URL has already been added.';
                    snackbarVariables.isOpen = true;
                }
            } else {
                snackbarVariables.labelText = 'Please enter a URL.';
                snackbarVariables.isOpen = true;
            }
        } else {
            const idx = app.googleFonts.indexOf(importField);
            if (importField !== '') {
                if (idx === -1) {
                    const fontId = importField.replace(/ /g, '+');
                    console.log(fontId);
                    const url = `https://fonts.googleapis.com/css2?family=${fontId}&display=swap`;

                    try {
                        const res = await fetch(url, { method: 'GET', mode: 'cors' });

                        if (res.ok) {
                            const tag = document.createElement('link');
                            tag.id = fontId;
                            tag.rel = 'stylesheet';
                            tag.href = url;
                            tag.crossOrigin = 'anonymous';
                            document.head.appendChild(tag);
                            app.googleFonts.push(importField);
                            textFonts.push(importField);
                            snackbarVariables.labelText = 'Font imported successfully.';
                            snackbarVariables.isOpen = true;
                        } else {
                            snackbarVariables.labelText = 'Unable to load the font. Please check the font name.';
                            snackbarVariables.isOpen = true;
                            console.log(res.status);
                        }
                    } catch (error) {
                        snackbarVariables.labelText = 'Unable to access the Google Fonts. Please check the font name.';
                        snackbarVariables.isOpen = true;
                        console.log(error);
                    }
                } else {
                    snackbarVariables.labelText = 'This font has already been added.';
                    snackbarVariables.isOpen = true;
                }
            } else {
                snackbarVariables.labelText = 'Please enter a Font name.';
                snackbarVariables.isOpen = true;
            }
        }
    }

function deleteFont() {
        if (importFromUrl) {
            const cIdx = app.customFonts.indexOf(fontUrl);
            const tag = document.getElementById(fontUrl);

            fontUrl = '';

            if (cIdx !== -1) {
                app.customFonts.splice(cIdx, 1);
            }

            if (tag) {
                tag.remove();
            }
        } else {
            const fontId = fontName.replace(/ /g, '+');
            const gIdx = app.googleFonts.indexOf(fontName);
            const tIdx = textFonts.indexOf(fontName);
            const tag = document.getElementById(fontId);

            fontName = 'Times New Roman';

            if (gIdx !== -1) {
                app.googleFonts.splice(gIdx, 1);
            }

            if (tIdx !== -1) {
                textFonts.splice(tIdx, 1);
            }

            if (tag) {
                tag.remove();
            }
        }
    }

function changeObjectId() {
        if (choice.id === '') {
            choice.id = choiceId
        } else {
            if (choice.id !== choiceId) {
                choice.id = checkDupId(choice.id, choiceMap);
                if (choice.groups) {
                    for (let i = 0; i < choice.groups.length; i++) {
                        const group = groupMap.get(choice.groups[i]);
                        if (typeof group !== 'undefined') {
                            const elementIndex = group.elements.indexOf(choiceId);
                            if (elementIndex !== -1) group.elements[elementIndex] = choice.id;
                        }
                    }
                }
                if (choice.objectDesignGroups) {
                    for (let i = 0; i < choice.objectDesignGroups.length; i++) {
                        const dGroup = objectDesignMap.get(choice.objectDesignGroups[i]);
                        if (typeof dGroup !== 'undefined') {
                            const elementIndex = dGroup.elements.indexOf(choiceId);
                            if (elementIndex !== -1) dGroup.elements[elementIndex] = choice.id;
                        }
                    }
                }
                if (choice.addons) {
                    for (let i = 0; i < choice.addons.length; i++) {
                        const addon = choice.addons[i];
                        addon.parentId = choice.id;
                    }
                }
                choiceMap.set(choice.id, {choice: choice, row: row});
                choiceMap.delete(choiceId);
                choiceId = choice.id;
            }
        }
    }

function createNewAddon() {
        if (typeof choice.addons === 'undefined') choice.addons = [];
        if (!choice.addonJustify) choice.addonJustify = app.defaultAddonJustify;
        if (!choice.useSeperateAddon) choice.useSeperateAddon = app.defaultUseSeperateAddon;
        choice.addons.push({
            id: '',
            title: app.defaultAddonTitle,
            text: app.defaultAddonText,
            template: app.defaultAddonTemplate,
            addonWidth: app.defaultAddonWidth,
            image: '',
            requireds: [],
            parentId: choice.id,
            ...(app.defaultUseShowAddon && { showAddon: true }),
            ...(app.defaultUseHideAddon && { hideAddon: true })
        });
    }

function createNewScore() {
        if (typeof choice.scores === 'undefined') choice.scores = [];
        choice.scores.push({
            idx: generateId(0, 5, 's'),
            id: '',
            value: 0,
            type: '',
            requireds: [],
            beforeText: app.defaultBeforePoint,
            afterText: app.defaultAfterPoint,
            showScore: app.defaultUseShowScore
        });
    }

function cloneObject() {
        const id = generateId(0, app.objectIdLength, 'choice');
        const clone: Choice = JSON.parse(JSON.stringify(choice));

        clone.id = id;
        clone.index = index + 1;
        clone.isActive = false;
        delete clone.forcedActivated;
        delete clone.appliedDisChoices;

        for (let i = 0; i < clone.scores.length; i++) {
            const score = clone.scores[i];

            score.idx = generateId(0, 5, 's');
            scoreSet.add(score.idx);
            if (clone.isSelectableMultiple) {
                delete score.isActiveMul;
                delete score.isActiveMulMinus;
            } else {
                delete score.isActive;
            }
            delete score.setValue;
            deleteDiscount(score);
        }

        if (clone.backpackBtnRequirement) {
            if (typeof app.hideBackpackBtn !== 'undefined') {
                app.hideBackpackBtn += 1;
            } else {
                delete clone.backpackBtnRequirement;
            }
        }

        row.objects.splice(index + 1, 0, clone);
        choiceMap.set(id, {choice: row.objects[index + 1], row: row});
        if (clone.addons) {
            for (let i = 0; i < clone.addons.length; i++) {
                const addon = clone.addons[i];

                addon.parentId = clone.id;
                if (addon.isSelectable) {
                    addon.id = generateId(0, app.objectIdLength, 'addon');
                    addon.isActive = false;
                    delete addon.forcedActivated;
                    delete addon.appliedDisChoices;

                    if (addon.scores) {
                        for (let j = 0; j < addon.scores.length; j++) {
                            const score = addon.scores[j];

                            score.idx = generateId(0, 5, 's');
                            scoreSet.add(score.idx);
                            if (addon.isSelectableMultiple) {
                                delete score.isActiveMul;
                                delete score.isActiveMulMinus;
                            } else {
                                delete score.isActive;
                            }
                            delete score.setValue;
                            deleteDiscount(score);
                        }
                    }
                    choiceMap.set(addon.id, {choice: row.objects[index + 1].addons[i] as SelectableAddon, row: row});
                }
            }
        }

        for (let i = index + 2; i < row.objects.length; i++) {
            row.objects[i].index += 1;
        }

        if (clone.groups) {
            for (let i = 0; i < clone.groups.length; i++) {
                let group = groupMap.get(clone.groups[i]);
                if (typeof group !== 'undefined') {
                    let elementIndex = group.elements.indexOf(id);
                    if (elementIndex === -1) group.elements.push(id);
                }
            }
        }
        if (clone.objectDesignGroups) {
            for (let i = 0; i < clone.objectDesignGroups.length; i++) {
                let dGroup = objectDesignMap.get(clone.objectDesignGroups[i]);
                if (typeof dGroup !== 'undefined') {
                    let elementIndex = dGroup.elements.indexOf(id);
                    if (elementIndex === -1) dGroup.elements.push(id);
                }
            }
        }
    }

function deleteGroup(num: number) {
        const group = groupMap.get(choice.groups[num]);
        choice.groups.splice(num, 1);
        if (typeof group !== 'undefined') {
            const elementIndex = group.elements.indexOf(choice.id);
            const rowElementIndex = group.rowElements.indexOf(row.id);
            if (elementIndex !== -1) group.elements.splice(elementIndex, 1);
            if (rowElementIndex !== -1) group.rowElements.splice(rowElementIndex, 1);
        }
    }

function deleteDesignGroup(num: number) {
        if (choice.objectDesignGroups) {
            const group = objectDesignMap.get(choice.objectDesignGroups[num]);
            choice.objectDesignGroups.splice(num, 1);
            if (typeof group !== 'undefined') {
                const elementIndex = group.elements.indexOf(choice.id);
                if (elementIndex !== -1) group.elements.splice(elementIndex, 1);
            }
        }
    }

function deleteObject() {
        function deleteProc() {
            const idx = choice.index;
            if (choice.backpackBtnRequirement) {
                if (choice.isActive) {
                    app.btnBackpackIsOn -= 1;
                }
                app.hideBackpackBtn -= 1;
            }
            if (choice.showAllAddons && choice.isActive) {
                app.showAddons -= 1;
            }
            if (choice.groups) {
                for (let i = 0; i < choice.groups.length; i++) {
                    const group = groupMap.get(choice.groups[i]);
                    if (typeof group !== 'undefined') {
                        const elementIndex = group.elements.indexOf(choice.id);
                        if (elementIndex !== -1) group.elements.splice(elementIndex, 1);
                    }
                }
            }
            if (choice.objectDesignGroups) {
                for (let i = 0; i < choice.objectDesignGroups.length; i++) {
                    const dGroup = objectDesignMap.get(choice.objectDesignGroups[i]);
                    if (typeof dGroup !== 'undefined') {
                        const elementIndex = dGroup.elements.indexOf(choice.id);
                        if (elementIndex !== -1) dGroup.elements.splice(elementIndex, 1);
                    }
                }
            }
            if (choice.scores) {
                for (let i = 0; i < choice.scores.length; i++) {
                    const score = choice.scores[i];
                    scoreSet.delete(score.idx);
                }
            }
            if (choice.addons) {
                for (let i = 0; i < choice.addons.length; i++) {
                    const addon = choice.addons[i];
                    if (addon.isSelectable) {
                        if (addon.scores) {
                            for (let j = 0; j < addon.scores.length; j++) {
                                const score = addon.scores[j];
                                scoreSet.delete(score.idx);
                            }
                        }
                        choiceMap.delete(addon.id);
                    }
                }
            }

            activatedMap.delete(choice.id);
            tmpActivatedMap.delete(choice.id);
            row.objects.splice(index, 1);
            choiceMap.delete(choice.id);
            for (let i = idx; i < row.objects.length; i++) {
                row.objects[i].index = i;
            }
        }
        if (app.checkDeleteObject) {
            dlgVariables.currentDialog = 'dlgCommon';
            dlgVariables.row = row;
            dlgVariables.context = 'Are you sure you want to delete this choice?<br>Be sure to deselect this choice before delete.';
            dlgVariables.title = '';
            dlgVariables.cFunc = (e: CustomEvent) => {
                if (e.detail.action === 'accept') {
                    deleteProc();
                }
            }
        } else {
            deleteProc();
        }
    }

function deleteProc() {
            const idx = choice.index;
            if (choice.backpackBtnRequirement) {
                if (choice.isActive) {
                    app.btnBackpackIsOn -= 1;
                }
                app.hideBackpackBtn -= 1;
            }
            if (choice.showAllAddons && choice.isActive) {
                app.showAddons -= 1;
            }
            if (choice.groups) {
                for (let i = 0; i < choice.groups.length; i++) {
                    const group = groupMap.get(choice.groups[i]);
                    if (typeof group !== 'undefined') {
                        const elementIndex = group.elements.indexOf(choice.id);
                        if (elementIndex !== -1) group.elements.splice(elementIndex, 1);
                    }
                }
            }
            if (choice.objectDesignGroups) {
                for (let i = 0; i < choice.objectDesignGroups.length; i++) {
                    const dGroup = objectDesignMap.get(choice.objectDesignGroups[i]);
                    if (typeof dGroup !== 'undefined') {
                        const elementIndex = dGroup.elements.indexOf(choice.id);
                        if (elementIndex !== -1) dGroup.elements.splice(elementIndex, 1);
                    }
                }
            }
            if (choice.scores) {
                for (let i = 0; i < choice.scores.length; i++) {
                    const score = choice.scores[i];
                    scoreSet.delete(score.idx);
                }
            }
            if (choice.addons) {
                for (let i = 0; i < choice.addons.length; i++) {
                    const addon = choice.addons[i];
                    if (addon.isSelectable) {
                        if (addon.scores) {
                            for (let j = 0; j < addon.scores.length; j++) {
                                const score = addon.scores[j];
                                scoreSet.delete(score.idx);
                            }
                        }
                        choiceMap.delete(addon.id);
                    }
                }
            }

            activatedMap.delete(choice.id);
            tmpActivatedMap.delete(choice.id);
            row.objects.splice(index, 1);
            choiceMap.delete(choice.id);
            for (let i = idx; i < row.objects.length; i++) {
                row.objects[i].index = i;
            }
        }

function deleteAddon(num: number) {
        const addon = choice.addons[num];

        choice.addons.splice(num, 1);
        if (addon.isSelectable) {
            choiceMap.delete(addon.id);

            let count = 0;
            for (let i = 0; i < choice.addons.length; i++) {
                if (choice.addons[i].isSelectable) count++;
            }

            if (count === 0) {
                delete choice.deselectWhenNoAddon;
            }
        }
    }

function moveChoiceLeft() {
        if (index > 0) {
            [row.objects[index - 1], row.objects[index]] = [row.objects[index], row.objects[index - 1]];
            row.objects[index - 1].index -= 1;
            row.objects[index].index += 1;
        }
    }

function moveChoiceRight() {
        if (index < row.objects.length - 1) {
            [row.objects[index], row.objects[index + 1]] = [row.objects[index + 1], row.objects[index]];
            row.objects[index].index -= 1;
            row.objects[index + 1].index += 1;
        }
    }

function setFilters(bgStyles: BgStyles, filters: Filters) {
        if (isEnabled) {
            if (isActive) {
                if (filterStyle.selFilterBlurIsOn) {
                    filters.blur = ` blur(${filterStyle.selFilterBlur}px)`;
                }
                if (filterStyle.selFilterBrightIsOn) {
                    filters.brightness = ` brightness(${filterStyle.selFilterBright}%)`;
                }
                if (filterStyle.selFilterContIsOn) {
                    filters.contrast = ` contrast(${filterStyle.selFilterCont}%)`;
                }
                if (filterStyle.selFilterGrayIsOn) {
                    filters.grayscale = ` grayscale(${filterStyle.selFilterGray}%)`;
                }
                if (filterStyle.selFilterHueIsOn) {
                    filters.hueRotate = ` hue-rotate(${filterStyle.selFilterHue}deg)`;
                }
                if (filterStyle.selFilterInvertIsOn) {
                    filters.invert = ` invert(${filterStyle.selFilterInvert}%)`;
                }
                if (filterStyle.selFilterOpacIsOn) {
                    filters.opacity = ` opacity(${filterStyle.selFilterOpac}%)`;
                }
                if (filterStyle.selFilterSaturIsOn) {
                    filters.saturate = ` saturate(${filterStyle.selFilterSatur})`;
                }
                if (filterStyle.selFilterSepiaIsOn) {
                    filters.sepia = ` sepia(${filterStyle.selFilterGray}%)`;
                }
                if (filterStyle.selBgColorIsOn) {
                    bgStyles.bgColor = `background-color: ${hexToRgba(filterStyle.selFilterBgColor)};`;
                    if (!filterStyle.selOverlayOnImage) bgStyles.bgImage = '';
                }
                if (objectStyle.objectGradientIsOn && objectStyle.objectGradientOnSelect) {
                    const gradient = objectStyle.objectGradientOnSelect.split(');')[0];
                    bgStyles.bgImage = `background-image: linear-gradient(${gradient});`;
                }
            } else {
                if (filterStyle.unselFilterBlurIsOn) {
                    filters.blur = ` blur(${filterStyle.unselFilterBlur}px)`;
                }
                if (filterStyle.unselFilterBrightIsOn) {
                    filters.brightness = ` brightness(${filterStyle.unselFilterBright}%)`;
                }
                if (filterStyle.unselFilterContIsOn) {
                    filters.contrast = ` contrast(${filterStyle.unselFilterCont}%)`;
                }
                if (filterStyle.unselFilterGrayIsOn) {
                    filters.grayscale = ` grayscale(${filterStyle.unselFilterGray}%)`;
                }
                if (filterStyle.unselFilterHueIsOn) {
                    filters.hueRotate = ` hue-rotate(${filterStyle.unselFilterHue}deg)`;
                }
                if (filterStyle.unselFilterInvertIsOn) {
                    filters.invert = ` invert(${filterStyle.unselFilterInvert}%)`;
                }
                if (filterStyle.unselFilterOpacIsOn) {
                    filters.opacity = ` opacity(${filterStyle.unselFilterOpac}%)`;
                }
                if (filterStyle.unselFilterSaturIsOn) {
                    filters.saturate = ` saturate(${filterStyle.unselFilterSatur})`;
                }
                if (filterStyle.unselFilterSepiaIsOn) {
                    filters.sepia = ` sepia(${filterStyle.unselFilterGray}%)`;
                }
                if (objectStyle.objectGradientIsOn && objectStyle.objectGradient) {
                    const gradient = objectStyle.objectGradient.split(');')[0];
                    bgStyles.bgImage = `background-image: linear-gradient(${gradient});`;
                }
            }
            if (app.isPointerCursor && !choice.isNotSelectable && (!choice.isSelectableMultiple || (choice.allowSelectByClick && choice.multipleUseVariable === 0))) {
                bgStyles.cursor = `cursor: pointer;`;
            }
        } else {
            if (filterStyle.reqFilterBlurIsOn) {
                filters.blur = ` blur(${filterStyle.reqFilterBlur}px)`;
            }
            if (filterStyle.reqFilterBrightIsOn) {
                filters.brightness = ` brightness(${filterStyle.reqFilterBright}%)`;
            }
            if (filterStyle.reqFilterContIsOn) {
                filters.contrast = ` contrast(${filterStyle.reqFilterCont}%)`;
            }
            if (filterStyle.reqFilterGrayIsOn) {
                filters.grayscale = ` grayscale(${filterStyle.reqFilterGray}%)`;
            }
            if (filterStyle.reqFilterHueIsOn) {
                filters.hueRotate = ` hue-rotate(${filterStyle.reqFilterHue}deg)`;
            }
            if (filterStyle.reqFilterInvertIsOn) {
                filters.invert = ` invert(${filterStyle.reqFilterInvert}%)`;
            }
            if (filterStyle.reqFilterOpacIsOn) {
                filters.opacity = ` opacity(${filterStyle.reqFilterOpac}%)`;
            }
            if (filterStyle.reqFilterSaturIsOn) {
                filters.saturate = ` saturate(${filterStyle.reqFilterSatur})`;
            }
            if (filterStyle.reqFilterSepiaIsOn) {
                filters.sepia = ` sepia(${filterStyle.reqFilterGray}%)`;
            }
            if (filterStyle.reqBgColorIsOn) {
                bgStyles.bgColor = `background-color: ${hexToRgba(filterStyle.reqFilterBgColor)};`;
                if (!filterStyle.reqOverlayOnImage) bgStyles.bgImage = '';
            }
            if (objectStyle.objectGradientIsOn && objectStyle.objectGradientOnReq) {
                const gradient = objectStyle.objectGradientOnReq.split(');')[0];
                bgStyles.bgImage = `background-image: linear-gradient(${gradient});`;
            }
        }
    }

function objectWidthClass() {
        if (isSearch) return 'col-sm-6 col-12';
        const objectWidth = row.overrideWidth ? row.objectWidth : (choice.objectWidth || row.objectWidth);
        const objectWidthNum = objectWidthToNum(objectWidth);
        const objectsPerRowNum = app.objectsPerRow === 'col-6' ? 2 : app.objectsPerRow === 'col-4' ? 3 : 4;
        if ($winWidth > 1280) {
            return objectWidth;
        } else if ($winWidth > app.smallerScreenPx) {
            if (app.objectsPerRow === 'default') return fixedWidth(objectWidth);
            switch(objectWidthNum) {
                case 1: return 'col-12';
                case 2: return 'col-6';
                case 3: return objectsPerRowNum > 2 ? 'col-4' : app.objectsPerRow;
                case 4: return objectsPerRowNum > 3 ? 'col-3' : app.objectsPerRow;
                default: return app.objectsPerRow;
            }
        } else if ($winWidth > 480) {
            return objectWidthNum === 1 ? 'col-12' : 'col-6';
        } else {
            return 'col-12';
        }
    }

function toggleAutoActive() {
        if (choice.isAutoActive) {
            delete choice.isNotSelectable;
            delete choice.selectOnce;
            delete choice.isImageUpload;
            delete choice.notDeselectedByClean;
            delete choice.activateAfterReset;
            delete choice.isSelectDelayed;
            delete choice.selectDelayTime;
            if (!choice.isActive) {
                selectObject(choice, row, options);
                if (choice.isActive) choice.forcedActivated = true;
            }
            if (!choice.isActive) tmpActivatedMap.set(choice.id, {multiple: 0});
        } else {
            const newOptions = {...options};

            newOptions.isOverDlg = true;
            newOptions.linkedObjects = [];
            delete choice.isAutoActive;
            delete choice.forcedActivated;
            tmpActivatedMap.delete(choice.id);
            if (choice.isActive) deselectObject(choice, row, newOptions);
