async function handleCounter(isSel: boolean) {
        if (row.isInfoRow) return;

        let origRow = row;

        options.isOverDlg = false;
        options.isOverImg = false;
        options.linkedObjects = [];

        if (row.isResultRow || row.isGroupRow) {
            const cMap = choiceMap.get(choice.id);

            if (typeof cMap !== 'undefined') {
                origRow = cMap.row;
            }
        }

        if (isSel) {
            if (!choice.isNotSelectable) await selectedOneMore(choice, origRow, options);
        } else {
            if (!choice.selectOnce) await selectedOneLess(choice, origRow, options);
        }
    }

function activateObject(e?: MouseEvent) {
        if (row.isInfoRow) return;

        const target = e && e.target ? e.target as HTMLElement : null
        let origRow = row;

        options.isOverDlg = false;
        options.isOverImg = false;
        options.linkedObjects = [];
        if (target && choice.addons && choice.addons.length > 0) {
            if (closestByClassPrefix(target, 'addon-', 'addon')) return;
        }

        if (row.isResultRow || row.isGroupRow) {
            const cMap = choiceMap.get(choice.id);

            if (typeof cMap !== 'undefined') {
                origRow = cMap.row;
            }
        }

        if (choice.isSelectableMultiple) {
            if (choice.allowSelectByClick && choice.multipleUseVariable === 0) {
                if (target) {
                    if (closestByClassPrefix(target, 'multi-', 'choice-')) return;
                }
                selectedOneMore(choice, origRow, options);
            }
        } else {
            if (choice.isActive) {
                if (!choice.selectOnce && !choice.forcedActivated) deselectObject(choice, origRow, options);
            } else if (!choice.isNotSelectable) {
                selectObject(choice, origRow, options);
            }
        }
    }

async function toggleActive() {
        if (row.infoRow) return;
        if (choice.isActive) {
            if (choice.isSelectableMultiple && choice.isMultipleUseVariable) {
                const mul = choice.multipleUseVariable;

                for (let i = 0; i < Math.abs(mul); i++) {
                    if (mul > 0) {
                        await selectedOneLess(choice, row, options);
                    } else if (mul < 0) {
                        await selectedOneMore(choice, row, options);
                    }
                }
            } else if (!choice.selectOnce && !choice.forcedActivated) {
                deselectObject(choice, row, options);
            }
        } else if (!choice.isNotSelectable) {
            if (choice.isSelectableMultiple && choice.isMultipleUseVariable) {
                selectedOneMore(choice, row, options);
            } else {
                selectObject(choice, row, options);
            }
        }
    }

