function saveApp(index: number) {
        app.activated = getSelectedObjectId().split(',');
        const tempApp = JSON.parse(JSON.stringify(app));
        tempApp.version = appVersion;

        const key = `${location.pathname.replace(/\/index\.html$/, '/')}slot-${index}`;
