function calTime(num: number) {
        const h = Math.floor(num / 3600);
        const m = Math.floor((num % 3600) / 60);
        const s = Math.floor(num % 60);
        const rm = String(m).padStart(2, '0');
        const rs = String(s).padStart(2, '0');

        return h > 0 ? `${h}:${rm}:${rs}` : `${rm}:${rs}`;
    }

