            app.backpack[num - 1].index -= 1;
            app.backpack[num].index += 1;
        }
    }

function moveRowDown(num: number) {
        if (num < app.backpack.length - 1) {
            [app.backpack[num], app.backpack[num + 1]] = [app.backpack[num + 1], app.backpack[num]];
            app.backpack[num].index -= 1;
            app.backpack[num + 1].index += 1;
        }
    }

