            updated.style = `${updated.style}${updated.style.endsWith(';') || !updated.style ? '' : ';'}text-align: ${str};`
          }
          updated.style = updated.style.trim()
          return chain().updateAttributes('paragraph', { all: updated, textAlign: str }).run()
        }
      },
    }
  }

