                    for (let k = 0; k < dc.stack; k++) {
                        stackVal = calcStackDiscount(stackVal, dc.operator, dc.value);
                        if (dc.useLowLimit) stackVal = Math.max(stackVal, dc.lowLimit);
                    }
                    stackNum.push(j);
                } else {
                    let dcVal = calcStackDiscount(score.value, dc.operator, dc.value);
                    if (dc.useLowLimit) dcVal = Math.max(dcVal, dc.lowLimit);
                    if (nonStackNum === DISABLED || nonStackVal > dcVal) {
                        nonStackVal = dcVal;
                        nonStackNum = j;
                    }
                }
            }
        }

        if (nonStackNum !== DISABLED) {
            if (stackNum.length > 0) {
                if (nonStackVal > stackVal) {
                    for (let j = 0; j < stackNum.length; j++) {
                        score.discounts[stackNum[j]].state = ACTIVE;
                    }
                    disVal = stackVal;
                } else if (stackVal > nonStackVal) {
                    score.discounts[nonStackNum].state = ACTIVE;
                    disVal = nonStackVal;
                } else {
                    if (stackNum[0] > nonStackNum) {
                        score.discounts[nonStackNum].state = ACTIVE;
                        disVal = nonStackVal;
                    } else {
                        for (let j = 0; j < stackNum.length; j++) {
                            score.discounts[stackNum[j]].state = ACTIVE;
                        }
                        disVal = stackVal;
                    }
                }
            } else {
                score.discounts[nonStackNum].state = ACTIVE;
                disVal = nonStackVal;
            }
            isDiscounted = true;
        } else if (stackNum.length > 0) {
            for (let j = 0; j < stackNum.length; j++) {
                score.discounts[stackNum[j]].state = ACTIVE;
            }
            disVal = stackVal;
            isDiscounted = true;
        }

        if (isDiscounted) {
            disVal = point.allowFloat ? disVal : Math.floor(disVal);
            score.discountScore = disVal;
            if (targetChoice.isActive && disVal !== scoreVal) {
                if (actNum.length > 0) {
                    for (let j = 0; j < actNum.length; j++) {
                        const dc = score.discounts[actNum[j]];
                        if (dc.state !== ACTIVE) {
                            const cMap = choiceMap.get(dc.id);

                            if (typeof cMap !== 'undefined') {
                                countSet.add(cMap.choice);
                            }
                        }
                    }
                }
                score.tmpDisScore = scoreVal - disVal;
                score.isChangeDiscount = true;
            }
            score.appliedDiscount = true;
        } else {
            delete score.appliedDiscount;
        }
    }
    if (countSet.size > 0) {
        const arr = Array.from(countSet);
        for (let i = 0; i < arr.length; i++) {
            const dChoice = arr[i];

            await removeCount(targetChoice, dChoice);
        }
    }
}

async function fillDiscount(localChoice: Choice | SelectableAddon, targetChoice: Choice | SelectableAddon) {
    for (let i = 0; i < targetChoice.scores.length; i++) {
        const score = targetChoice.scores[i];
        const point = pointTypeMap.get(score.id);
        if (typeof point === 'undefined') continue;
        if (typeof score.discounts === 'undefined') continue;

        let disVal = score.value;
        let actVal = score.value;
        const actNum: number[] = [];
        let stackVal = score.value;
        const stackNum: number[] = [];
        let nonStackVal = score.value;
        let nonStackNum = DISABLED;
        let isDiscounted = false;

        for (let j = 0; j < score.discounts.length; j++) {
            const dc = score.discounts[j];
            if (dc.id === localChoice.id) {
                dc.state = FULL;
            } else {
                if (dc.state === ACTIVE) {
                    for (let k = 0; k < dc.stack; k++) {
                        actVal = calcStackDiscount(actVal, dc.operator, dc.value);
                        if (dc.useLowLimit) actVal = Math.max(actVal, dc.lowLimit);
                    }
                    actNum.push(j);
                } else if (dc.state === INACTIVE) {
                    if (dc.stackable) {
                        for (let k = 0; k < dc.stack; k++) {
                            stackVal = calcStackDiscount(stackVal, dc.operator, dc.value);
                            if (dc.useLowLimit) stackVal = Math.max(stackVal, dc.lowLimit);
                        }
                        stackNum.push(j);
                    } else {
                        let dcVal = calcStackDiscount(score.value, dc.operator, dc.value);
                        if (dc.useLowLimit) dcVal = Math.max(dcVal, dc.lowLimit);
                        if (nonStackNum === DISABLED || nonStackVal > dcVal) {
                            nonStackVal = dcVal;
                            nonStackNum = j;
                        }
                    }
                }
            }
        }

        if (actNum.length > 0) {
            disVal = actVal;
            isDiscounted = true;
            if (nonStackNum !== DISABLED) {
                if (actVal > nonStackVal) {
                    for (let j = 0; j < actNum.length; j++) {
                        const aDis = score.discounts[actNum[j]];

                        aDis.state = INACTIVE;
                    }
                    score.discounts[nonStackNum].state = ACTIVE;
                    disVal = actVal;
                }
            }
        } else {
            if (nonStackNum !== DISABLED) {
                if (stackNum.length > 0) {
                    if (nonStackVal > stackVal) {
                        for (let j = 0; j < stackNum.length; j++) {
                            score.discounts[stackNum[j]].state = ACTIVE;
                        }
                        disVal = stackVal;
                    } else if (stackVal > nonStackVal) {
                        score.discounts[nonStackNum].state = ACTIVE;
                        disVal = nonStackVal;
                    } else {
                        if (stackNum[0] > nonStackNum) {
                            score.discounts[nonStackNum].state = ACTIVE;
                            disVal = nonStackVal;
                        } else {
                            for (let j = 0; j < stackNum.length; j++) {
                                score.discounts[stackNum[j]].state = ACTIVE;
                            }
                            disVal = stackVal;
                        }
                    }
                } else {
                    score.discounts[nonStackNum].state = ACTIVE;
                    disVal = nonStackVal;
                }
                isDiscounted = true;
            } else if (stackNum.length > 0) {
                for (let j = 0; j < stackNum.length; j++) {
                    score.discounts[stackNum[j]].state = ACTIVE;
                }
                disVal = stackVal;
                isDiscounted = true;
            }
        }

        if (isDiscounted) {
            disVal = point.allowFloat ? disVal : Math.floor(disVal);
            if (score.discountScore !== disVal) {
                if (targetChoice.isActive) {
                    const scoreVal = typeof score.discountScore !== 'undefined' ? score.discountScore : score.value;
                    score.isChangeDiscount = true;
                    score.tmpDisScore = scoreVal - disVal;
                }
                score.discountScore = disVal;
                score.appliedDiscount = true;
            }
        } else {
            delete score.appliedDiscount;
            delete score.isChangeDiscount;
            delete score.tmpDisScore;
        }
    }
}

export async function deselectDiscount(localChoice: Choice | SelectableAddon, targetChoice: Choice | SelectableAddon) {
    const countNum: number[] = [];
    for (let i = 0; i < targetChoice.scores.length; i++) {
        const score = targetChoice.scores[i];
        const point = pointTypeMap.get(score.id);
        if (typeof point === 'undefined') continue;
        if (typeof score.discounts === 'undefined') continue;

        const idx = score.discounts.findIndex(item => item.id === localChoice.id);
        if (idx === -1) continue;

        const discount = score.discounts[idx];
        const checkMul = targetChoice.isSelectableMultiple && localChoice.useDiscountCount && localChoice.countPerSelection
        const inCount = discount.state === FULL && checkMul && typeof localChoice.appliedDisChoices !== 'undefined' && targetChoice.multipleUseVariable >= localChoice.appliedDisChoices.filter(id => id === targetChoice.id).length;
        let scoreVal = (score.appliedDiscount || discount.state === ACTIVE || inCount) && typeof score.discountScore !== 'undefined' ? score.discountScore : score.value;
        let disVal = score.value;
        let actVal = score.value;
        let actNum: number[] = [];
        let stackVal = score.value;
        let stackNum: number[] = [];
        let nonStackVal = score.value;
        let nonStackNum = DISABLED;

        if (discount.stack > 1) {
            discount.stack -= 1;
            if (discount.state === INACTIVE || (discount.state === FULL && !targetChoice.isSelectableMultiple)) continue;
            if (!discount.stackable) {
                if (discount.count === DISABLED) continue;
                const leng = discount.count * discount.stack;

                if (typeof localChoice.appliedDisChoices !== 'undefined' && localChoice.appliedDisChoices.length > leng) {
                    for (let j = leng; j < localChoice.appliedDisChoices.length; j++) {
                        const id = localChoice.appliedDisChoices[j];

                        if (id === targetChoice.id) {
                            discount.state = FULL;
                            countNum.push(j);
                        }
                    }
                } else {
                    continue;
                }
            }
            if (countNum.length === 0 && discount.state === FULL) continue;
        } else {
            score.discounts.splice(idx, 1);
            if (discount.state === INACTIVE || (discount.state === FULL && !inCount)) {
                if (score.discounts.length === 0) deleteDiscount(score);
                continue;
            }
            if (checkMul && discount.state === FULL && !inCount) scoreVal = score.value;
        }

        for (let j = 0; j < score.discounts.length; j++) {
            const dc = score.discounts[j];

            if (dc.state === ACTIVE) {
                const num = dc.stackable ? dc.stack : 1;
                for (let k = 0; k < num; k++) {
                    actVal = calcStackDiscount(actVal, dc.operator, dc.value);
                    if (dc.useLowLimit) actVal = Math.max(actVal, dc.lowLimit);
                }
                actNum.push(j);
            } else if (dc.state === INACTIVE) {
                if (dc.stackable) {
                    for (let k = 0; k < dc.stack; k++) {
                        stackVal = calcStackDiscount(stackVal, dc.operator, dc.value);
                        if (dc.useLowLimit) stackVal = Math.max(stackVal, dc.lowLimit);
                    }
                    stackNum.push(j);
                } else {
                    let dcVal = calcStackDiscount(score.value, dc.operator, dc.value);
                    if (dc.useLowLimit) dcVal = Math.max(dcVal, dc.lowLimit);
                    if (nonStackVal > dcVal || nonStackNum === DISABLED) {
                        nonStackVal = dcVal;
                        nonStackNum = j;
                    }
                }
            }
        }

        if (actNum.length > 0) {
            if (nonStackNum !== -1) {
                if (actVal > nonStackVal) {
                    for (let j = 0; j < actNum.length; j++) {
                        const aDis = score.discounts[actNum[j]];

                        aDis.state = INACTIVE;
                    }
                    score.discounts[nonStackNum].state = ACTIVE;
                    disVal = nonStackVal;
                }
            } else {
                disVal = actVal;
            }
        } else {
            if (nonStackNum !== DISABLED) {
                if (stackNum.length > 0) {
                    if (nonStackVal > stackVal) {
                        for (let j = 0; j < stackNum.length; j++) {
                            score.discounts[stackNum[j]].state = ACTIVE;
                        }
                        disVal = stackVal;
                    } else if (stackVal > nonStackVal) {
                        score.discounts[nonStackNum].state = ACTIVE;
                        disVal = nonStackVal;
                    } else {
                        if (stackNum[0] > nonStackNum) {
                            score.discounts[nonStackNum].state = ACTIVE;
                            disVal = nonStackVal;
                        } else {
                            for (let j = 0; j < stackNum.length; j++) {
                                score.discounts[stackNum[j]].state = ACTIVE;
                            }
                            disVal = stackVal;
                        }
                    }
                } else {
                    score.discounts[nonStackNum].state = ACTIVE;
                    disVal = nonStackVal;
                }
            } else if (stackNum.length > 0) {
                for (let j = 0; j < stackNum.length; j++) {
                    score.discounts[stackNum[j]].state = ACTIVE;
                }
                disVal = stackVal;
            } else {
                delete score.appliedDiscount;
            }
        }
        if (targetChoice.isActive && scoreVal !== disVal) {
            disVal = point.allowFloat ? disVal : Math.floor(disVal);
            score.discountScore = disVal;
            score.tmpDisScore = scoreVal - disVal;
            score.isChangeDiscount = true;
        }
    }
    for (let i = countNum.length - 1; i >= 0; i--) {
        const idx = countNum[i];
        if (typeof localChoice.appliedDisChoices !== 'undefined') {
            localChoice.appliedDisChoices.splice(idx, 1);
        }
    }
}

export function selectDiscount(localChoice: Choice | SelectableAddon, targetChoice: Choice | SelectableAddon) {
    if (typeof localChoice.discountOperator === 'undefined' || typeof localChoice.discountValue === 'undefined') return;
    for (let i = 0; i < targetChoice.scores.length; i++) {
        const score = targetChoice.scores[i];
        const point = pointTypeMap.get(score.id);
        if (typeof point === 'undefined') continue;
        if (score.isNotDiscountable) continue;
        if (typeof localChoice.discountPointTypes !== 'undefined' && localChoice.discountPointTypes.length > 0 && localChoice.discountPointTypes.indexOf(score.id) === -1) continue;
        if (typeof score.discounts === 'undefined') score.discounts = [];
        if (!score.setValue && (score.isRandom || score.useExpression)) {
            setScoreValue(point, score, targetChoice.isSelectableMultiple && targetChoice.isMultipleUseVariable, targetChoice.multipleUseVariable);
            score.setValue = false;
        }
        score.discountIsOn = true;

        const discount: Discount = {
            id: localChoice.id,
            state: INACTIVE,
            operator: localChoice.discountOperator,
            value: localChoice.discountValue,
            stackable: !!localChoice.stackableDiscount,
            stack: 1,
            count: localChoice.useDiscountCount && localChoice.discountCount ? localChoice.discountCount : DISABLED,
            useLowLimit: !!localChoice.discountLowLimitIsOn,
            lowLimit: localChoice.discountLowLimitIsOn && typeof localChoice.discountLowLimit !== 'undefined' ? localChoice.discountLowLimit : DISABLED,
            showDiscount: !!localChoice.discountShow,
            replaceText: !!localChoice.replaceScoreText,
            afterText: localChoice.discountAfterText || '',
            beforeText: localChoice.discountBeforeText || '',
            consolidate: !!localChoice.discountTextDuplicated,
            hideIcon: !!localChoice.hideScoreIcon,
            hideValue: !!localChoice.hideScoreValue,
        }
        let scoreVal = score.appliedDiscount && typeof score.discountScore !== 'undefined' ? score.discountScore : score.value;
        const idx = score.discounts.findIndex(item => item.id === localChoice.id);
        let disVal = calcStackDiscount(score.value, discount.operator, discount.value);
        if (discount.useLowLimit) disVal = Math.max(disVal, discount.lowLimit);
        let actVal = score.value;
        let actNum: number[] = [];
        let stackVal = score.value;
        let stackNum: number[] = [];
        for (let j = 0; j < score.discounts.length; j++) {
            const dc = score.discounts[j];

            if (dc.state === ACTIVE) {
                const stack = dc.stackable ? dc.stack : 1
                for (let k = 0; k < stack; k++) {
                    actVal = calcStackDiscount(actVal, dc.operator, dc.value);
                    if (dc.useLowLimit) actVal = Math.max(actVal, dc.lowLimit);
                }
                actNum.push(j);
            } else if (dc.state === INACTIVE) {
                if (dc.stackable) {
                    for (let k = 0; k < dc.stack; k++) {
                        stackVal = calcStackDiscount(stackVal, dc.operator, dc.value);
                        if (dc.useLowLimit) stackVal = Math.max(stackVal, dc.lowLimit);
                    }
                    stackNum.push(j);
                }
            }
        }

        if (idx !== DISABLED) {
            const dc = score.discounts[idx];

            if (dc.stackable) {
                for (let j = 0; j < dc.stack; j++) {
                    disVal = calcStackDiscount(disVal, dc.operator, dc.value);
                    if (dc.useLowLimit) disVal = Math.max(disVal, dc.lowLimit);
                }
                if (dc.state === INACTIVE) {
                    if (actVal > disVal) {
                        dc.state = ACTIVE;
                        discount.state = ACTIVE;
                    }
                }
            } else {
                if (dc.state === FULL) {
                    dc.state = ACTIVE;
                    discount.state = ACTIVE;
                }
            }
            dc.stack += 1;
        } else {
            if (actNum.length > 0) {
                if (discount.stackable) {
                    if (score.discounts[actNum[0]].stackable) {
                        disVal = calcStackDiscount(actVal, discount.operator, discount.value);
                        if (discount.useLowLimit) disVal = Math.max(disVal, discount.lowLimit);
                        discount.state = ACTIVE;
                    } else {
                        if (stackNum.length > 0) {
                            disVal = calcStackDiscount(stackVal, discount.operator, discount.value);
                            if (discount.useLowLimit) disVal = Math.max(disVal, discount.lowLimit);

                            if (actVal > disVal) {
                                for (let j = 0; j < stackNum.length; j++) {
                                    score.discounts[stackNum[j]].state = ACTIVE;
                                }
                                discount.state = ACTIVE;
                            }
                        } else {
                            if (actVal > disVal) {
                                discount.state = ACTIVE;
                            }
                        }
                    }
                } else {
                    if (actVal > disVal) {
                        discount.state = ACTIVE;
                    }
                }
                if (discount.state === ACTIVE) {
                    if (!score.discounts[actNum[0]].stackable || !discount.stackable) {
                        for (let j = 0; j < actNum.length; j++) {
                            score.discounts[j].state = INACTIVE;
                        }
                    }
                }
            } else {
                discount.state = ACTIVE;
            }

            score.discounts.push(discount);
        }

        if (discount.state === ACTIVE) {
            disVal = point.allowFloat ? disVal : Math.floor(disVal);
            score.discountScore = disVal;
            score.appliedDiscount = true;
            if (targetChoice.isActive) {
                score.tmpDisScore = scoreVal - disVal;
                score.isChangeDiscount = true;
            }
        }
    }
}

export function expDiscount(point: PointType, score: Score) {
    if (typeof score.discounts === 'undefined') return;

    let disVal = score.value;
    let disCal = score.value;
    for (let i = 0; i < score.discounts.length; i++) {
        const discount = score.discounts[i];

        if (discount.state === ACTIVE) {
            disCal = calcStackDiscount(disCal, discount.operator, discount.value);
            disVal = disCal;
            if (discount.useLowLimit) disVal = Math.max(disVal, discount.lowLimit);
        }
    }
    disVal = point.allowFloat ? disVal : Math.floor(disVal);
    score.discountScore = disVal;
}

export function checkPoints(localChoice: Choice | SelectableAddon, isSel: boolean) {
    let isPositive = true;
    const scoreMap = new Map<string, number>();
    const acMap = new SvelteMap<string, ActivatedMap>([...activatedMap].map(([key, value]) => [key, {...value}]));
    const tChoice = acMap.get(localChoice.id);

    if (isSel) {
        if (localChoice.isSelectableMultiple && localChoice.isMultipleUseVariable) {
            if (typeof tChoice !== 'undefined') {
                tChoice.multiple += 1;
            } else {
                acMap.set(localChoice.id, { multiple: localChoice.multipleUseVariable + 1 });
            }
        } else {
            acMap.set(localChoice.id, { multiple: 0 });
        }
    } else {
        if (typeof tChoice !== 'undefined') {
            acMap.delete(localChoice.id);
        }
    }

    for (let i = 0; i < localChoice.scores.length; i++) {
        const score = localChoice.scores[i];
        if (isSel && !checkRequirements(score.requireds)) continue;

        const isActive = localChoice.isSelectableMultiple && localChoice.isMultipleUseVariable && score.isActiveMul ? score.isActiveMul[localChoice.multipleUseVariable] : score.isActive;
        if (!isSel && !isActive) continue;

        const point = pointTypeMap.get(score.id);
        if (typeof point === 'undefined') continue;

        if (isSel) {
            if (score.useExpression) {
                if (score.isRandom && score.expMinValue && score.expMaxValue) {
                    try {
                        const minReplaced = score.expMinValue.replace(/\{([^{}]+)\}/g, (_, vStr) => {
                            const vScore = scoreMap.get(vStr);
                            if (typeof vScore !== 'undefined') {
                                return `${vScore}`;
                            } else {
                                const vPoint = pointTypeMap.get(vStr);
                                if (typeof vPoint !== 'undefined') {
                                    return `${vPoint.startingSum}`;
                                }
                            }
                            throw new Error(`Undefined variable: "${vStr}"`);
                        });
                        const maxReplaced = score.expMaxValue.replace(/\{([^{}]+)\}/g, (_, vStr) => {
                            const vScore = scoreMap.get(vStr);
                            if (typeof vScore !== 'undefined') {
                                return `${vScore}`;
                            } else {
                                const vPoint = pointTypeMap.get(vStr);
                                if (typeof vPoint !== 'undefined') {
                                    return `${vPoint.startingSum}`;
                                }
                            }
                            throw new Error(`Undefined variable: "${vStr}"`);
                        });
                        const minValue = evaluate(minReplaced);
                        const maxValue = evaluate(maxReplaced);
                        score.value = Math.floor(Math.random() * (maxValue - minValue + 1)) + minValue;
                        score.value = point.allowFloat ? score.value : Math.floor(score.value);
                        score.setValue = true;
                        if (localChoice.isSelectableMultiple && localChoice.isMultipleUseVariable) {
                            if (typeof score.mulValue === 'undefined') score.mulValue = [];
                            score.mulValue.splice(localChoice.multipleUseVariable, 1, score.value);
                        }
                    } catch (e) {
                        console.error(e);
                    }
                } else if (score.expValue) {
                    try {
                        const replaced = score.expValue.replace(/\{([^{}]+)\}/g, (_, vStr) => {
                            const vScore = scoreMap.get(vStr);
                            if (typeof vScore !== 'undefined') {
                                return `${vScore}`;
                            } else {
                                const vPoint = pointTypeMap.get(vStr);
                                if (typeof vPoint !== 'undefined') {
                                    return `${vPoint.startingSum}`;
                                }
                            }
                            throw new Error(`Undefined variable: "${vStr}"`);
                        });
                        score.value = evaluate(replaced);
                        score.value = point.allowFloat ? score.value : Math.floor(score.value);
                        score.setValue = true;
                        if (localChoice.isSelectableMultiple && localChoice.isMultipleUseVariable) {
                            if (typeof score.mulValue === 'undefined') score.mulValue = [];
                            score.mulValue.splice(localChoice.multipleUseVariable, 1, score.value);
                        }
                    } catch (e) {
                        console.error(e);
                    }
                }
            } else if (score.isRandom) {
                setScoreValue(point, score, localChoice.isSelectableMultiple && localChoice.isMultipleUseVariable, localChoice.multipleUseVariable);
            }
        }

        let scoreVal = score.discountIsOn && typeof score.discountScore !== 'undefined' && score.appliedDiscount ? score.discountScore : score.value;

        if (score.multiplyByTimes) {
            scoreVal = scoreVal * (Math.abs(localChoice.multipleUseVariable) + 1);
        }

        const data = scoreMap.get(score.id);

        if (typeof data !== 'undefined') {
            const val = isSel ? data - scoreVal : data + scoreVal;
            scoreMap.set(score.id, val);
        } else {
            const val = isSel ? point.startingSum - scoreVal : point.startingSum + scoreVal;
            scoreMap.set(score.id, val);
        }
    }

    for (const [id, val] of scoreMap) {
        const point = pointTypeMap.get(id);

        if (typeof point !== 'undefined') {
            if (point.belowZeroNotAllowed && val < 0) {
                isPositive = false;
                break;
            }
        }
    }

    if (localChoice.multiplyPointtypeIsOnCheck && typeof localChoice.pointTypeToMultiply !== 'undefined') {
        let idx = 0;
        for (let i = 0; i < localChoice.pointTypeToMultiply.length; i++) {
            let point = pointTypeMap.get(localChoice.pointTypeToMultiply[i]);

            if (typeof point !== 'undefined' && point.belowZeroNotAllowed) {
                let pointVal = point.startingSum;
                for (let j = mdObjects.length - 1; j >= 0; j--) {
                    let mdChoice = mdObjects[j];

                    if (mdChoice.multiplyPointtypeIsOnCheck && typeof mdChoice.startingSumAtMultiply !== 'undefined') {
                        let val = mdChoice.startingSumAtMultiply[i].value * mdChoice.startingSumAtMultiply[i].calcVal;
                        val = point.allowFloat ? val : Math.floor(val);
                        pointVal -= val;
                        pointVal += mdChoice.startingSumAtMultiply[i].value;
                    }
                    if (mdChoice.dividePointtypeIsOnCheck && typeof mdChoice.startingSumAtDivide !== 'undefined') {
                        let val = mdChoice.startingSumAtDivide[i].value / mdChoice.startingSumAtDivide[i].calcVal;
                        val = point.allowFloat ? val : Math.floor(val);
                        pointVal -= val;
                        pointVal += mdChoice.startingSumAtDivide[i].value;
                    }
                    if (mdChoice.setPointtypeIsOnCheck && typeof mdChoice.startingSumAtSet !== 'undefined') {
                        pointVal = mdChoice.startingSumAtSet[i].value;
                    }
                    if (mdChoice.id === localChoice.id) {
                        idx = j;
                        break;
                    }
                }
                for (let j = idx + 1;  j < mdObjects.length; j++) {
                    let mdChoice = mdObjects[j];

                    if (mdChoice.multiplyPointtypeIsOnCheck && typeof mdChoice.startingSumAtMultiply !== 'undefined') {
                        pointVal *= mdChoice.startingSumAtMultiply[i].calcVal;
                        pointVal = point.allowFloat ? pointVal : Math.floor(pointVal);
                    } 
                    if (mdChoice.dividePointtypeIsOnCheck && typeof mdChoice.startingSumAtDivide !== 'undefined') {
                        pointVal /= mdChoice.startingSumAtDivide[i].calcVal;
                        pointVal = point.allowFloat ? pointVal : Math.floor(pointVal);
                    }
                    if (mdChoice.setPointtypeIsOnCheck && typeof mdChoice.startingSumAtSet !== 'undefined') {
                        pointVal = mdChoice.startingSumAtSet[i].calcVal;
                        pointVal = point.allowFloat ? pointVal : Math.floor(pointVal);
                    }
                }

                isPositive = isPositive && pointVal >= 0;
            }
