    options.isForced = true;
    options.isAllowDeselect = localChoice.isAllowDeselect;

    if (fChoice.activateOtherChoice && typeof fChoice.activateThisChoice !== 'undefined' && options.linkedObjects.indexOf(localChoice.id) === -1 && fChoice.activateThisChoice.split(',').some(item => item.split('/ON#')[0] === localChoice.id)) {
        options.linkedObjects.push(localChoice.id);
        options.isLinked = true;
    }
    if (fChoice.isSelectableMultiple) {
        if (fChoice.isMultipleUseVariable && typeof fChoice.numMultipleTimesMinus !== 'undefined' && typeof fChoice.numMultipleTimesPluss !== 'undefined') {
            if (num > 0) {
                for (let i = 0; i < num; i++) {
                    await selectedOneMore(fChoice, fRow, options);
                }
            } else if (num < 0) {
                for (let i = 0; i > (num * -1); i++) {
                    await selectedOneLess(fChoice, fRow, options);
                }
            }
        }
    } else {
        if (!fChoice.isActive) {
            await selectObject(fChoice, fRow, options);
        } else {
            if (!options.isAllowDeselect) {
                fChoice.forcedActivated = true;
                if (typeof fChoice.activatedFrom === 'undefined') fChoice.activatedFrom = 0;
                fChoice.activatedFrom += 1;
            }
        }
    }
}

async function deselectTempActivate(localChoice: Choice | SelectableAddon, fChoice: Choice | SelectableAddon, num: number) {
    const tmpAct = tmpActivatedMap.get(fChoice.id);
    if (typeof tmpAct === 'undefined') return;

    let tmpNum = 0;

    if (fChoice.isSelectableMultiple && fChoice.isMultipleUseVariable) {
        tmpNum = tmpAct.multiple - num;
        if (tmpNum === 0) {
            tmpActivatedMap.delete(fChoice.id);
        } else {
            tmpActivatedMap.set(fChoice.id, {multiple: tmpNum, isAllowDeselect: localChoice.isAllowDeselect || false});
        }
    } else {
        if (typeof tmpAct.activatedFrom !== 'undefined') {
            tmpAct.activatedFrom -= 1;
        }
        if (!tmpAct.activatedFrom && !fChoice.isAutoActive) {
            tmpActivatedMap.delete(fChoice.id);
        }
    }
}

async function deselectForceActivate(localChoice: Choice | SelectableAddon, fChoice: Choice | SelectableAddon, fRow: Row, num: number, options: ChoiceOptions) {
    options.isOverDlg = true;
    options.isOverImg = true;
    if (fChoice.activateOtherChoice && typeof fChoice.activateThisChoice !== 'undefined' && options.linkedObjects.indexOf(localChoice.id) === -1 && fChoice.activateThisChoice.split(',').some(item => item.split('/ON#')[0] === localChoice.id)) {
        options.linkedObjects.push(localChoice.id);
    }
    if (fChoice.isActive) {
        if (fChoice.isSelectableMultiple) {
            if (fChoice.isMultipleUseVariable && typeof fChoice.numMultipleTimesMinus !== 'undefined' && typeof fChoice.numMultipleTimesPluss !== 'undefined') {
                if (num > 0) {
                    for (let i = 0; i < num; i++) {
                        if (!localChoice.isAllowDeselect) fChoice.numMultipleTimesMinus -= 1;
                        if (!localChoice.isNotDeactivate) {
                            if (fChoice.isDeselectDelayed || fChoice.isFadeTransition) {
                                selectedOneLess(fChoice, fRow, options);
                            } else {
                                await selectedOneLess(fChoice, fRow, options);
                            }
                        }
                    }
                } else if (num < 0) {
                    for (let i = 0; i > (num * -1); i++) {
                        if (!localChoice.isAllowDeselect) fChoice.numMultipleTimesPluss += 1;
                        if (!localChoice.isNotDeactivate) {
                            if (fChoice.isDeselectDelayed || fChoice.isFadeTransition) {
                                selectedOneMore(fChoice, fRow, options);
                            } else {
                                await selectedOneMore(fChoice, fRow, options);
                            }
                        }
                    }
                }
            }
        } else {
            if (typeof fChoice.activatedFrom !== 'undefined') {
                fChoice.activatedFrom -= 1;
                if (fChoice.activatedFrom <= 0 || options.linkedObjects.indexOf(localChoice.id) !== -1) {
                    delete fChoice.activatedFrom;
                    delete fChoice.forcedActivated;
                    if (!localChoice.isNotDeactivate) {
                        if (fChoice.isDeselectDelayed || fChoice.isFadeTransition) {
                            deselectObject(fChoice, fRow, options);
                        } else {
                            await deselectObject(fChoice, fRow, options);
                        }
                    }
                }
            } else {
                delete fChoice.forcedActivated;
                if (!localChoice.isNotDeactivate && fChoice.isActive) {
                    if (fChoice.isDeselectDelayed || fChoice.isFadeTransition) {
                        deselectObject(fChoice, fRow, options);
                    } else {
                        await deselectObject(fChoice, fRow, options);
                    }
                }
            }
        }
    } else {
        await deselectTempActivate(localChoice, fChoice, num);
    }
}

async function selectForceRandomActivate(localChoice: Choice | SelectableAddon, options: ChoiceOptions) {
    if (typeof localChoice.activateThisChoice !== 'undefined') {
        let forceList = localChoice.activateThisChoice.split(',');
        let listMap = new Map<string, number>();
        for (let i = 0; i < forceList.length; i++) {
            let [key, val = '0'] = forceList[i].split('/ON#');
            let num = parseInt(val);
            let group = groupMap.get(key);
            if (typeof group !== 'undefined') {
                for (let j = 0; j < group.elements.length; j++) {
                    const cMap = choiceMap.get(group.elements[j]);

                    if (typeof cMap !== 'undefined') {
                        const gChoice = cMap.choice;
                        const reqCheck = gChoice.isSelectableMultiple && gChoice.isMultipleUseVariable && typeof gChoice.numMultipleTimesPluss !== 'undefined' && gChoice.numMultipleTimesPluss >= gChoice.multipleUseVariable + num && !gChoice.isInfoRow && !gChoice.isNotSelectable && checkRequirements(gChoice.requireds);
                        if (!activatedMap.has(gChoice.id) || reqCheck) {
                            listMap.set(gChoice.id, num);
                        }
                    }
                }
            } else {
                const cMap = choiceMap.get(key);

                if (typeof cMap !== 'undefined') {
                    const lChoice = cMap.choice;
                    const reqCheck = lChoice.isSelectableMultiple && lChoice.isMultipleUseVariable && typeof lChoice.numMultipleTimesPluss !== 'undefined' && lChoice.numMultipleTimesPluss >= lChoice.multipleUseVariable + num && !lChoice.isInfoRow && !lChoice.isNotSelectable && checkRequirements(lChoice.requireds);

                    if (!activatedMap.has(key) || reqCheck) {
                        listMap.set(key, num);
                    }
                }
            }
        }
        let listArray = [...listMap.keys()];
        let actNum = Math.min(listArray.length, localChoice.numActivateRandom || 0);
        let repeatNum = actNum;
        for (let i = listArray.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [listArray[i], listArray[j]] = [listArray[j], listArray[i]];
        }
        let result: string[] = [];
        for (let i = 0; i < actNum;) {
            const id = listArray[i];
            const cMap = choiceMap.get(id);
            if (typeof cMap !== 'undefined') {
                const rndRow = cMap.row;
                const rndChoice = cMap.choice;
                const choiceNum = listMap.get(id) || 0;
                const rndNum = rndChoice.multipleUseVariable;

                await selectForceActivate(localChoice, rndChoice, rndRow, choiceNum, options);
                if (!rndChoice.isActive || (rndChoice.isSelectableMultiple && rndChoice.isMultipleUseVariable && rndChoice.multipleUseVariable === rndNum)) {
                    if (result.length < actNum && listArray.length > repeatNum) {
                        listArray[i] = listArray[repeatNum++];
                        if (typeof rndChoice.activatedFrom !== 'undefined') {
                            rndChoice.activatedFrom -= 1;
                            if (rndChoice.activatedFrom === 0) tmpActivatedMap.delete(rndChoice.id);
                        }
                        continue;
                    } else {
                        break;
                    }
                }
                let item = choiceNum > 0 ? `${id}/ON#${choiceNum}` : id;
                result.push(item);
            }
            i++;
        }

        if (localChoice.isSelectableMultiple) {
            if (typeof localChoice.activatedRandomMul === 'undefined') localChoice.activatedRandomMul = [];
            localChoice.activatedRandomMul[localChoice.multipleUseVariable - 1] = [...result];
        } else {
            localChoice.activatedRandom = [...result];
        }
    }
}

async function removeCount(localChoice: Choice | SelectableAddon, dChoice: Choice | SelectableAddon) {
    if (typeof dChoice.appliedDisChoices === 'undefined') return;

    const idx = dChoice.appliedDisChoices.indexOf(localChoice.id);
    if (idx === DISABLED) return;

    dChoice.appliedDisChoices.splice(idx, 1);
    const dList = new Set(dChoice.appliedDisChoices);
    const nList = new Set();
    if (dChoice.isDisChoices) {
        if (typeof dChoice.discountRows !== 'undefined') {
            for (let i = 0; i < dChoice.discountRows.length; i++) {
                const tRow = rowMap.get(dChoice.discountRows[i]);
                if (typeof tRow !== 'undefined') {
                    for (let j = 0; j < tRow.objects.length; j++) {
                        const tChoice = tRow.objects[j];
                        if (!dList.has(tChoice.id) || (tChoice.isSelectableMultiple && dChoice.countPerSelection)) {
                            await emptyDiscount(dChoice, tChoice);
                            nList.add(tChoice.id);
                        }
                    }
                }
            }
        }
        if (typeof dChoice.discountChoices !== 'undefined') {
            for (let i = 0; i < dChoice.discountChoices.length; i++) {
                const cMap = choiceMap.get(dChoice.discountChoices[i]);
                if (typeof cMap !== 'undefined') {
                    const tChoice = cMap.choice;

                    if (!nList.has(tChoice.id) && !dList.has(tChoice.id) || (tChoice.isSelectableMultiple && dChoice.countPerSelection)) {
                        await emptyDiscount(dChoice, tChoice);
                    }
                }
            }
        }
    } else {
        if (typeof dChoice.discountGroups !== 'undefined') {
            for (let i = 0; i < dChoice.discountGroups.length; i++) {
                const groupData = groupMap.get(dChoice.discountGroups[i]);
                if (typeof groupData !== 'undefined') {
                    for (let j = 0; j < groupData.elements.length; j++) {
                        const cMap = choiceMap.get(groupData.elements[j]);
                        if (typeof cMap !== 'undefined') {
                            const tChoice = cMap.choice;

                            if (!dList.has(tChoice.id) || (tChoice.isSelectableMultiple && dChoice.countPerSelection)) {
                                await emptyDiscount(dChoice, tChoice);
                            }
                        }
                    }
                }
            }
        }
    }
}

async function addCount(localChoice: Choice | SelectableAddon, dChoice: Choice | SelectableAddon) {
    if (!dChoice.discountCount) return;

    let count = dChoice.discountCount * (dChoice.isSelectableMultiple && dChoice.isMultipleUseVariable ? dChoice.multipleUseVariable : 1);

    if (typeof dChoice.appliedDisChoices === 'undefined') dChoice.appliedDisChoices = [];

    if (!localChoice.isSelectableMultiple && dChoice.appliedDisChoices.indexOf(localChoice.id) !== DISABLED) return;

    if (localChoice.isSelectableMultiple && dChoice.countPerSelection) {
        if (dChoice.appliedDisChoices.length < count && dChoice.appliedDisChoices.filter(id => id === localChoice.id).length < localChoice.multipleUseVariable) dChoice.appliedDisChoices.push(localChoice.id);
    } else {
        if (dChoice.appliedDisChoices.indexOf(localChoice.id) !== DISABLED) return;
        dChoice.appliedDisChoices.push(localChoice.id);
    }

    if (dChoice.appliedDisChoices.length < count) return;

    const dList = new Set(dChoice.appliedDisChoices);
    const nList = new Set();
    if (dChoice.isDisChoices) {
        if (typeof dChoice.discountRows !== 'undefined') {
            for (let i = 0; i < dChoice.discountRows.length; i++) {
                const tRow = rowMap.get(dChoice.discountRows[i]);
                if (typeof tRow !== 'undefined') {
                    for (let j = 0; j < tRow.objects.length; j++) {
                        const tChoice = tRow.objects[j];
                        if (!dList.has(tChoice.id) || (tChoice.isSelectableMultiple && dChoice.countPerSelection)) {
                            await fillDiscount(dChoice, tChoice);
                            nList.add(tChoice.id);
                        }
                    }
                }
            }
        }
        if (typeof dChoice.discountChoices !== 'undefined') {
            for (let i = 0; i < dChoice.discountChoices.length; i++) {
                const cMap = choiceMap.get(dChoice.discountChoices[i]);
                if (typeof cMap !== 'undefined') {
                    const tChoice = cMap.choice;

                    if (!nList.has(tChoice.id) && !dList.has(tChoice.id) || (tChoice.isSelectableMultiple && dChoice.countPerSelection)) {
                        await fillDiscount(dChoice, tChoice);
                    }
                }
            }
        }
    } else {
        if (typeof dChoice.discountGroups !== 'undefined') {
            for (let i = 0; i < dChoice.discountGroups.length; i++) {
                const groupData = groupMap.get(dChoice.discountGroups[i]);
                if (typeof groupData !== 'undefined') {
                    for (let j = 0; j < groupData.elements.length; j++) {
                        const cMap = choiceMap.get(groupData.elements[j]);
                        if (typeof cMap !== 'undefined') {
                            const tChoice = cMap.choice;

                            if (!dList.has(tChoice.id) || (tChoice.isSelectableMultiple && dChoice.countPerSelection)) {
                                await fillDiscount(dChoice, tChoice);
                            }
                        }
                    }
                }
            }
        }
    }
}

async function updateCount(localChoice: Choice | SelectableAddon, dChoice: Choice | SelectableAddon) {
    if (typeof dChoice.appliedDisChoices === 'undefined') return;

    let totalNum = 0;
    let appliedNum = 0;

    for (let i = 0; i < localChoice.scores.length; i++) {
        const score = localChoice.scores[i];
        if (typeof score.discounts === 'undefined' || score.discounts.length === 0) continue;

        for (let j = 0; j < score.discounts.length; j++) {
            const dc = score.discounts[j];

            if (dc.id === dChoice.id) {
                if (dc.state === ACTIVE) appliedNum += 1;
                totalNum += 1;
            }
        }
    }

    if (appliedNum === totalNum) await removeCount(localChoice, dChoice);
}

async function deselectUpdateScore(localChoice: Choice | SelectableAddon, localRow: Row, tmpScores: TempScore, count: number, changedScores = new Set<string>(), scoreUpdate: string[] = [], options: ChoiceOptions) {
    const activated = Array.from(activatedMap.keys());
    const newOptions = {...options};
    newOptions.isOverDlg = true;
    newOptions.isOverImg = true;

    for (let i = 0; i < activated.length; i++) {
        const id = activated[i];
        const cMap = choiceMap.get(id);
        if (typeof cMap === 'undefined') continue;

        const aRow = cMap.row;
        const aChoice = cMap.choice;
        if (!aChoice.isActive) continue;

        const thisTmpScores = new SvelteMap<string, number>();
        const addSet = new Set<Choice | SelectableAddon>();
        const removeSet = new Set<Choice | SelectableAddon>();
        let isChanged = false;
        for (let j = 0; j < aChoice.scores.length; j++) {
            const aScore = aChoice.scores[j];
            if (aScore.isNotRecalculatable) continue;

            const point = pointTypeMap.get(aScore.id);
            if (typeof point === 'undefined') continue;

            const isActive = aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable ? true : aScore.isActive;

            if (aScore.isChangeDiscount && isActive && typeof aScore.tmpDisScore !== 'undefined') {
                if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                    let mul = aChoice.multipleUseVariable;
                    let isChangedMul = false;
                    let totalScore = 0;

                    if (aScore.discounts) {
                        for (let k = 0; k < aScore.discounts.length; k++) {
                            const dc = aScore.discounts[k];
                            if (dc.state !== INACTIVE) {
                                const dMap = choiceMap.get(dc.id);

                                if (typeof dMap !== 'undefined') {
                                    const dChoice = dMap.choice;

                                    if (typeof dChoice.appliedDisChoices !== 'undefined' && dChoice.countPerSelection) {
                                        const count = dChoice.appliedDisChoices.filter(id => id === aChoice.id).length;
                                        if (count === 0) continue;
                                        mul = mul - count;
                                        break;
                                    }
                                }
                            }
                        }
                    }
                    for (let k = mul - 1; k >= 0; k--) {
                        if (!aChoice.isActive || !aScore.isActiveMul) break;
                        if (!aScore.isActiveMul[k]) continue;
                        let tmpScore = aScore.multiplyByTimes ? aScore.tmpDisScore * (k + 1) : aScore.tmpDisScore;
                        if (point.belowZeroNotAllowed && point.startingSum + tmpScore < 0) {
                            if (aChoice.forcedActivated) {
                                aChoice.numMultipleTimesMinus--;
                                await selectedOneLess(aChoice, aRow, newOptions);

                                const tmpAct = tmpActivatedMap.get(aChoice.id);
                                if (typeof tmpAct !== 'undefined') {
                                    tmpAct.multiple += 1;
                                } else {
                                    tmpActivatedMap.set(aChoice.id, {multiple: 1, activatedFrom: aChoice.activatedFrom});
                                }
                            } else {
                                await selectedOneLess(aChoice, aRow, newOptions);
                            }
                            isChangedMul = true;
                            break;
                        } else {
                            point.startingSum += tmpScore;
                            totalScore += tmpScore;
                            isChangedMul = true;
                        }
                    }

                    delete aScore.isChangeDiscount;
                    delete aScore.tmpDisScore;

                    if (!aChoice.isActive) break;

                    thisTmpScores.set(aScore.id, totalScore);

                    if (isChangedMul) {
                        isChanged = localChoice.id !== aChoice.id;
                    }
                } else if (!aChoice.isSelectableMultiple) {
                    if (point.belowZeroNotAllowed && point.startingSum + aScore.tmpDisScore < 0) {
                        if (aChoice.forcedActivated) {
                            delete aChoice.forcedActivated;
                            tmpActivatedMap.set(aChoice.id, {multiple: aChoice.multipleUseVariable, activatedFrom: aChoice.activatedFrom});
                        }
                        await deselectObject(aChoice, aRow, newOptions);
                    } else {
                        point.startingSum += aScore.tmpDisScore;
                        thisTmpScores.set(aScore.id, aScore.tmpDisScore);
                        delete aScore.isChangeDiscount;
                        delete aScore.tmpDisScore;
                    }

                    if (!aChoice.isActive) break;

                    isChanged = localChoice.id !== aChoice.id;
                }

                if (isChanged) {
                    if (aScore.appliedDiscount && typeof aScore.discounts !== 'undefined') {
                        for (let k = 0; k < aScore.discounts.length; k++) {
                            const dc = aScore.discounts[k];

                            if (dc.state === ACTIVE && dc.count !== DISABLED) {
                                const cMap = choiceMap.get(dc.id);

                                if (typeof cMap !== 'undefined') {
                                    const dChoice = cMap.choice;

                                    if (!deselectQue.has(dChoice.id)) addSet.add(dChoice);
                                }
                            }
                        }
                    }
                }
            } else {
                delete aScore.isChangeDiscount;
                delete aScore.tmpDisScore;
            }
            if (!changedScores.has(aScore.idx)) {
                const hasScore = localChoice.scores.length > 0;
                const scoreLeng = localChoice.scores.length || 1;
                for (let k = 0; k < scoreLeng; k++) {
                    if (!aChoice.isActive) break;

                    const lScore = hasScore ? localChoice.scores[k] : null;
                    const tmpScore = lScore ? (tmpScores.get(lScore.id) || 0) : 0;
                    const lPoint = lScore ? pointTypeMap.get(lScore.id) : null;
                    if (hasScore && !lPoint) continue;

                    const afterDeselected = checkRequirements(aScore.requireds);
                    const tmpActivated = new SvelteMap<string, ActivatedMap>([...activatedMap].map(([key, value]) => [key, {...value}]));
                    const isMultiple = localChoice.isSelectableMultiple && localChoice.isMultipleUseVariable;
                    if (isMultiple) {
                        if (localChoice.multipleUseVariable === -1) {
                            tmpActivated.delete(localChoice.id);
                            localRow.currentChoices -= 1;
                        } else {
                            tmpActivated.set(localChoice.id, {multiple: localChoice.multipleUseVariable + 1});
                            if (localChoice.multipleUseVariable === 0) {
                                localRow.currentChoices += 1;
                            }
                        }
                    } else {
                        tmpActivated.set(localChoice.id, {multiple: 0});
                        localRow.currentChoices += 1;
                    }
                    if (lPoint) lPoint.startingSum += tmpScore;
                    const beforeDeselected = checkRequirements(aScore.requireds, tmpActivated);
                    if (isMultiple) {
                        if (localChoice.multipleUseVariable === -1) {
                            localRow.currentChoices += 1;
                        } else if (localChoice.multipleUseVariable === 0) {
                            localRow.currentChoices -= 1;
                        }
                    } else {
                        localRow.currentChoices -= 1;
                    }
                    if (lPoint) lPoint.startingSum -= tmpScore;
                    if (beforeDeselected === afterDeselected) continue;

                    if (!aScore.setValue) setScoreValue(point, aScore, aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable, aChoice.multipleUseVariable);
                    let scoreVal = aScore.appliedDiscount && typeof aScore.discountScore !== 'undefined' ? aScore.discountScore : aScore.value;
                    scoreVal = point.allowFloat ? scoreVal : Math.floor(scoreVal);
                    if (beforeDeselected) {
                        if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                            const mul = aChoice.multipleUseVariable;

                            for (let l = mul - 1; l >= 0; l--) {
                                if (typeof aScore.isActiveMul !== 'undefined' && aScore.isActiveMul[l]) {
                                    const sValue = aScore.multiplyByTimes ? scoreVal * (l + 1) : scoreVal;
                                    if (point.belowZeroNotAllowed && point.startingSum + sValue < 0) {
                                        if (aChoice.forcedActivated) {
                                            aChoice.numMultipleTimesMinus--;
                                            await selectedOneLess(aChoice, aRow, newOptions);

