                            }
                        }
                        if (aScore.appliedDiscount && typeof aScore.discounts !== 'undefined') {
                            for (let k = 0; k < aScore.discounts.length; k++) {
                                const dc = aScore.discounts[k];

                                if (dc.state === ACTIVE && dc.count !== DISABLED) {
                                    const cMap = choiceMap.get(dc.id);

                                    if (typeof cMap !== 'undefined') {
                                        const dChoice = cMap.choice;

                                        addSet.add(dChoice);
                                    }
                                }
                            }
                        }
                    }
                    if (!isChanged) {
                        isChanged = true;
                    }
                    changedScores.add(aScore.idx);
                    if (!aChoice.isActive) break;
                }
            }
            if (!isChanged) {
                if (aScore.useExpression) {
                    const oldVal = aScore.value;

                    setScoreValue(point, aScore, aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable, aChoice.multipleUseVariable - 1);
                    if (oldVal !== aScore.value) {
                        let expVal = oldVal - aScore.value;
                        if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                            const mul = aChoice.multipleUseVariable;

                            for (let l = mul - 1; l >= 0; l--) {
                                if (typeof aScore.isActiveMul !== 'undefined' && aScore.isActiveMul[l]) {
                                    const sValue = aScore.multiplyByTimes ? expVal * (l + 1) : expVal;
                                    if (point.belowZeroNotAllowed && point.startingSum + sValue < 0) {
                                        if (aChoice.forcedActivated) {
                                            aChoice.numMultipleTimesMinus--;
                                            await selectedOneLess(aChoice, aRow, newOptions);

                                            const tmpAct = tmpActivatedMap.get(aChoice.id);
                                            if (typeof tmpAct !== 'undefined') {
                                                tmpAct.multiple += 1;
                                            } else {
                                                tmpActivatedMap.set(aChoice.id, {multiple: 1, activatedFrom: aChoice.activatedFrom});
                                            }
                                        } else {
                                            await selectedOneLess(aChoice, aRow, newOptions);
                                        }
                                        isChanged = true;
                                        changedScores.add(aScore.idx);
                                        break;
                                    } else {
                                        point.startingSum += sValue;
                                        thisTmpScores.set(aScore.id, sValue);
                                        isChanged = true;
                                        changedScores.add(aScore.idx);
                                    }
                                }
                            }
                        } else if (!aChoice.isSelectableMultiple) {
                            if (aScore.isActive) {
                                if (point.belowZeroNotAllowed && point.startingSum + expVal < 0) {
                                    if (aChoice.forcedActivated) {
                                        delete aChoice.forcedActivated;
                                        tmpActivatedMap.set(aChoice.id, {multiple: aChoice.multipleUseVariable, activatedFrom: aChoice.activatedFrom});
                                    }
                                    await deselectObject(aChoice, aRow, newOptions);
                                } else {
                                    point.startingSum += expVal;
                                    thisTmpScores.set(aScore.id, expVal);
                                }
                                isChanged = true;
                                changedScores.add(aScore.idx);
                            }
                        }
                    }
                }
            }
        }
        if (removeSet.size > 0) {
            const arr = Array.from(removeSet);

            for (let i = 0; i < arr.length; i++) {
                const dChoice = arr[i];

                if (!addSet.has(dChoice)) await updateCount(aChoice, dChoice);
            }
        }
        if (addSet.size > 0) {
            const arr = Array.from(addSet);

            for (let i = 0; i < arr.length; i++) {
                const dChoice = arr[i];

                await addCount(aChoice, dChoice);
            }
        }
        if (isChanged) {
            scoreUpdate.length === 0 ? scoreUpdate.push(`Scores Updated On: ${aChoice.title}`) : scoreUpdate.push(`, ${aChoice.title}`);
            await deselectUpdateScore(aChoice, aRow, thisTmpScores, count + 1, changedScores, scoreUpdate, options);
        }
    }
    if (count === 0) {
        if (scoreUpdate.length > 0 && !app.hideScoresUpdated) {
            const tempDiv = document.createElement('div');

            tempDiv.innerHTML = scoreUpdate.join('');
            snackbarVariables.labelText = tempDiv.textContent || '';
            snackbarVariables.isOpen = true;
        }
        scoreUpdate.splice(0);
    }
}

export async function selectUpdateScore(localChoice: Choice | SelectableAddon | null, localRow: Row, tmpScores: TempScore, count: number, changedScores = new Set<string>(), scoreUpdate: string[] = [], options: ChoiceOptions) {
    const activated = Array.from(activatedMap.keys());

    for (let i = 0; i < activated.length; i++) {
        const id = activated[i];
        const cMap = choiceMap.get(id);
        if (typeof cMap === 'undefined') continue;

        const aRow = cMap.row;
        const aChoice = cMap.choice;
        const thisTmpScores = new SvelteMap<string, number>();
        const addSet = new Set<Choice | SelectableAddon>();
        const removeSet = new Set<Choice | SelectableAddon>();
        const newOptions = {...options};
        newOptions.isOverDlg = true;
        newOptions.isOverImg = true;

        let isChanged = false;
        if (localChoice && localChoice.useDiscountCount && !localChoice.appliedDisChoices) localChoice.appliedDisChoices = [];
        for (let j = 0; j < aChoice.scores.length; j++) {
            const aScore = aChoice.scores[j];
            if (aScore.isNotRecalculatable) continue;

            const point = pointTypeMap.get(aScore.id);
            if (typeof point === 'undefined') continue;

            const isActive = aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable ? true : aScore.isActive;

            if (aScore.appliedDiscount && aScore.isChangeDiscount && isActive && typeof aScore.tmpDisScore !== 'undefined') {
                if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                    let mul = aChoice.multipleUseVariable;
                    let isChangedMul = false;
                    let totalScore = 0;

                    if (aScore.discounts) {
                        for (let k = 0; k < aScore.discounts.length; k++) {
                            const dc = aScore.discounts[k];
                            if (dc.state !== INACTIVE) {
                                const dMap = choiceMap.get(dc.id);

                                if (typeof dMap !== 'undefined') {
                                    const dChoice = dMap.choice;

                                    if (typeof dChoice.appliedDisChoices !== 'undefined' && dChoice.countPerSelection) {
                                        const count = dChoice.appliedDisChoices.filter(id => id === aChoice.id).length;
                                        if (count === 0) continue;
                                        mul = mul - count;
                                        break;
                                    }
                                }
                            }
                        }
                    }
                    for (let k = mul - 1; k >= 0; k--) {
                        if (aChoice.isActive && aScore.isActiveMul && aScore.isActiveMul[k]) {
                            let tmpScore = aScore.multiplyByTimes ? aScore.tmpDisScore * (k + 1) : aScore.tmpDisScore;
                            if (point.belowZeroNotAllowed && point.startingSum + tmpScore < 0) {
                                if (aChoice.forcedActivated) {
                                    aChoice.numMultipleTimesMinus--;
                                    await selectedOneLess(aChoice, aRow, newOptions);

                                    const tmpAct = tmpActivatedMap.get(aChoice.id);
                                    if (typeof tmpAct !== 'undefined') {
                                        tmpAct.multiple += 1;
                                    } else {
                                        tmpActivatedMap.set(aChoice.id, {multiple: 1, activatedFrom: aChoice.activatedFrom});
                                    }
                                } else {
                                    await selectedOneLess(aChoice, aRow, newOptions);
                                }
                                isChangedMul = true;
                                break;
                            } else {
                                point.startingSum += tmpScore;
                                totalScore += tmpScore;
                                isChangedMul = true;
                            }
                        }
                    }

                    if (isChangedMul) {
                        isChanged = true;
                    }

                    thisTmpScores.set(aScore.id, totalScore);
                } else if (!aChoice.isSelectableMultiple) {
                    if (point.belowZeroNotAllowed && point.startingSum + aScore.tmpDisScore < 0) {
                        if (aChoice.forcedActivated) {
                            delete aChoice.forcedActivated;
                            tmpActivatedMap.set(aChoice.id, {multiple: aChoice.multipleUseVariable, activatedFrom: aChoice.activatedFrom});
                        }
                        await deselectObject(aChoice, aRow, options);
                    } else {
                        point.startingSum += aScore.tmpDisScore;
                        thisTmpScores.set(aScore.id, aScore.tmpDisScore);
                    }

                    isChanged = true;
                }

                if (isChanged) {
                    if (aScore.appliedDiscount && typeof aScore.discounts !== 'undefined') {
                        for (let k = 0; k < aScore.discounts.length; k++) {
                            const dc = aScore.discounts[k];

                            if (dc.state === ACTIVE && dc.count !== DISABLED) {
                                const cMap = choiceMap.get(dc.id);

                                if (typeof cMap !== 'undefined') {
                                    const dChoice = cMap.choice;

                                    addSet.add(dChoice);
                                }
                            }
                        }
                    }
                }
            }
            delete aScore.isChangeDiscount;
            delete aScore.tmpDisScore;

            if (!aChoice.isActive) break;

            let isChangedExp = false;
            let expVal = aScore.value;
            if (aScore.useExpression && !changedScores.has(aScore.idx)) {
                const oldVal = aScore.value;

                setScoreValue(point, aScore, aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable, aChoice.multipleUseVariable - 1);
                if (oldVal !== aScore.value) {
                    expVal = oldVal - aScore.value;
                    if (!isChangedExp) {
                        isChangedExp = true;
                    }
                }
            }
            if (!changedScores.has(aScore.idx)) {
                const hasScore = localChoice && localChoice.scores.length > 0;
                const scoreLeng = localChoice && localChoice.scores.length || 1;
                for (let k = 0; k < scoreLeng; k++) {
                    if (!aChoice.isActive) break;

                    const lScore = hasScore ? localChoice.scores[k] : null;
                    const tmpScore = lScore ? (tmpScores.get(lScore.id) || 0) : 0;
                    const lPoint = lScore ? pointTypeMap.get(lScore.id) : null;
                    const rPoint = !localChoice ? pointTypeMap.get(tmpScores.keys().next().value || '') : null;
                    const tmpPoint = rPoint ? tmpScores.values().next().value || 0 : 0;
                    if (hasScore && !lPoint) continue;

                    const afterSelected = checkRequirements(aScore.requireds);
                    const tmpActivated = new SvelteMap<string, ActivatedMap>([...activatedMap].map(([key, value]) => [key, {...value}]));
                    if (localChoice) {
                        if (localChoice.isSelectableMultiple && localChoice.isMultipleUseVariable) {
                            if (localChoice.multipleUseVariable === 0) {
                                tmpActivated.delete(localChoice.id);
                                localRow.currentChoices += 1;
                            } else {
                                tmpActivated.set(localChoice.id, {multiple: localChoice.multipleUseVariable + 1});
                                if (localChoice.multipleUseVariable === 1) {
                                    localRow.currentChoices -= 1;
                                }
                            }
                        } else {
                            tmpActivated.delete(localChoice.id);
                            localRow.currentChoices -= 1;
                        }
                        if (lPoint) lPoint.startingSum += tmpScore;
                    } else if (rPoint) {
                        rPoint.startingSum -= tmpPoint;
                    }
                    const beforeSelected = checkRequirements(aScore.requireds, tmpActivated);
                    if (localChoice) {
                        if (localChoice.isSelectableMultiple && localChoice.isMultipleUseVariable) {
                            if (localChoice.multipleUseVariable === 0) {
                                localRow.currentChoices -= 1;
                            } else if (localChoice.multipleUseVariable === 1) {
                                localRow.currentChoices += 1;
                            }
                        } else {
                            localRow.currentChoices += 1;
                        }
                        if (lPoint) lPoint.startingSum -= tmpScore;
                    } else if (rPoint) {
                        rPoint.startingSum += tmpPoint;
                    }
                    if (beforeSelected === afterSelected) continue;

                    if (!aScore.setValue) setScoreValue(point, aScore, aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable, aChoice.multipleUseVariable - 1);
                    let scoreVal = aScore.discountIsOn && typeof aScore.discountScore !== 'undefined' && aScore.appliedDiscount ? aScore.discountScore : aScore.value;
                    scoreVal = point.allowFloat ? scoreVal : Math.floor(scoreVal);
                    if (beforeSelected) {
                        if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                            const mul = aChoice.multipleUseVariable;

                            for (let l = mul - 1; l >= 0; l--) {
                                if (typeof aScore.isActiveMul !== 'undefined' && aScore.isActiveMul[l]) {
                                    const sValue = aScore.multiplyByTimes ? scoreVal * (l + 1) : scoreVal;
                                    if (point.belowZeroNotAllowed && point.startingSum + sValue < 0) {
                                        if (aChoice.forcedActivated) {
                                            aChoice.numMultipleTimesMinus--;
                                            await selectedOneLess(aChoice, aRow, newOptions);

                                            const tmpAct = tmpActivatedMap.get(aChoice.id);
                                            if (typeof tmpAct !== 'undefined') {
                                                tmpAct.multiple += 1;
                                            } else {
                                                tmpActivatedMap.set(aChoice.id, {multiple: 1, activatedFrom: aChoice.activatedFrom});
                                            }
                                        } else {
                                            await selectedOneLess(aChoice, aRow, newOptions);
                                        }
                                        break;
                                    } else {
                                        point.startingSum += sValue;
                                        thisTmpScores.set(aScore.id, sValue);
                                        aScore.isActiveMul[l] = false;
                                    }
                                }
                            }
                        } else if (!aChoice.isSelectableMultiple) {
                            if (aScore.isActive) {
                                if (point.belowZeroNotAllowed && point.startingSum + scoreVal < 0) {
                                    if (aChoice.forcedActivated) {
                                        delete aChoice.forcedActivated;
                                        tmpActivatedMap.set(aChoice.id, {multiple: aChoice.multipleUseVariable, activatedFrom: aChoice.activatedFrom});
                                    }
                                    deselectObject(aChoice, aRow, newOptions);
                                } else {
                                    point.startingSum += scoreVal;
                                    thisTmpScores.set(aScore.id, scoreVal);
                                    delete aScore.isActive;
                                }
                            }
                        }
                        if (aScore.setValue) delete aScore.setValue;
                        if (aScore.appliedDiscount && typeof aScore.discounts !== 'undefined') {
                            for (let k = 0; k < aScore.discounts.length; k++) {
                                const dc = aScore.discounts[k];

                                if (dc.state === ACTIVE && dc.count !== DISABLED) {
                                    const cMap = choiceMap.get(dc.id);

                                    if (typeof cMap !== 'undefined') {
                                        const dChoice = cMap.choice;

                                        if (!addSet.has(dChoice)) {
                                            removeSet.add(dChoice);
                                        }
                                    }
                                }
                            }
                        }
                    } else {
                        if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                            const mul = aChoice.multipleUseVariable;
                            if (typeof aScore.isActiveMul === 'undefined') aScore.isActiveMul = [];
                            for (let l = mul - 1; l >= 0; l--) {
                                if (!aScore.isActiveMul[l]) {
                                    const sValue = aScore.multiplyByTimes ? scoreVal * (l + 1) : scoreVal;
                                    if (point.belowZeroNotAllowed && point.startingSum + sValue < 0) {
                                        if (aChoice.forcedActivated) {
                                            aChoice.numMultipleTimesMinus--;
                                            await selectedOneLess(aChoice, aRow, newOptions);

                                            const tmpAct = tmpActivatedMap.get(aChoice.id);
                                            if (typeof tmpAct !== 'undefined') {
                                                tmpAct.multiple += 1;
                                            } else {
                                                tmpActivatedMap.set(aChoice.id, {multiple: 1, activatedFrom: aChoice.activatedFrom});
                                            }
                                        } else {
                                            await selectedOneLess(aChoice, aRow, newOptions);
                                        }
                                        break;
                                    } else {
                                        point.startingSum -= sValue;
                                        thisTmpScores.set(aScore.id, sValue);
                                        aScore.isActiveMul[l] = true;
                                    }
                                }
                            }
                        } else if (!aChoice.isSelectableMultiple) {
                            if (!aScore.isActive) {
                                if (point.belowZeroNotAllowed && point.startingSum - scoreVal < 0) {
                                    if (aChoice.forcedActivated) {
                                        delete aChoice.forcedActivated;
                                        tmpActivatedMap.set(aChoice.id, {multiple: aChoice.multipleUseVariable, activatedFrom: aChoice.activatedFrom});
                                    }
                                    await deselectObject(aChoice, aRow, newOptions);
                                } else {
                                    point.startingSum -= scoreVal;
                                    thisTmpScores.set(aScore.id, scoreVal);
                                    aScore.isActive = true;
                                }
                            }
                        }
                        if (aScore.appliedDiscount && typeof aScore.discounts !== 'undefined') {
                            for (let k = 0; k < aScore.discounts.length; k++) {
                                const dc = aScore.discounts[k];

                                if (dc.state === ACTIVE && dc.count !== DISABLED) {
                                    const cMap = choiceMap.get(dc.id);

                                    if (typeof cMap !== 'undefined') {
                                        const dChoice = cMap.choice;

                                        addSet.add(dChoice);
                                    }
                                }
                            }
                        }
                    }
                    if (!isChanged) {
                        isChanged = true;
                    }
                    changedScores.add(aScore.idx);
                }
            }
            if (isChangedExp && !isChanged) {
                if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                    const mul = aChoice.multipleUseVariable;

                    for (let l = mul - 1; l >= 0; l--) {
                        if (typeof aScore.isActiveMul !== 'undefined' && aScore.isActiveMul[l]) {
                            const sValue = aScore.multiplyByTimes ? expVal * (l + 1) : expVal;
                            isChanged = true;
                            changedScores.add(aScore.idx);
                            if (point.belowZeroNotAllowed && point.startingSum + sValue < 0) {
                                if (aChoice.forcedActivated) {
                                    aChoice.numMultipleTimesMinus--;
                                    await selectedOneLess(aChoice, aRow, newOptions);

                                    const tmpAct = tmpActivatedMap.get(aChoice.id);
                                    if (typeof tmpAct !== 'undefined') {
                                        tmpAct.multiple += 1;
                                    } else {
                                        tmpActivatedMap.set(aChoice.id, {multiple: 1, activatedFrom: aChoice.activatedFrom});
                                    }
                                } else {
                                    await selectedOneLess(aChoice, aRow, newOptions);
                                }
                                break;
                            } else {
                                point.startingSum += sValue;
                                thisTmpScores.set(aScore.id, sValue);
                            }
                        }
                    }
                } else if (!aChoice.isSelectableMultiple) {
                    if (aScore.isActive) {
                        if (point.belowZeroNotAllowed && point.startingSum + expVal < 0) {
                            if (aChoice.forcedActivated) {
                                delete aChoice.forcedActivated;
                                tmpActivatedMap.set(aChoice.id, {multiple: aChoice.multipleUseVariable, activatedFrom: aChoice.activatedFrom});
                            }
                            await deselectObject(aChoice, aRow, newOptions);
                        } else {
                            point.startingSum += expVal;
                            thisTmpScores.set(aScore.id, expVal);
                        }
                        isChanged = true;
                        changedScores.add(aScore.idx);
                    }
                }
            }
        }
        if (removeSet.size > 0) {
            const arr = Array.from(removeSet);

            for (let i = 0; i < arr.length; i++) {
                const dChoice = arr[i];

                if (!addSet.has(dChoice)) await updateCount(aChoice, dChoice);
            }
        }
        if (addSet.size > 0) {
            const arr = Array.from(addSet);

            for (let i = 0; i < arr.length; i++) {
                const dChoice = arr[i];

                await addCount(aChoice, dChoice);
            }
        }
        if (isChanged) {
            scoreUpdate.length === 0 ? scoreUpdate.push(`Scores Updated On: ${aChoice.title}`) : scoreUpdate.push(`, ${aChoice.title}`);
            await selectUpdateScore(aChoice, aRow, thisTmpScores, count + 1, changedScores, scoreUpdate, options);
        }
    }
    if (count === 0) {
        if (scoreUpdate.length > 0 && !app.hideScoresUpdated) {
            const tempDiv = document.createElement('div');

            tempDiv.innerHTML = scoreUpdate.join('');
            snackbarVariables.labelText = tempDiv.textContent || '';
            snackbarVariables.isOpen = true;
        }
        scoreUpdate.splice(0);
    }
}

export async function activateTempChoices(options: ChoiceOptions) {
    if (isActivating) return;
    let isActivated = false;
    for (const [id, val] of tmpActivatedMap) {
        if (deselectQue.has(id)) continue;

        const cMap = choiceMap.get(id);
        if (typeof cMap === 'undefined') continue;

        const aRow = cMap.row;
        const aChoice = cMap.choice;
        const newOption = {...options};

        newOption.isForced = true;
        newOption.isAllowDeselect = val.isAllowDeselect;
        newOption.fromTemp = true;

        if (val.multiple === 0) {
            if (aChoice.isSelectDelayed || aChoice.isFadeTransition) {
                selectObject(aChoice, aRow, newOption);
            } else {
                await selectObject(aChoice, aRow, newOption);
            }
            if (aChoice.isActive) isActivated = true;
        } else {
            const num = aChoice.multipleUseVariable;
            for (let i = 0; i < val.multiple; i++) {
                if (aChoice.isSelectDelayed || aChoice.isFadeTransition) {
                    selectedOneMore(aChoice, aRow, newOption);
                }
                await selectedOneMore(aChoice, aRow, newOption);
            }
            if (aChoice.multipleUseVariable > num) isActivated = true;
        }
    }

    if (isActivated) await activateTempChoices(options);
}

function clearWordDialog() {
    wordDialog.currentDialog = 'none';
    wordDialog.context = '';
    wordDialog.cFunc = () => {};
    wordDialog.isDeselect = false;
    wordDialog.isForced = false;
    wordDialog.isWord = false;
    wordDialog.prevText = '';
    wordDialog.title = '';
}

function clearImgDialog() {
    imgDialog.currentDialog = 'none';
    delete imgDialog.data;
    imgDialog.imgProp = '';
    imgDialog.isDeselect = false;
    imgDialog.isForced = false;
}

function openWordDialog(localChoice: Choice | SelectableAddon, options: {isWord?: boolean, isDeselect?: boolean, isForced?: boolean}): Promise<{ status: 'accept'; wordText: string } | { status: 'cancel' } | { status: 'deselect' }> {
    return new Promise((resolve) => {
        let done = false;
        wordDialog.context = localChoice.wordPromptText || '';
        wordDialog.prevText = localChoice.wordChangeSelect || '';
        wordDialog.isWord = options.isWord;
        wordDialog.isDeselect = options.isDeselect;
        wordDialog.isForced = options.isForced;
        wordDialog.currentDialog = 'dlgCommon';
        wordDialog.cFunc = (e, wordText) => {
            if (done) return;
            done = true;
            clearWordDialog();
            if (e.detail.action === 'accept') {
                resolve({ status: 'accept', wordText: wordText || '' });
            } else if (e.detail.action === 'deselect') {
                resolve({ status: 'deselect' });
            } else {
                resolve({ status: 'cancel' });
            }
        };
    });
}

function openImgDialog(localChoice: Choice | SelectableAddon, options: {isDeselect?: boolean, isForced?: boolean}): Promise<{ status: 'accept'; wordText: string } | { status: 'cancel' } | { status: 'deselect' }> {
    return new Promise((resolve) => {
        let done = false;
        imgDialog.currentDialog = 'appImageUpload';
        imgDialog.data = localChoice;
        imgDialog.imgProp = 'image';
        imgDialog.isDeselect = options.isDeselect;
        imgDialog.isForced = options.isForced;
        imgDialog.cFunc = (e) => {
            if (done) return;
            done = true;
            clearImgDialog();
            if (e.detail.action === 'deselect') {
                resolve({ status: 'deselect' });
            } else {
                resolve({ status: 'cancel' });
            }
        }
    });
}

function delayProc(ms: number) {
    return new Promise(res => setTimeout(res, ms));
}

async function deselectDiscountOther(localChoice: Choice | SelectableAddon) {
    if (!localChoice.discountOther) return;
    if (typeof localChoice.discountOperator === 'undefined' || typeof localChoice.discountValue === 'undefined') return;

    if (localChoice.isDisChoices) {
        const dList = new Set<string>();
        if (typeof localChoice.discountRows !== 'undefined') {
            for (let i = 0; i < localChoice.discountRows.length; i++) {
                const dRow = rowMap.get(localChoice.discountRows[i]);
                if (typeof dRow !== 'undefined') {
                    for (let j = 0; j < dRow.objects.length; j++) {
                        const dChoice = dRow.objects[j];
                        await deselectDiscount(localChoice, dChoice);
                        dList.add(dChoice.id);
                    }
                }
            }
        }
        if (typeof localChoice.discountChoices !== 'undefined') {
            for (let i = 0; i < localChoice.discountChoices.length; i++) {
                if (!dList.has(localChoice.discountChoices[i])) {
                    const cMap = choiceMap.get(localChoice.discountChoices[i]);
                    if (typeof cMap !== 'undefined') {
                        await deselectDiscount(localChoice, cMap.choice);
                    }
                }
            }
        }
    } else {
        if (typeof localChoice.discountGroups !== 'undefined') {
            for (let i = 0; i < localChoice.discountGroups.length; i++) {
                const groupData = groupMap.get(localChoice.discountGroups[i]);
                if (typeof groupData !== 'undefined') {
                    for (let j = 0; j < groupData.elements.length; j++) {
                        const cMap = choiceMap.get(groupData.elements[j]);
                        if (typeof cMap !== 'undefined') {
