                                    const thisWindow = document.getElementById('backpackDialog');
                                    thisWindow?.scrollTo({top: divs[idx].getBoundingClientRect().top + window.scrollY, behavior: 'smooth'});
                                } else {
                                    window.scrollTo({top: divs[idx].getBoundingClientRect().top + window.scrollY, behavior: 'smooth'});
                                }
                            }
                        }
                    }
                }
            }, 10);
        });
    }
}

function checkAddonDeselectable(localChoice: Choice, localRow: Row) {
    if (!localChoice.addons || localChoice.addons.length === 0) return true;

    let result = true;
    for (let i = 0; i < localChoice.addons.length; i++) {
        const addon = localChoice.addons[i];
        if (!addon.isSelectable) continue;
        if (!addon.isActive) continue;
        if (addon.activateThisChoice && addon.activateThisChoice.split(',').indexOf(localChoice.id) !== -1) continue;
        if (addon.selectOnce) return false;
        if (addon.forcedActivated) return false;

        if (addon.isSelectableMultiple && addon.isMultipleUseVariable) {
            const pNum = addon.multipleUseVariable;
            for (let i = 0; i < Math.abs(pNum); i++) {
                if (pNum > 0) {
                    result = result && checkDeselectable(addon, localRow);
                } else {
                    result = result && checkSelectable(addon, localRow);
                }
            }
        } else {
            result = result && checkDeselectable(addon, localRow);
        }

        if (!result) return false;
    }
    return result;
}

function checkDeselectable(localChoice: Choice | SelectableAddon, localRow: Row): boolean {
    const isChoice = typeof localChoice.parentId === 'undefined';
    const pointCheck = checkPoints(localChoice, false);
    const addonCheck = isChoice ? checkAddonDeselectable(localChoice as Choice, localRow) : true;
    if (!pointCheck || !addonCheck) return false;

    return true;
}

function checkSelectable(localChoice: Choice | SelectableAddon, localRow: Row, aMap: SvelteMap<string, ActivatedMap> = new SvelteMap([...activatedMap].map(([key, value]) => [key, {...value}])), pMap: SvelteMap<string, PointType> = new SvelteMap([...pointTypeMap].map(([key, value]) => [key, {...value}]))): boolean {
    const isChoice = typeof localChoice.parentId === 'undefined';
    const countCheck = isChoice ? !localChoice.isCountDisabled : localChoice.countAsChoice;
    const reqCheck = checkRequirements(localChoice.requireds) && !localRow.isInfoRow;
    if (!reqCheck) return false;

    let origRow = localRow;
    if (localRow.isResultRow) {
        const cMap = choiceMap.get(localChoice.id);

        if (typeof cMap !== 'undefined') {
            origRow = cMap.row;
        }
    }
    let allowedNum = origRow.allowedChoices;

    if (localChoice.addToAllowChoice && typeof localChoice.idOfAllowChoice !== 'undefined' && typeof localChoice.numbAddToAllowChoice !== 'undefined') {
        for (let i = 0; i < localChoice.idOfAllowChoice.length; i++) {
            if (localChoice.idOfAllowChoice[i] === localRow.id) {
                allowedNum += localChoice.numbAddToAllowChoice;
                break;
            }
        }
    }

    if (!isChoice) {
        const cMap = choiceMap.get(localChoice.parentId);

        if (typeof cMap !== 'undefined') {
            const pChoice = cMap.choice;
            const pRow = cMap.row;

            if (!pChoice.isActive) {
                const isMul = pChoice.isSelectableMultiple && pChoice.isMultipleUseVariable;
                if (!checkSelectable(pChoice, pRow, aMap, pMap)) return false;

                aMap.set(pChoice.id, { multiple: isMul ? 1 : 0 });

                for (let i = 0; i < localChoice.scores.length; i++) {
                    const score = localChoice.scores[i];

                    if (checkRequirements(score.requireds)) {
                        const point = pMap.get(score.id);
                        if (typeof point !== 'undefined') {
                            let val = score.value;
                            if (score.useExpression && score.setValue) {
                                expDiscount(point, score);
                            }

                            if (score.discountIsOn && score.appliedDiscount && typeof score.discountScore !== 'undefined' && typeof score.discounts !== 'undefined') {
                                val = score.discountScore;
                            }
                            val = point.allowFloat ? val : Math.floor(val);
                            point.startingSum -= val;
                        }
                    }
                }
            }
        }
    }

    if (countCheck && allowedNum > 0 && origRow.currentChoices >= allowedNum) {
        let deselectable = false;
        for (const [id] of aMap) {
            const cMap = choiceMap.get(id);

            if (typeof cMap !== 'undefined') {
                const aRow = cMap.row;
                if (aRow.id !== origRow.id) continue;

                const aChoice = cMap.choice;

                if (typeof aChoice.parentId === 'undefined' ? !aChoice.isCountDisabled : aChoice.countAsChoice) {
                    if (!aChoice.forcedActivated && !aChoice.selectOnce && aChoice.id !== localChoice.parentId) {
                        if (aChoice.isSelectableMultiple) {
                            let counter = aChoice.multipleUseVariable;
                            for (let i = 0; i < counter; i++) {
                                deselectable = checkDeselectable(aChoice, origRow);
                            }
                        } else {
                            deselectable = checkDeselectable(aChoice, origRow);
                        }
                        if (deselectable) {
                            break;
                        }
                    }
                }
            }
        }
        if (!deselectable) {
            return false;
        }
    }

    return checkPoints(localChoice, true);
}

export async function deselectObject(localChoice: Choice | SelectableAddon, localRow: Row, options: ChoiceOptions) {
    if (deselectQue.has(localChoice.id) || !localChoice.isActive) return;
    deselectQue.add(localChoice.id);

    const isChoice = typeof localChoice.parentId === 'undefined';
    const deselectable = checkDeselectable(localChoice, localRow);
    if (!deselectable) {
        deselectQue.delete(localChoice.id);
        return;
    }

    const addonCheck = isChoice ? await checkAddons(localChoice as Choice, localRow, options) : true;
    if (!addonCheck) {
        deselectQue.delete(localChoice.id);
        return;
    }

    const countCheck = isChoice ? !localChoice.isCountDisabled : localChoice.countAsChoice;

    const deselectProcess = async () => {
        playSfxOnDeselect(localChoice);
        const tmpScores = new SvelteMap<string, number>();

        await deselectCalculateScore(localChoice, tmpScores, {isMultiple: false, isPos: false, selNum: DISABLED});

        await deselectActivateOther(localChoice, options);

        await deselectDiscountOther(localChoice);

        localChoice.isActive = false;
        if (countCheck) localRow.currentChoices -= 1;
        activatedMap.delete(localChoice.id);

        await deselectMissingReq(localChoice.id, options);

        deselectModifyPoint(localChoice);

        setVariables(localChoice, false);

        addAllowedChoice(localChoice, options, SUBTRACT);

        deselectEffectProc(localChoice);

        deselectHideContent(localChoice);

        if (localChoice.textfieldIsOn && typeof localChoice.idOfTheTextfieldWord !== 'undefined') {
            const word = wordMap.get(localChoice.idOfTheTextfieldWord);
            if (typeof word !== 'undefined') {
                word.replaceText = localChoice.wordChangeDeselect || '';
            }
        }

        if (localChoice.isImageUpload) {
            if (typeof localChoice.defaultImage !== 'undefined') localChoice.image = localChoice.defaultImage;
        }

        if (localChoice.backpackBtnRequirement) {
            if (typeof app.btnBackpackIsOn !== 'undefined') {
                app.btnBackpackIsOn -= 1;
            }
        }

        if (localChoice.showAllAddons) {
            if (typeof app.showAllAddons !== 'undefined') {
                app.showAllAddons -= 1;
            }
        }

        delete localChoice.tempSlots;
        await deselectUpdateScore(localChoice, localRow, tmpScores, 0, undefined, undefined, options);
        activateTempChoices(options);
        delete localChoice.appliedDisChoices;
        if (localChoice.isAutoActive) tmpActivatedMap.set(localChoice.id, {multiple: 0});

        if (!localChoice.isActive && localChoice.parentId) {
            const pMap = choiceMap.get(localChoice.parentId);

            if (typeof pMap !== 'undefined') {
                const pChoice = pMap.choice;

                if (pChoice.isActive) {
                    let deselect = localChoice.deselectParent;
                    let count = 0;

                    if (pChoice.deselectWhenNoAddon) {
                        for (let i = 0; i < pChoice.addons.length; i++) {
                            const cAddon = pChoice.addons[i] as Addon;

                            if (cAddon.isActive) {
                                count++;
                            }
                        }

                        if (count === 0) deselect = true;
                    }

                    if (deselect) {
                        const newOptions = {...options};
                        newOptions.fromAddon = true;
                        newOptions.isOverDlg = true;
                        newOptions.isOverImg = true;
                        if (pChoice.isSelectableMultiple && pChoice.isMultipleUseVariable) {
                            const pNum = pChoice.multipleUseVariable;
                            for (let i = 0; i < Math.abs(pNum); i++) {
                                if (pNum > 0) {
                                    await selectedOneLess(pChoice, localRow, newOptions);
                                } else {
                                    await selectedOneMore(pChoice, localRow, newOptions);
                                }
                            }
                        } else {
                            await deselectObject(pChoice, localRow, newOptions);
                        }
                    }
                }
            }
        }
    }

    if (localChoice.isDeselectDelayed && typeof localChoice.deselectDelayTime !== 'undefined') {
        if (localChoice.deselectDelayTimer) {
            deselectQue.delete(localChoice.id);
            return;
        }
        localChoice.deselectDelayTimer = true;
        await delayProc(localChoice.deselectDelayTime);
        delete localChoice.deselectDelayTimer;
    }

    if (!options.isOverDlg) {
        if (localChoice.customTextfieldIsOn) {
            const result = await openWordDialog(localChoice, {isWord: true, isDeselect: true});

            if (result.status === 'cancel') {
                deselectQue.delete(localChoice.id);
                return;
            }
            if (result.status === 'accept' && localChoice.idOfTheTextfieldWord) {
                localChoice.wordChangeSelect = result.wordText;
                const word = wordMap.get(localChoice.idOfTheTextfieldWord);
                if (typeof word !== 'undefined') {
                    word.replaceText = result.wordText;
                }
                deselectQue.delete(localChoice.id);
                return;
            }
        }

        if (localChoice.isImageUpload) {
            const result = await openImgDialog(localChoice, {isDeselect: true});

            if (result.status !== 'deselect') {
                deselectQue.delete(localChoice.id);
                return;
            }
        }
    }

    if (options.linkedObjects.indexOf(localChoice.id) === -1) {
        if (localChoice.isFadeTransition) {
            if (typeof localChoice.fadeTransitionColor === 'undefined' || localChoice.fadeTransitionColor === '') {
                app.fadeTransitionColor = '000000FF';
            } else {
                app.fadeTransitionColor = localChoice.fadeTransitionColor;
            }

            if (typeof localChoice.fadeInTransitionTime === 'undefined') {
                app.fadeTransitionTime = 0.25;
            } else {
                app.fadeTransitionTime = localChoice.fadeInTransitionTime / 1000;
            }

            app.fadeTransitionIsOn = true;

            await delayProc(app.fadeTransitionTime * 1000);

            if (typeof localChoice.fadeOutTransitionTime !== 'undefined') {
                app.fadeTransitionTime = localChoice.fadeOutTransitionTime / 1000;
            }
            app.fadeTransitionIsOn = false;
        }
        await deselectProcess();
    }
    if (options.linkedObjects.indexOf(localChoice.id) === 0) {
        options.linkedObjects.splice(0);
    }
    deselectQue.delete(localChoice.id);

}

