                    }
                }

                for (let i = rList.length - 1; i >= 0; i--) {
                    tmpSet.add(rList[i]);
                }

                rList = [...tmpSet].reverse();
                localChoice.activatedRandom = rList.slice(0, rNum);

                for (let i = 0; i < rNum; i++) {
