                if (newChoice.objectDesignGroups) {
                    for (let j = 0; j < newChoice.objectDesignGroups.length; j++) {
                        let dGroup = objectDesignMap.get(newChoice.objectDesignGroups[j]);
                        if (typeof dGroup !== 'undefined') {
