function replaceFields(obj: any, keysToReplace: string[], imgMap: Map<string, string>) {
    for (let i = 0; i < keysToReplace.length; i++) {
        const key = keysToReplace[i];

        if (typeof obj[key] === 'string') {
            const img = imgMap.get(obj[key]);

            if (img) {
                obj[key] = img;
            }
        }
    }
}

function replaceImages(imgMap: Map<string, string>) {
    const styleKeysToReplace = ['backgroundImage', 'rowBackgroundImage', 'objectBackgroundImage', 'addonBackgroundImage', 'rowBorderImage', 'objectBorderImage', 'addonBorderImage'];
    const imageKeyToReplace = ['image'];
    const choiceKeysToReplace = ['image', 'bgImage'];

    replaceFields(app.styling, styleKeysToReplace, imgMap);

    for (let i = 0; i < app.rows.length; i++) {
        const row = app.rows[i];

        if (typeof row.styling !== 'undefined') {
            replaceFields(row.styling, styleKeysToReplace, imgMap);
        }
        replaceFields(row, imageKeyToReplace, imgMap);

        for (let j = 0; j < row.objects.length; j++) {
            const choice = row.objects[j];

            if (typeof choice.styling !== 'undefined') {
                replaceFields(choice.styling, styleKeysToReplace, imgMap);
            }
            replaceFields(choice, choiceKeysToReplace, imgMap);

            for (let k = 0; k < choice.addons.length; k++) {
                const addon = choice.addons[k];

                replaceFields(addon, choiceKeysToReplace, imgMap);
            }
        }
    }

    for (let i = 0; i < app.backpack.length; i++) {
        const row = app.backpack[i];

        if (typeof row.styling !== 'undefined') {
            replaceFields(row.styling, styleKeysToReplace, imgMap)
        }
        replaceFields(row, imageKeyToReplace, imgMap);

        for (let j = 0; j < row.objects.length; j++) {
            const choice = row.objects[j];

            if (typeof choice.styling !== 'undefined') {
                replaceFields(choice.styling, styleKeysToReplace, imgMap);
            }
            replaceFields(choice, choiceKeysToReplace, imgMap);

            for (let k = 0; k < choice.addons.length; k++) {
                const addon = choice.addons[k];

                replaceFields(addon, choiceKeysToReplace, imgMap);
            }
        }
    }

    if (typeof app.rowDesignGroups !== 'undefined') {
        for (let i = 0; i < app.rowDesignGroups.length; i++) {
            const dGroup = app.rowDesignGroups[i];

            if (typeof dGroup.styling !== 'undefined') {
                replaceFields(dGroup.styling, styleKeysToReplace, imgMap);
            }
        }
    }

    if (typeof app.objectDesignGroups !== 'undefined') {
        for (let i = 0; i < app.objectDesignGroups.length; i++) {
            const dGroup = app.objectDesignGroups[i];

            if (typeof dGroup.styling !== 'undefined') {
                replaceFields(dGroup.styling, styleKeysToReplace, imgMap);
            }
        }
    }

    if (typeof app.viewerConfig !== 'undefined') {
        replaceFields(app.viewerConfig, ['loadingBgImage', 'favicon'], imgMap);
    }
}

async function waitForImagesToLoad(container: HTMLElement): Promise<void> {
    const imgs = container.querySelectorAll('img');
    const promises = Array.from(imgs).map(img => {
        if (img.complete) return Promise.resolve();
        return new Promise(resolve => {
            img.onload = resolve;
            img.onerror = resolve;
        });
    });
    return Promise.all(promises).then(() => {});
}

function forceEagerImageLoading(container: HTMLElement) {
    const images = container.querySelectorAll('img');
    images.forEach(img => {
        if (img.loading === 'lazy') {
            img.loading = 'eager';
        }
    });
}

function copyComputedStyles(source: HTMLElement, target: HTMLElement) {
    const computed = window.getComputedStyle(source);
    for (const key of computed) {
        try {
            target.style.setProperty(key, computed.getPropertyValue(key), computed.getPropertyPriority(key));
        } catch (error) {
            console.error(error);
        }
    }
}

function deepCopyStyles(source: HTMLElement, target: HTMLElement) {
    copyComputedStyles(source, target);
    const sourceChildren = source.children;
    const targetChildren = target.children;

    for (let i = 0; i < sourceChildren.length; i++) {
        deepCopyStyles(sourceChildren[i] as HTMLElement, targetChildren[i] as HTMLElement);
    }
}

async function waitForBorderImagesToLoad(container: HTMLElement) {
    const elements = container.querySelectorAll<HTMLElement>('*');
    const borderImageUrls: string[] = [];

    elements.forEach(el => {
        const style = getComputedStyle(el);
        const urlMatch = style.borderImageSource.match(/url\(["']?(.*?)["']?\)/);
        if (urlMatch && urlMatch[1]) {
            borderImageUrls.push(urlMatch[1]);
        }
    });

    const loadPromises = borderImageUrls.map(src => {
        return new Promise(resolve => {
            const img = new Image();
            img.src = src;
            img.onload = resolve;
            img.onerror = resolve;
        });
    });

    await Promise.all(loadPromises);
}

function waitForRenderFrames(frames = 2): Promise<void> {
    return new Promise(resolve => {
        let count = 0;
        function next() {
            if (++count >= frames) return resolve();
                requestAnimationFrame(next);
        }
        requestAnimationFrame(next);
    });
}

