export function getDate(time: string) {
    const userLocale = navigator.language;
    const userTimeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    const updated = new Date(time);
    const formatDate = new Intl.DateTimeFormat(userLocale, {
        timeZone: userTimeZone,
        dateStyle: 'medium'
    }).format(updated);

    return formatDate;
}

export function scrollToLastRow(virtualizer: SvelteVirtualizer<HTMLDivElement, Element>
, virtualListEl: HTMLDivElement, lastIndex: number) {
    let retryCount = 0;
    virtualListEl.scrollTo({ top: virtualListEl.scrollHeight, behavior: 'smooth' });

    function tryScroll() {
        const virtualItem = virtualizer.getVirtualItems().find(item => item.index === lastIndex);
        if (virtualItem) {
            virtualizer.scrollToIndex(lastIndex, { align: 'end', behavior: 'smooth' });
        } else {
            if (retryCount < 10) {
                retryCount++;
                requestAnimationFrame(tryScroll);
            }
        }
    }

    tryScroll();
}

