function buttonActivate() {
        if (row.btnPointAddon && row.buttonTypeRadio === 'sumaddon' && typeof row.pointTypeRandom !== 'undefined') {
            const rndMax = row.randomMax || 0;
            const rndMin = row.randomMin || 0;
            const rnd = Math.floor(Math.random() * (rndMax - rndMin) + rndMin);
            const tmpScores = new SvelteMap<string, number>();
            const point = pointTypeMap.get(row.pointTypeRandom);

            if (typeof point !== 'undefined') {
                if (point.belowZeroNotAllowed && point.startingSum + rnd < 0) {
                    return;
                }

                const actRow = activatedMap.get(row.id);
                let pNum = 0;

                point.startingSum += rnd;

                if (typeof actRow !== 'undefined' && actRow.pointNum) {
                    pNum = actRow.pointNum;
                }

                Array.from(activatedMap.entries()).forEach(([id, val]) => {
                    const cMap = choiceMap.get(id);
                    if (typeof cMap !== 'undefined') {
                        const aRow = cMap.row;
                        const aChoice = cMap.choice;
                        if (!checkRequirements(aChoice.requireds)) {
                            if (aChoice.forcedActivated) {
                                delete aChoice.forcedActivated;
                                if (!aChoice.isAllowDeselect) tmpActivatedMap.set(aChoice.id, {multiple: val.multiple});
                            }
                            if (val.multiple === 0) {
                                if (aChoice.isActive) {
                                    deselectObject(aChoice, aRow, deselectOptions);
                                }
                            } else if (val.multiple > 0) {
                                const mul = val.multiple;
                                for (let i = 0; i < mul; i++) {
                                    if (aChoice.isActive) {
                                        selectedOneLess(aChoice, aRow, deselectOptions);
                                    }
                                }
                            }
                        }
                    }
                });

                activatedMap.set(row.id, {multiple: 0, isRowButton: true, rndPoint: row.pointTypeRandom, pointNum: pNum + rnd});
                tmpScores.set(point.id, rnd);

                selectUpdateScore(null, row, tmpScores, 0, undefined, undefined, blankOptions);
                activateTempChoices(blankOptions);
            }
            return;
        }

        if (row.buttonRandom) {
            if (row.isWeightedRandom) {
                const validChoices = row.objects.filter(choice => checkRequirements(choice.requireds) && (!choice.isNotSelectable || row.allowActivateUnselectable) && (!choice.isActive || !row.onlyUnselectedChoices));
                if (validChoices.length === 0) return;
                let totalWeight = 0;

                for (let i = 0; i < validChoices.length; i++) {
                    const vChoice = validChoices[i];
                    const weight = vChoice.randomWeight || 100;

                    totalWeight += weight;
                }

                if (typeof row.buttonRandomNumber !== 'undefined') {
                    for (let i = 0; i < row.buttonRandomNumber; i++) {
                        const rnd = Math.floor(Math.random() * totalWeight);
                        let runningTotal = 0;

                        for (let j = 0; j < validChoices.length; j++) {
                            const vChoice = validChoices[j];
                            const weight = vChoice.randomWeight || 100;

                            runningTotal += weight;

                            if (rnd < runningTotal) {
                                if (vChoice.isSelectableMultiple && vChoice.isMultipleUseVariable && vChoice.numMultipleTimesPluss) {
                                    if (vChoice.numMultipleTimesPluss > vChoice.multipleUseVariable) {
                                        selectedOneMore(vChoice, row, blankOptions);
                                    } else {
                                        selectedOneLess(vChoice, row, deselectOptions);
                                    }
                                } else {
                                    if (vChoice.isActive) {
                                        deselectObject(vChoice, row, deselectOptions);
                                    } else {
                                        selectObject(vChoice, row, blankOptions);
                                    }
                                }
                                break;
                            }
                        }
                    }
                }
            } else {
                if (typeof row.buttonRandomNumber !== 'undefined') {
                    const selectedIndexes: number[] = [];
                    for (let i = 0; i < row.buttonRandomNumber; i++) {
                        const validChoices = row.objects.filter(choice => checkRequirements(choice.requireds) && (!choice.isNotSelectable || row.allowActivateUnselectable) && (!choice.isActive || !row.onlyUnselectedChoices));
                        if (validChoices.length === 0) return;

                        const index = Math.floor(Math.random() * validChoices.length);
                        const choice = validChoices[index];

                        if (choice && selectedIndexes.indexOf(index) === -1) {
                            selectedIndexes.push(index);

                            if (choice.isSelectableMultiple && choice.isMultipleUseVariable && choice.numMultipleTimesPluss) {
                                if (choice.numMultipleTimesPluss > choice.multipleUseVariable) {
                                    selectedOneMore(choice, row, blankOptions);
                                } else {
                                    selectedOneLess(choice, row, deselectOptions);
                                }
                            } else {
                                if (choice.isActive) {
                                    deselectObject(choice, row, deselectOptions);
                                } else {
                                    selectObject(choice, row, blankOptions);
                                }
                            }
                        }
                    }
                }
            }
        } else if (typeof row.buttonId !== 'undefined') {
            const variable = variableMap.get(row.buttonId);

            if (typeof variable !== 'undefined') {
                if (activatedMap.has(variable.id)) {
                    if (row.buttonType) {
                        variable.isTrue = false;
                        activatedMap.delete(variable.id);
                    }
                } else {
                    variable.isTrue = true;
                    activatedMap.set(variable.id, {multiple: 0, isVariable: true});
                }
            }
        }
    }

