async function loadImagesSequentially(images: Set<string>) {
        const urls = Array.from(images);

        for (let i = 0; i < urls.length; i++) {
            const url = urls[i];

            try {
                await new Promise((resolve, reject) => {
                    const img = new Image();

                    img.onload = resolve;
                    img.onerror = reject;
                    img.src = url;
                });
            } catch (error) {
                console.error(error);
            } finally {
                if (indicatorEl) indicatorEl.innerHTML = `<div>Images</div><div>${i} / ${urls.length}</div>`;
            }
        }
    }

async function checkAvifSupport() {
        if (hasAvif.value) {
            const errorMsg = 'Your browser does not support the .avif format.\n Avif images may not be displayed.';

            try {
                await new Promise((resolve, reject) => {
                    const img = new Image();

                    img.onload = resolve;
                    img.onerror = reject
                    img.src = 'data:image/avif;base64,';
                });
            } catch (error) {
                console.error(error);
                snackbarVariables.labelText = errorMsg;
                snackbarVariables.isOpen = true;
            }
        }
    }

async function loadProject() {
        boxEl = document.getElementById('lm');
		sizeEl = document.getElementById('projectSize');
        indicatorEl = document.getElementById('indicator');
        const totalSize = sizeEl ? parseInt(sizeEl.innerHTML) : 0;
        const indType = indicatorEl ? indicatorEl.className : '';

        if (indicatorEl) {
            defaultText = indicatorEl.innerHTML;
        }

        if (boxEl) {
            boxEl.style.pointerEvents = 'none';
            boxEl.style.overflow = 'hidden';
        }

        if (typeof window.fetch === 'function') {
            try {
                const response = await fetch('project.json');
                if (response && response.body) {
                    const reader = response.body.getReader();
                    const decoder = new TextDecoder();
                    let receivedLength = 0;
                    let data = '';

                    while (true) {
                        const { done, value } = await reader.read();
                        if (done) break;
                        receivedLength += value.length;
                        data += decoder.decode(value, { stream: true });

                        if (indicatorEl) {
                            if (indType === 'ind2' && totalSize > 0) {
                                indicatorEl.innerHTML = `${defaultText}<div>${(receivedLength / totalSize * 100).toFixed(1)} %</div>`;
                            } else if (indType === 'ind3' && totalSize > 0) {
                                indicatorEl.innerHTML = `${defaultText}<div>${(receivedLength / 1e6).toFixed(1)}/${(totalSize / 1e6).toFixed(1)} MB</div>`
                            } else {
                                indicatorEl.innerHTML = `${defaultText}<div>${(receivedLength / 1e6).toFixed(1)} MB</div>`;
                            }
                        }
                    }

                    if (boxEl) {
                        boxEl.style.height = '0';
                    }
                    const json = JSON.parse(data);
                    const cleanedData = removeNulls(json);
                    const parsed = AppSchema.safeParse(cleanedData);

                    if (parsed.success) {
                        initializeApp(parsed.data);
                        if (app.preloadExternalImages && externalImages.size > 0) {
                            await loadImagesSequentially(externalImages);
                        }
                        setTimeout(() => {
                            const styleEl = document.createElement('style');
                            document.head.appendChild(styleEl);
                            setTimeout(() => {
                                if (boxEl) {
                                    boxEl.style.height = '';
                                    boxEl.style.opacity = '1';
                                    boxEl.style.overflow = '';
                                    boxEl.style.pointerEvents = '';
                                }
                                if (indicatorEl) indicatorEl.remove();
                                if (sizeEl) sizeEl.remove();
                                if (styleEl.sheet) styleEl.sheet.insertRule("body::before{opacity:0;transition:opacity 2s}", 0);
                            }, 1000);
                        }, 1000);
                        await checkAvifSupport();
                    } else {
                        snackbarVariables.labelText = 'Failed to load data.';
                        snackbarVariables.isOpen = true;
                        console.error(parsed.error);
                    }
                }
            } catch (error) {
                console.error(error);
                if (boxEl) {
                    boxEl.style.height = '0';
                }
                const json = JSON.parse(JSON.stringify(app));
                initializeApp(json);
                if (app.preloadExternalImages && externalImages.size > 0) {
                    await loadImagesSequentially(externalImages);
                }
                setTimeout(() => {
                    const styleEl = document.createElement('style');
                    document.head.appendChild(styleEl);
                    setTimeout(() => {
                        if (boxEl) {
                            boxEl.style.height = '';
                            boxEl.style.opacity = '1';
                            boxEl.style.overflow = '';
                            boxEl.style.pointerEvents = '';
                        }
                        if (indicatorEl) indicatorEl.remove();
                        if (sizeEl) sizeEl.remove();
                        if (styleEl.sheet) styleEl.sheet.insertRule("body::before{opacity:0;transition:opacity 2s}", 0);
                    }, 1000);
                }, 1000);
                await checkAvifSupport();
            }
        } else {
            const xhr = new XMLHttpRequest();
            xhr.open('GET', 'project.json', true);

			xhr.onprogress = (e) => {
                if (indicatorEl) {
                    if (indType === 'ind2' && totalSize > 0) {
                        indicatorEl.innerHTML = `${defaultText}<div>${(e.loaded / totalSize * 100).toFixed(1)} %</div>`;
                    } else if (indType === 'ind3' && totalSize > 0) {
                        indicatorEl.innerHTML = `${defaultText}<div>${(e.loaded / 1e6).toFixed(1)}/${(totalSize / 1e6).toFixed(1)} MB</div>`;
                    } else {
                        indicatorEl.innerHTML = `${defaultText}<div>${(e.loaded / 1e6).toFixed(1)} MB</div>`;
                    }
                }
			};

			xhr.onload = async () => {
                if (boxEl) {
                    boxEl.style.height = '0';
                }
				if (xhr.status === 200) {
					const json = JSON.parse(xhr.responseText);
					initializeApp(json);

					if (app.preloadExternalImages && app.externalImages.size > 0) {
						await loadImagesSequentially(app.externalImages);
					}
				} else {
                    const json = JSON.parse(JSON.stringify(app));
					initializeApp(json);
				}
				setTimeout(() => {
                    const styleEl = document.createElement('style');
                    document.head.appendChild(styleEl);
                    setTimeout(() => {
                        if (boxEl) {
                            boxEl.style.height = '';
                            boxEl.style.opacity = '1';
                            boxEl.style.overflow = '';
                            boxEl.style.pointerEvents = '';
                        }
                        if (indicatorEl) indicatorEl.remove();
                        if (sizeEl) sizeEl.remove();
                        if (styleEl.sheet) styleEl.sheet.insertRule("body::before{opacity:0;transition:opacity 2s}", 0);
                    }, 1000);
                }, 1000);
                await checkAvifSupport();
			};

			xhr.send();
        }
    }

async function performSearch() {
    // This will cause the menu to be rerendered, so we should preserve
    // focus if the menu is focused.
    if (focused && !isInputFocused()) {
      focus();
    }

    loadingState += 1;
    errorState = false;
    if (typeof text === 'undefined') text = '';
    try {
      const searchResult = await search(text);
      if (searchResult !== false) {
        matches = searchResult;
        if (selectOnExactMatch) {
          const exactMatch = matches.find(
            (match) => getOptionLabel(match) === text,
          );
          if (exactMatch != null && getOptionLabel(value) !== text) {
            selectOption(exactMatch);
          }
        }
      }
    } catch (e: any) {
      errorState = true;
    }
    loadingState -= 1;
  }

function selectOption(option: any, setText = true) {
    const event = dispatch(getElement(), 'SMUIAutocompleteSelected', option, {
      bubbles: true,
      cancelable: true,
    });

    if (event.defaultPrevented) {
      return;
    }

    if (isSearch) {
      text = getOptionLabel(option);
      performSearch();
      tick().then(() => {  
        sResult = matches;
        blur();
      });
      return;
    }

    if (multiple && multipleValue) {
      multipleValue.push(option);
      if (setText) {
        text = '';
      }
    } else {
      if (setText) {
        text = getOptionLabel(option);
      }
      value = option;
      if (!setText) {
        previousValue = option;
      }
      tick().then(() => blur());
    }
  }

function deselectOption(option: any, setText = true) {
    const event = dispatch(getElement(), 'SMUIAutocompleteDeselected', option, {
      bubbles: true,
      cancelable: true,
    });

    if (event.defaultPrevented) {
      return;
    }

    if (multiple && multipleValue) {
      let index = multipleValue.indexOf(option);
      multipleValue.splice(index, 1);
    } else {
      if (setText) {
        text = '';
      }
      value = undefined;
      if (!setText) {
        previousValue = undefined;
      }
      visibleCounter = 24;
    }
  }

function toggleOption(option: any) {
    if (multiple) {
      if (multipleValue && multipleValue.includes(option)) {
        deselectOption(option);
      } else {
        selectOption(option);
      }
    } else {
      if (option === value) {
        deselectOption(option);
      } else {
        selectOption(option);
      }
    }
  }

function isInViewport(elem: Element) {
    var bounding = elem.getBoundingClientRect();
    return (
      bounding.top >= 0 &&
      bounding.left >= 0 &&
      bounding.bottom <=
        (window.innerHeight || document.documentElement.clientHeight) &&
      bounding.right <=
        (window.innerWidth || document.documentElement.clientWidth)
    );
  }

