export function wrapAudioPlayer(audio: HTMLAudioElement): MusicPlayer {
    let muted = false;
    let lastVolume = 1;
    let canSeek = false;
    let stopped = true;

    audio.addEventListener('loadedmetadata', () => {
        canSeek = Number.isFinite(audio.duration) && audio.seekable && audio.seekable.length > 0;
        if (canSeek) bgmVariables.curBgmLength = audio.duration;
    });

    audio.addEventListener('play', () => {
        stopped = false;
    });

    audio.addEventListener('ended', () => {
        stopped = true;
    });

    return {
        type: 'audio',
        load(url, options) {
            audio.src = url;
            audio.loop = !!options?.loop;
            audio.load();

            stopped = true;
            canSeek = false;
        },
        play: () => audio.play().catch((e) => {
            stopped = true;
            console.warn(e);
            throw e;
        }),
        pause: () => audio.pause(),
        stop: () => {
            audio.pause();
            if (canSeek) audio.currentTime = 0;
            stopped = true;
        },
        mute: () => {
            muted = true;
            audio.muted = true;
        },
        unMute: () => {
            muted = false;
            audio.muted = false;
        },

        setVolume: (v) => {
            lastVolume = v / 100;
            if (!muted) {
                audio.volume = lastVolume;
            }
        },

        isPlaying: () => !audio.paused && !stopped,
        isStopped: () => stopped,
        isMuted: () => muted,

        seekTo: (sec: number) => {
            if (!canSeek) return false;

            try {
                audio.currentTime = sec;
                return true;
            } catch {
                return false;
            }
        },

        getCurrentTime: () => canSeek ? audio.currentTime : 0,
        getDuration: () => canSeek ? audio.duration : 0,
        getPlayerState: () => audio.paused ? 2 : 1,

        getTitle: () => audio.src.split('/').pop() ?? '',
        getId: () => audio.src
    }
}

