async function selectForceActivate(localChoice: Choice | SelectableAddon, fChoice: Choice | SelectableAddon, fRow: Row, num: number, options: ChoiceOptions) {
    if (fChoice.isNotSelectable && localChoice.isNotActiveUnselectable) return;

    options.isLinked = false;
    options.isForced = true;
    options.isAllowDeselect = localChoice.isAllowDeselect;

    if (fChoice.activateOtherChoice && typeof fChoice.activateThisChoice !== 'undefined' && options.linkedObjects.indexOf(localChoice.id) === -1 && fChoice.activateThisChoice.split(',').some(item => item.split('/ON#')[0] === localChoice.id)) {
        options.linkedObjects.push(localChoice.id);
        options.isLinked = true;
    }
    if (fChoice.isSelectableMultiple) {
        if (fChoice.isMultipleUseVariable && typeof fChoice.numMultipleTimesMinus !== 'undefined' && typeof fChoice.numMultipleTimesPluss !== 'undefined') {
            if (num > 0) {
                for (let i = 0; i < num; i++) {
                    await selectedOneMore(fChoice, fRow, options);
                }
            } else if (num < 0) {
                for (let i = 0; i > (num * -1); i++) {
                    await selectedOneLess(fChoice, fRow, options);
                }
            }
        }
    } else {
        if (!fChoice.isActive) {
            await selectObject(fChoice, fRow, options);
        } else {
            if (!options.isAllowDeselect) {
                fChoice.forcedActivated = true;
                if (typeof fChoice.activatedFrom === 'undefined') fChoice.activatedFrom = 0;
                fChoice.activatedFrom += 1;
            }
        }
    }
}

async function deselectTempActivate(localChoice: Choice | SelectableAddon, fChoice: Choice | SelectableAddon, num: number) {
    const tmpAct = tmpActivatedMap.get(fChoice.id);
    if (typeof tmpAct === 'undefined') return;

    let tmpNum = 0;

    if (fChoice.isSelectableMultiple && fChoice.isMultipleUseVariable) {
        tmpNum = tmpAct.multiple - num;
        if (tmpNum === 0) {
            tmpActivatedMap.delete(fChoice.id);
        } else {
            tmpActivatedMap.set(fChoice.id, {multiple: tmpNum, isAllowDeselect: localChoice.isAllowDeselect || false});
        }
    } else {
        if (typeof tmpAct.activatedFrom !== 'undefined') {
            tmpAct.activatedFrom -= 1;
        }
        if (!tmpAct.activatedFrom && !fChoice.isAutoActive) {
            tmpActivatedMap.delete(fChoice.id);
        }
    }
}

async function deselectForceActivate(localChoice: Choice | SelectableAddon, fChoice: Choice | SelectableAddon, fRow: Row, num: number, options: ChoiceOptions) {
    options.isOverDlg = true;
    options.isOverImg = true;
    if (fChoice.activateOtherChoice && typeof fChoice.activateThisChoice !== 'undefined' && options.linkedObjects.indexOf(localChoice.id) === -1 && fChoice.activateThisChoice.split(',').some(item => item.split('/ON#')[0] === localChoice.id)) {
        options.linkedObjects.push(localChoice.id);
    }
    if (fChoice.isActive) {
        if (fChoice.isSelectableMultiple) {
            if (fChoice.isMultipleUseVariable && typeof fChoice.numMultipleTimesMinus !== 'undefined' && typeof fChoice.numMultipleTimesPluss !== 'undefined') {
                if (num > 0) {
                    for (let i = 0; i < num; i++) {
                        if (!localChoice.isAllowDeselect) fChoice.numMultipleTimesMinus -= 1;
                        if (!localChoice.isNotDeactivate) {
                            if (fChoice.isDeselectDelayed || fChoice.isFadeTransition) {
                                selectedOneLess(fChoice, fRow, options);
                            } else {
                                await selectedOneLess(fChoice, fRow, options);
                            }
                        }
                    }
                } else if (num < 0) {
                    for (let i = 0; i > (num * -1); i++) {
                        if (!localChoice.isAllowDeselect) fChoice.numMultipleTimesPluss += 1;
                        if (!localChoice.isNotDeactivate) {
                            if (fChoice.isDeselectDelayed || fChoice.isFadeTransition) {
                                selectedOneMore(fChoice, fRow, options);
                            } else {
                                await selectedOneMore(fChoice, fRow, options);
                            }
                        }
                    }
                }
            }
        } else {
            if (typeof fChoice.activatedFrom !== 'undefined') {
                fChoice.activatedFrom -= 1;
                if (fChoice.activatedFrom <= 0 || options.linkedObjects.indexOf(localChoice.id) !== -1) {
                    delete fChoice.activatedFrom;
                    delete fChoice.forcedActivated;
                    if (!localChoice.isNotDeactivate) {
                        if (fChoice.isDeselectDelayed || fChoice.isFadeTransition) {
                            deselectObject(fChoice, fRow, options);
                        } else {
                            await deselectObject(fChoice, fRow, options);
                        }
                    }
                }
            } else {
                delete fChoice.forcedActivated;
                if (!localChoice.isNotDeactivate && fChoice.isActive) {
                    if (fChoice.isDeselectDelayed || fChoice.isFadeTransition) {
                        deselectObject(fChoice, fRow, options);
                    } else {
                        await deselectObject(fChoice, fRow, options);
                    }
                }
            }
        }
    } else {
        await deselectTempActivate(localChoice, fChoice, num);
    }
}

async function selectForceRandomActivate(localChoice: Choice | SelectableAddon, options: ChoiceOptions) {
    if (typeof localChoice.activateThisChoice !== 'undefined') {
        let forceList = localChoice.activateThisChoice.split(',');
        let listMap = new Map<string, number>();
        for (let i = 0; i < forceList.length; i++) {
            let [key, val = '0'] = forceList[i].split('/ON#');
            let num = parseInt(val);
            let group = groupMap.get(key);
            if (typeof group !== 'undefined') {
                for (let j = 0; j < group.elements.length; j++) {
                    const cMap = choiceMap.get(group.elements[j]);

                    if (typeof cMap !== 'undefined') {
                        const gChoice = cMap.choice;
                        const reqCheck = gChoice.isSelectableMultiple && gChoice.isMultipleUseVariable && typeof gChoice.numMultipleTimesPluss !== 'undefined' && gChoice.numMultipleTimesPluss >= gChoice.multipleUseVariable + num && !gChoice.isInfoRow && !gChoice.isNotSelectable && checkRequirements(gChoice.requireds);
                        if (!activatedMap.has(gChoice.id) || reqCheck) {
                            listMap.set(gChoice.id, num);
                        }
                    }
                }
            } else {
                const cMap = choiceMap.get(key);

                if (typeof cMap !== 'undefined') {
                    const lChoice = cMap.choice;
                    const reqCheck = lChoice.isSelectableMultiple && lChoice.isMultipleUseVariable && typeof lChoice.numMultipleTimesPluss !== 'undefined' && lChoice.numMultipleTimesPluss >= lChoice.multipleUseVariable + num && !lChoice.isInfoRow && !lChoice.isNotSelectable && checkRequirements(lChoice.requireds);

                    if (!activatedMap.has(key) || reqCheck) {
                        listMap.set(key, num);
                    }
                }
            }
        }
        let listArray = [...listMap.keys()];
        let actNum = Math.min(listArray.length, localChoice.numActivateRandom || 0);
        let repeatNum = actNum;
        for (let i = listArray.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [listArray[i], listArray[j]] = [listArray[j], listArray[i]];
        }
        let result: string[] = [];
        for (let i = 0; i < actNum;) {
            const id = listArray[i];
            const cMap = choiceMap.get(id);
            if (typeof cMap !== 'undefined') {
                const rndRow = cMap.row;
                const rndChoice = cMap.choice;
                const choiceNum = listMap.get(id) || 0;
                const rndNum = rndChoice.multipleUseVariable;

                await selectForceActivate(localChoice, rndChoice, rndRow, choiceNum, options);
                if (!rndChoice.isActive || (rndChoice.isSelectableMultiple && rndChoice.isMultipleUseVariable && rndChoice.multipleUseVariable === rndNum)) {
                    if (result.length < actNum && listArray.length > repeatNum) {
                        listArray[i] = listArray[repeatNum++];
                        if (typeof rndChoice.activatedFrom !== 'undefined') {
                            rndChoice.activatedFrom -= 1;
                            if (rndChoice.activatedFrom === 0) tmpActivatedMap.delete(rndChoice.id);
                        }
                        continue;
                    } else {
                        break;
                    }
                }
                let item = choiceNum > 0 ? `${id}/ON#${choiceNum}` : id;
                result.push(item);
            }
            i++;
        }

        if (localChoice.isSelectableMultiple) {
            if (typeof localChoice.activatedRandomMul === 'undefined') localChoice.activatedRandomMul = [];
            localChoice.activatedRandomMul[localChoice.multipleUseVariable - 1] = [...result];
        } else {
            localChoice.activatedRandom = [...result];
        }
    }
}

async function removeCount(localChoice: Choice | SelectableAddon, dChoice: Choice | SelectableAddon) {
    if (typeof dChoice.appliedDisChoices === 'undefined') return;

    const idx = dChoice.appliedDisChoices.indexOf(localChoice.id);
    if (idx === DISABLED) return;

    dChoice.appliedDisChoices.splice(idx, 1);
    const dList = new Set(dChoice.appliedDisChoices);
    const nList = new Set();
    if (dChoice.isDisChoices) {
        if (typeof dChoice.discountRows !== 'undefined') {
            for (let i = 0; i < dChoice.discountRows.length; i++) {
                const tRow = rowMap.get(dChoice.discountRows[i]);
                if (typeof tRow !== 'undefined') {
                    for (let j = 0; j < tRow.objects.length; j++) {
                        const tChoice = tRow.objects[j];
                        if (!dList.has(tChoice.id) || (tChoice.isSelectableMultiple && dChoice.countPerSelection)) {
                            await emptyDiscount(dChoice, tChoice);
                            nList.add(tChoice.id);
                        }
                    }
                }
            }
        }
        if (typeof dChoice.discountChoices !== 'undefined') {
            for (let i = 0; i < dChoice.discountChoices.length; i++) {
                const cMap = choiceMap.get(dChoice.discountChoices[i]);
                if (typeof cMap !== 'undefined') {
                    const tChoice = cMap.choice;

                    if (!nList.has(tChoice.id) && !dList.has(tChoice.id) || (tChoice.isSelectableMultiple && dChoice.countPerSelection)) {
                        await emptyDiscount(dChoice, tChoice);
                    }
                }
            }
        }
    } else {
        if (typeof dChoice.discountGroups !== 'undefined') {
            for (let i = 0; i < dChoice.discountGroups.length; i++) {
                const groupData = groupMap.get(dChoice.discountGroups[i]);
                if (typeof groupData !== 'undefined') {
                    for (let j = 0; j < groupData.elements.length; j++) {
                        const cMap = choiceMap.get(groupData.elements[j]);
                        if (typeof cMap !== 'undefined') {
                            const tChoice = cMap.choice;

                            if (!dList.has(tChoice.id) || (tChoice.isSelectableMultiple && dChoice.countPerSelection)) {
                                await emptyDiscount(dChoice, tChoice);
                            }
                        }
                    }
                }
            }
        }
    }
}

async function addCount(localChoice: Choice | SelectableAddon, dChoice: Choice | SelectableAddon) {
    if (!dChoice.discountCount) return;

    let count = dChoice.discountCount * (dChoice.isSelectableMultiple && dChoice.isMultipleUseVariable ? dChoice.multipleUseVariable : 1);

    if (typeof dChoice.appliedDisChoices === 'undefined') dChoice.appliedDisChoices = [];

    if (!localChoice.isSelectableMultiple && dChoice.appliedDisChoices.indexOf(localChoice.id) !== DISABLED) return;

    if (localChoice.isSelectableMultiple && dChoice.countPerSelection) {
        if (dChoice.appliedDisChoices.length < count && dChoice.appliedDisChoices.filter(id => id === localChoice.id).length < localChoice.multipleUseVariable) dChoice.appliedDisChoices.push(localChoice.id);
    } else {
        if (dChoice.appliedDisChoices.indexOf(localChoice.id) !== DISABLED) return;
        dChoice.appliedDisChoices.push(localChoice.id);
    }

    if (dChoice.appliedDisChoices.length < count) return;

    const dList = new Set(dChoice.appliedDisChoices);
    const nList = new Set();
    if (dChoice.isDisChoices) {
        if (typeof dChoice.discountRows !== 'undefined') {
            for (let i = 0; i < dChoice.discountRows.length; i++) {
                const tRow = rowMap.get(dChoice.discountRows[i]);
                if (typeof tRow !== 'undefined') {
                    for (let j = 0; j < tRow.objects.length; j++) {
                        const tChoice = tRow.objects[j];
                        if (!dList.has(tChoice.id) || (tChoice.isSelectableMultiple && dChoice.countPerSelection)) {
                            await fillDiscount(dChoice, tChoice);
                            nList.add(tChoice.id);
                        }
                    }
                }
            }
        }
        if (typeof dChoice.discountChoices !== 'undefined') {
            for (let i = 0; i < dChoice.discountChoices.length; i++) {
                const cMap = choiceMap.get(dChoice.discountChoices[i]);
                if (typeof cMap !== 'undefined') {
                    const tChoice = cMap.choice;

                    if (!nList.has(tChoice.id) && !dList.has(tChoice.id) || (tChoice.isSelectableMultiple && dChoice.countPerSelection)) {
                        await fillDiscount(dChoice, tChoice);
                    }
                }
            }
        }
    } else {
        if (typeof dChoice.discountGroups !== 'undefined') {
            for (let i = 0; i < dChoice.discountGroups.length; i++) {
                const groupData = groupMap.get(dChoice.discountGroups[i]);
                if (typeof groupData !== 'undefined') {
                    for (let j = 0; j < groupData.elements.length; j++) {
                        const cMap = choiceMap.get(groupData.elements[j]);
                        if (typeof cMap !== 'undefined') {
                            const tChoice = cMap.choice;

                            if (!dList.has(tChoice.id) || (tChoice.isSelectableMultiple && dChoice.countPerSelection)) {
                                await fillDiscount(dChoice, tChoice);
                            }
                        }
                    }
                }
            }
        }
    }
}

async function updateCount(localChoice: Choice | SelectableAddon, dChoice: Choice | SelectableAddon) {
    if (typeof dChoice.appliedDisChoices === 'undefined') return;

    let totalNum = 0;
    let appliedNum = 0;

    for (let i = 0; i < localChoice.scores.length; i++) {
        const score = localChoice.scores[i];
        if (typeof score.discounts === 'undefined' || score.discounts.length === 0) continue;

        for (let j = 0; j < score.discounts.length; j++) {
            const dc = score.discounts[j];

            if (dc.id === dChoice.id) {
                if (dc.state === ACTIVE) appliedNum += 1;
                totalNum += 1;
            }
        }
    }

    if (appliedNum === totalNum) await removeCount(localChoice, dChoice);
}

async function deselectUpdateScore(localChoice: Choice | SelectableAddon, localRow: Row, tmpScores: TempScore, count: number, changedScores = new Set<string>(), scoreUpdate: string[] = [], options: ChoiceOptions) {
    const activated = Array.from(activatedMap.keys());
    const newOptions = {...options};
    newOptions.isOverDlg = true;
    newOptions.isOverImg = true;

    for (let i = 0; i < activated.length; i++) {
        const id = activated[i];
        const cMap = choiceMap.get(id);
        if (typeof cMap === 'undefined') continue;

        const aRow = cMap.row;
        const aChoice = cMap.choice;
        if (!aChoice.isActive) continue;

        const thisTmpScores = new SvelteMap<string, number>();
        const addSet = new Set<Choice | SelectableAddon>();
        const removeSet = new Set<Choice | SelectableAddon>();
        let isChanged = false;
        for (let j = 0; j < aChoice.scores.length; j++) {
            const aScore = aChoice.scores[j];
            if (aScore.isNotRecalculatable) continue;

            const point = pointTypeMap.get(aScore.id);
            if (typeof point === 'undefined') continue;

            const isActive = aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable ? true : aScore.isActive;

            if (aScore.isChangeDiscount && isActive && typeof aScore.tmpDisScore !== 'undefined') {
                if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                    let mul = aChoice.multipleUseVariable;
                    let isChangedMul = false;
                    let totalScore = 0;

                    if (aScore.discounts) {
                        for (let k = 0; k < aScore.discounts.length; k++) {
                            const dc = aScore.discounts[k];
                            if (dc.state !== INACTIVE) {
                                const dMap = choiceMap.get(dc.id);

                                if (typeof dMap !== 'undefined') {
                                    const dChoice = dMap.choice;

                                    if (typeof dChoice.appliedDisChoices !== 'undefined' && dChoice.countPerSelection) {
                                        const count = dChoice.appliedDisChoices.filter(id => id === aChoice.id).length;
                                        if (count === 0) continue;
                                        mul = mul - count;
                                        break;
                                    }
                                }
                            }
                        }
                    }
                    for (let k = mul - 1; k >= 0; k--) {
                        if (!aChoice.isActive || !aScore.isActiveMul) break;
                        if (!aScore.isActiveMul[k]) continue;
                        let tmpScore = aScore.multiplyByTimes ? aScore.tmpDisScore * (k + 1) : aScore.tmpDisScore;
                        if (point.belowZeroNotAllowed && point.startingSum + tmpScore < 0) {
                            if (aChoice.forcedActivated) {
                                aChoice.numMultipleTimesMinus--;
                                await selectedOneLess(aChoice, aRow, newOptions);

                                const tmpAct = tmpActivatedMap.get(aChoice.id);
                                if (typeof tmpAct !== 'undefined') {
                                    tmpAct.multiple += 1;
                                } else {
                                    tmpActivatedMap.set(aChoice.id, {multiple: 1, activatedFrom: aChoice.activatedFrom});
                                }
                            } else {
                                await selectedOneLess(aChoice, aRow, newOptions);
                            }
                            isChangedMul = true;
                            break;
                        } else {
                            point.startingSum += tmpScore;
                            totalScore += tmpScore;
                            isChangedMul = true;
                        }
                    }

                    delete aScore.isChangeDiscount;
                    delete aScore.tmpDisScore;

                    if (!aChoice.isActive) break;

                    thisTmpScores.set(aScore.id, totalScore);

                    if (isChangedMul) {
                        isChanged = localChoice.id !== aChoice.id;
                    }
                } else if (!aChoice.isSelectableMultiple) {
                    if (point.belowZeroNotAllowed && point.startingSum + aScore.tmpDisScore < 0) {
                        if (aChoice.forcedActivated) {
                            delete aChoice.forcedActivated;
                            tmpActivatedMap.set(aChoice.id, {multiple: aChoice.multipleUseVariable, activatedFrom: aChoice.activatedFrom});
                        }
                        await deselectObject(aChoice, aRow, newOptions);
                    } else {
                        point.startingSum += aScore.tmpDisScore;
                        thisTmpScores.set(aScore.id, aScore.tmpDisScore);
                        delete aScore.isChangeDiscount;
                        delete aScore.tmpDisScore;
                    }

                    if (!aChoice.isActive) break;

                    isChanged = localChoice.id !== aChoice.id;
                }

                if (isChanged) {
                    if (aScore.appliedDiscount && typeof aScore.discounts !== 'undefined') {
                        for (let k = 0; k < aScore.discounts.length; k++) {
                            const dc = aScore.discounts[k];

                            if (dc.state === ACTIVE && dc.count !== DISABLED) {
                                const cMap = choiceMap.get(dc.id);

                                if (typeof cMap !== 'undefined') {
                                    const dChoice = cMap.choice;

                                    if (!deselectQue.has(dChoice.id)) addSet.add(dChoice);
                                }
                            }
                        }
                    }
                }
            } else {
                delete aScore.isChangeDiscount;
                delete aScore.tmpDisScore;
            }
            if (!changedScores.has(aScore.idx)) {
                const hasScore = localChoice.scores.length > 0;
                const scoreLeng = localChoice.scores.length || 1;
                for (let k = 0; k < scoreLeng; k++) {
                    if (!aChoice.isActive) break;

                    const lScore = hasScore ? localChoice.scores[k] : null;
                    const tmpScore = lScore ? (tmpScores.get(lScore.id) || 0) : 0;
                    const lPoint = lScore ? pointTypeMap.get(lScore.id) : null;
                    if (hasScore && !lPoint) continue;

                    const afterDeselected = checkRequirements(aScore.requireds);
                    const tmpActivated = new SvelteMap<string, ActivatedMap>([...activatedMap].map(([key, value]) => [key, {...value}]));
                    const isMultiple = localChoice.isSelectableMultiple && localChoice.isMultipleUseVariable;
                    if (isMultiple) {
                        if (localChoice.multipleUseVariable === -1) {
                            tmpActivated.delete(localChoice.id);
                            localRow.currentChoices -= 1;
                        } else {
                            tmpActivated.set(localChoice.id, {multiple: localChoice.multipleUseVariable + 1});
                            if (localChoice.multipleUseVariable === 0) {
                                localRow.currentChoices += 1;
                            }
                        }
                    } else {
                        tmpActivated.set(localChoice.id, {multiple: 0});
                        localRow.currentChoices += 1;
                    }
                    if (lPoint) lPoint.startingSum += tmpScore;
                    const beforeDeselected = checkRequirements(aScore.requireds, tmpActivated);
                    if (isMultiple) {
                        if (localChoice.multipleUseVariable === -1) {
                            localRow.currentChoices += 1;
                        } else if (localChoice.multipleUseVariable === 0) {
                            localRow.currentChoices -= 1;
                        }
                    } else {
                        localRow.currentChoices -= 1;
                    }
                    if (lPoint) lPoint.startingSum -= tmpScore;
                    if (beforeDeselected === afterDeselected) continue;

                    if (!aScore.setValue) setScoreValue(point, aScore, aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable, aChoice.multipleUseVariable);
                    let scoreVal = aScore.appliedDiscount && typeof aScore.discountScore !== 'undefined' ? aScore.discountScore : aScore.value;
                    scoreVal = point.allowFloat ? scoreVal : Math.floor(scoreVal);
                    if (beforeDeselected) {
                        if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                            const mul = aChoice.multipleUseVariable;

                            for (let l = mul - 1; l >= 0; l--) {
                                if (typeof aScore.isActiveMul !== 'undefined' && aScore.isActiveMul[l]) {
                                    const sValue = aScore.multiplyByTimes ? scoreVal * (l + 1) : scoreVal;
                                    if (point.belowZeroNotAllowed && point.startingSum + sValue < 0) {
                                        if (aChoice.forcedActivated) {
                                            aChoice.numMultipleTimesMinus--;
                                            await selectedOneLess(aChoice, aRow, newOptions);

                                            const tmpAct = tmpActivatedMap.get(aChoice.id);
                                            if (typeof tmpAct !== 'undefined') {
                                                tmpAct.multiple += 1;
                                            } else {
                                                tmpActivatedMap.set(aChoice.id, {multiple: 1, activatedFrom: aChoice.activatedFrom});
                                            }
                                        } else {
                                            await selectedOneLess(aChoice, aRow, newOptions);
                                        }
                                        break;
                                    } else {
                                        point.startingSum += sValue;
                                        thisTmpScores.set(aScore.id, sValue);
                                        aScore.isActiveMul[l] = false;
                                    }
                                }
                            }
                        } else if (!aChoice.isSelectableMultiple) {
                            if (aScore.isActive) {
                                if (point.belowZeroNotAllowed && point.startingSum + scoreVal < 0) {
                                    if (aChoice.forcedActivated) delete aChoice.forcedActivated;
                                    await deselectObject(aChoice, aRow, newOptions);
                                } else {
                                    point.startingSum += scoreVal;
                                    thisTmpScores.set(aScore.id, scoreVal);
                                    delete aScore.isActive;
                                }
                            }
                        }
                        if (aScore.setValue) delete aScore.setValue;
                        if (aScore.appliedDiscount && typeof aScore.discounts !== 'undefined') {
                            for (let k = 0; k < aScore.discounts.length; k++) {
                                const dc = aScore.discounts[k];

                                if (dc.state === ACTIVE && dc.count !== DISABLED) {
                                    const cMap = choiceMap.get(dc.id);

                                    if (typeof cMap !== 'undefined') {
                                        const dChoice = cMap.choice;

                                        if (!addSet.has(dChoice)) {
                                            removeSet.add(dChoice);
                                        }
                                    }
                                }
                            }
                        }
                    } else {
                        if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                            const mul = aChoice.multipleUseVariable;
                            if (typeof aScore.isActiveMul === 'undefined') aScore.isActiveMul = [];
                            for (let l = mul - 1; l >= 0; l--) {
                                if (!aScore.isActiveMul[l]) {
                                    const sValue = aScore.multiplyByTimes ? scoreVal * (l + 1) : scoreVal;
                                    if (point.belowZeroNotAllowed && point.startingSum + sValue < 0) {
                                        if (aChoice.forcedActivated) {
                                            aChoice.numMultipleTimesMinus--;
                                            await selectedOneLess(aChoice, aRow, newOptions);

                                            const tmpAct = tmpActivatedMap.get(aChoice.id);
                                            if (typeof tmpAct !== 'undefined') {
                                                tmpAct.multiple += 1;
                                            } else {
                                                tmpActivatedMap.set(aChoice.id, {multiple: 1, activatedFrom: aChoice.activatedFrom});
                                            }
                                        } else {
                                            await selectedOneLess(aChoice, aRow, newOptions);
                                        }
                                        break;
                                    } else {
                                        point.startingSum -= sValue;
                                        thisTmpScores.set(aScore.id, sValue);
                                        aScore.isActiveMul[l] = true;
                                    }
                                }
                            }
                        } else if (!aChoice.isSelectableMultiple) {
                            if (!aScore.isActive) {
                                if (point.belowZeroNotAllowed && point.startingSum - scoreVal < 0) {
                                    if (aChoice.forcedActivated) {
                                        delete aChoice.forcedActivated;
                                        tmpActivatedMap.set(aChoice.id, {multiple: aChoice.multipleUseVariable, activatedFrom: aChoice.activatedFrom});
                                    }
                                    await deselectObject(aChoice, aRow, newOptions);
                                } else {
                                    point.startingSum -= scoreVal;
                                    thisTmpScores.set(aScore.id, scoreVal);
                                    aScore.isActive = true;
                                }
                            }
                        }
                        if (aScore.appliedDiscount && typeof aScore.discounts !== 'undefined') {
                            for (let k = 0; k < aScore.discounts.length; k++) {
                                const dc = aScore.discounts[k];

                                if (dc.state === ACTIVE && dc.count !== DISABLED) {
                                    const cMap = choiceMap.get(dc.id);

                                    if (typeof cMap !== 'undefined') {
                                        const dChoice = cMap.choice;

                                        addSet.add(dChoice);
                                    }
                                }
                            }
                        }
                    }
                    if (!isChanged) {
                        isChanged = true;
                    }
                    changedScores.add(aScore.idx);
                    if (!aChoice.isActive) break;
                }
            }
            if (!isChanged) {
                if (aScore.useExpression) {
                    const oldVal = aScore.value;

                    setScoreValue(point, aScore, aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable, aChoice.multipleUseVariable - 1);
                    if (oldVal !== aScore.value) {
                        let expVal = oldVal - aScore.value;
                        if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                            const mul = aChoice.multipleUseVariable;

                            for (let l = mul - 1; l >= 0; l--) {
                                if (typeof aScore.isActiveMul !== 'undefined' && aScore.isActiveMul[l]) {
                                    const sValue = aScore.multiplyByTimes ? expVal * (l + 1) : expVal;
                                    if (point.belowZeroNotAllowed && point.startingSum + sValue < 0) {
                                        if (aChoice.forcedActivated) {
                                            aChoice.numMultipleTimesMinus--;
                                            await selectedOneLess(aChoice, aRow, newOptions);

                                            const tmpAct = tmpActivatedMap.get(aChoice.id);
                                            if (typeof tmpAct !== 'undefined') {
                                                tmpAct.multiple += 1;
                                            } else {
                                                tmpActivatedMap.set(aChoice.id, {multiple: 1, activatedFrom: aChoice.activatedFrom});
                                            }
                                        } else {
                                            await selectedOneLess(aChoice, aRow, newOptions);
                                        }
                                        isChanged = true;
                                        changedScores.add(aScore.idx);
                                        break;
                                    } else {
                                        point.startingSum += sValue;
                                        thisTmpScores.set(aScore.id, sValue);
                                        isChanged = true;
                                        changedScores.add(aScore.idx);
                                    }
                                }
                            }
                        } else if (!aChoice.isSelectableMultiple) {
                            if (aScore.isActive) {
                                if (point.belowZeroNotAllowed && point.startingSum + expVal < 0) {
                                    if (aChoice.forcedActivated) {
                                        delete aChoice.forcedActivated;
                                        tmpActivatedMap.set(aChoice.id, {multiple: aChoice.multipleUseVariable, activatedFrom: aChoice.activatedFrom});
                                    }
                                    await deselectObject(aChoice, aRow, newOptions);
                                } else {
                                    point.startingSum += expVal;
                                    thisTmpScores.set(aScore.id, expVal);
                                }
                                isChanged = true;
                                changedScores.add(aScore.idx);
                            }
                        }
                    }
                }
            }
        }
        if (removeSet.size > 0) {
            const arr = Array.from(removeSet);

            for (let i = 0; i < arr.length; i++) {
                const dChoice = arr[i];

                if (!addSet.has(dChoice)) await updateCount(aChoice, dChoice);
            }
        }
        if (addSet.size > 0) {
            const arr = Array.from(addSet);

            for (let i = 0; i < arr.length; i++) {
                const dChoice = arr[i];

                await addCount(aChoice, dChoice);
            }
        }
        if (isChanged) {
            scoreUpdate.length === 0 ? scoreUpdate.push(`Scores Updated On: ${aChoice.title}`) : scoreUpdate.push(`, ${aChoice.title}`);
            await deselectUpdateScore(aChoice, aRow, thisTmpScores, count + 1, changedScores, scoreUpdate, options);
        }
    }
    if (count === 0) {
        if (scoreUpdate.length > 0 && !app.hideScoresUpdated) {
            const tempDiv = document.createElement('div');

            tempDiv.innerHTML = scoreUpdate.join('');
            snackbarVariables.labelText = tempDiv.textContent || '';
            snackbarVariables.isOpen = true;
        }
        scoreUpdate.splice(0);
    }
}

export async function selectUpdateScore(localChoice: Choice | SelectableAddon | null, localRow: Row, tmpScores: TempScore, count: number, changedScores = new Set<string>(), scoreUpdate: string[] = [], options: ChoiceOptions) {
    const activated = Array.from(activatedMap.keys());

    for (let i = 0; i < activated.length; i++) {
        const id = activated[i];
        const cMap = choiceMap.get(id);
        if (typeof cMap === 'undefined') continue;

        const aRow = cMap.row;
        const aChoice = cMap.choice;
        const thisTmpScores = new SvelteMap<string, number>();
        const addSet = new Set<Choice | SelectableAddon>();
        const removeSet = new Set<Choice | SelectableAddon>();
        const newOptions = {...options};
        newOptions.isOverDlg = true;
        newOptions.isOverImg = true;

        let isChanged = false;
        if (localChoice && localChoice.useDiscountCount && !localChoice.appliedDisChoices) localChoice.appliedDisChoices = [];
        for (let j = 0; j < aChoice.scores.length; j++) {
            const aScore = aChoice.scores[j];
            if (aScore.isNotRecalculatable) continue;

            const point = pointTypeMap.get(aScore.id);
            if (typeof point === 'undefined') continue;

            const isActive = aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable ? true : aScore.isActive;

            if (aScore.appliedDiscount && aScore.isChangeDiscount && isActive && typeof aScore.tmpDisScore !== 'undefined') {
                if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                    let mul = aChoice.multipleUseVariable;
                    let isChangedMul = false;
                    let totalScore = 0;

                    if (aScore.discounts) {
                        for (let k = 0; k < aScore.discounts.length; k++) {
                            const dc = aScore.discounts[k];
                            if (dc.state !== INACTIVE) {
                                const dMap = choiceMap.get(dc.id);

                                if (typeof dMap !== 'undefined') {
                                    const dChoice = dMap.choice;

                                    if (typeof dChoice.appliedDisChoices !== 'undefined' && dChoice.countPerSelection) {
                                        const count = dChoice.appliedDisChoices.filter(id => id === aChoice.id).length;
                                        if (count === 0) continue;
                                        mul = mul - count;
                                        break;
                                    }
                                }
                            }
                        }
                    }
                    for (let k = mul - 1; k >= 0; k--) {
                        if (aChoice.isActive && aScore.isActiveMul && aScore.isActiveMul[k]) {
                            let tmpScore = aScore.multiplyByTimes ? aScore.tmpDisScore * (k + 1) : aScore.tmpDisScore;
                            if (point.belowZeroNotAllowed && point.startingSum + tmpScore < 0) {
                                if (aChoice.forcedActivated) {
                                    aChoice.numMultipleTimesMinus--;
                                    await selectedOneLess(aChoice, aRow, newOptions);

                                    const tmpAct = tmpActivatedMap.get(aChoice.id);
                                    if (typeof tmpAct !== 'undefined') {
                                        tmpAct.multiple += 1;
                                    } else {
                                        tmpActivatedMap.set(aChoice.id, {multiple: 1, activatedFrom: aChoice.activatedFrom});
                                    }
                                } else {
                                    await selectedOneLess(aChoice, aRow, newOptions);
                                }
                                isChangedMul = true;
                                break;
                            } else {
                                point.startingSum += tmpScore;
                                totalScore += tmpScore;
                                isChangedMul = true;
                            }
                        }
                    }

                    if (isChangedMul) {
                        isChanged = true;
                    }

                    thisTmpScores.set(aScore.id, totalScore);
                } else if (!aChoice.isSelectableMultiple) {
                    if (point.belowZeroNotAllowed && point.startingSum + aScore.tmpDisScore < 0) {
                        if (aChoice.forcedActivated) {
                            delete aChoice.forcedActivated;
                            tmpActivatedMap.set(aChoice.id, {multiple: aChoice.multipleUseVariable, activatedFrom: aChoice.activatedFrom});
                        }
                        await deselectObject(aChoice, aRow, options);
                    } else {
                        point.startingSum += aScore.tmpDisScore;
                        thisTmpScores.set(aScore.id, aScore.tmpDisScore);
                    }

                    isChanged = true;
                }

                if (isChanged) {
                    if (aScore.appliedDiscount && typeof aScore.discounts !== 'undefined') {
                        for (let k = 0; k < aScore.discounts.length; k++) {
                            const dc = aScore.discounts[k];

                            if (dc.state === ACTIVE && dc.count !== DISABLED) {
                                const cMap = choiceMap.get(dc.id);

                                if (typeof cMap !== 'undefined') {
                                    const dChoice = cMap.choice;

                                    addSet.add(dChoice);
                                }
                            }
                        }
                    }
                }
            }
            delete aScore.isChangeDiscount;
            delete aScore.tmpDisScore;

            if (!aChoice.isActive) break;

            let isChangedExp = false;
            let expVal = aScore.value;
            if (aScore.useExpression && !changedScores.has(aScore.idx)) {
                const oldVal = aScore.value;

                setScoreValue(point, aScore, aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable, aChoice.multipleUseVariable - 1);
                if (oldVal !== aScore.value) {
                    expVal = oldVal - aScore.value;
                    if (!isChangedExp) {
                        isChangedExp = true;
                    }
                }
            }
            if (!changedScores.has(aScore.idx)) {
                const hasScore = localChoice && localChoice.scores.length > 0;
                const scoreLeng = localChoice && localChoice.scores.length || 1;
                for (let k = 0; k < scoreLeng; k++) {
                    if (!aChoice.isActive) break;

                    const lScore = hasScore ? localChoice.scores[k] : null;
                    const tmpScore = lScore ? (tmpScores.get(lScore.id) || 0) : 0;
                    const lPoint = lScore ? pointTypeMap.get(lScore.id) : null;
                    const rPoint = !localChoice ? pointTypeMap.get(tmpScores.keys().next().value || '') : null;
                    const tmpPoint = rPoint ? tmpScores.values().next().value || 0 : 0;
                    if (hasScore && !lPoint) continue;

                    const afterSelected = checkRequirements(aScore.requireds);
                    const tmpActivated = new SvelteMap<string, ActivatedMap>([...activatedMap].map(([key, value]) => [key, {...value}]));
                    if (localChoice) {
                        if (localChoice.isSelectableMultiple && localChoice.isMultipleUseVariable) {
                            if (localChoice.multipleUseVariable === 0) {
                                tmpActivated.delete(localChoice.id);
                                localRow.currentChoices += 1;
                            } else {
                                tmpActivated.set(localChoice.id, {multiple: localChoice.multipleUseVariable + 1});
                                if (localChoice.multipleUseVariable === 1) {
                                    localRow.currentChoices -= 1;
                                }
                            }
                        } else {
                            tmpActivated.delete(localChoice.id);
                            localRow.currentChoices -= 1;
                        }
                        if (lPoint) lPoint.startingSum += tmpScore;
                    } else if (rPoint) {
                        rPoint.startingSum -= tmpPoint;
                    }
                    const beforeSelected = checkRequirements(aScore.requireds, tmpActivated);
                    if (localChoice) {
                        if (localChoice.isSelectableMultiple && localChoice.isMultipleUseVariable) {
                            if (localChoice.multipleUseVariable === 0) {
                                localRow.currentChoices -= 1;
                            } else if (localChoice.multipleUseVariable === 1) {
                                localRow.currentChoices += 1;
                            }
                        } else {
                            localRow.currentChoices += 1;
                        }
                        if (lPoint) lPoint.startingSum -= tmpScore;
                    } else if (rPoint) {
                        rPoint.startingSum += tmpPoint;
                    }
                    if (beforeSelected === afterSelected) continue;

                    if (!aScore.setValue) setScoreValue(point, aScore, aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable, aChoice.multipleUseVariable - 1);
                    let scoreVal = aScore.discountIsOn && typeof aScore.discountScore !== 'undefined' && aScore.appliedDiscount ? aScore.discountScore : aScore.value;
                    scoreVal = point.allowFloat ? scoreVal : Math.floor(scoreVal);
                    if (beforeSelected) {
                        if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                            const mul = aChoice.multipleUseVariable;

                            for (let l = mul - 1; l >= 0; l--) {
                                if (typeof aScore.isActiveMul !== 'undefined' && aScore.isActiveMul[l]) {
                                    const sValue = aScore.multiplyByTimes ? scoreVal * (l + 1) : scoreVal;
                                    if (point.belowZeroNotAllowed && point.startingSum + sValue < 0) {
                                        if (aChoice.forcedActivated) {
                                            aChoice.numMultipleTimesMinus--;
                                            await selectedOneLess(aChoice, aRow, newOptions);

                                            const tmpAct = tmpActivatedMap.get(aChoice.id);
                                            if (typeof tmpAct !== 'undefined') {
                                                tmpAct.multiple += 1;
                                            } else {
                                                tmpActivatedMap.set(aChoice.id, {multiple: 1, activatedFrom: aChoice.activatedFrom});
                                            }
                                        } else {
                                            await selectedOneLess(aChoice, aRow, newOptions);
                                        }
                                        break;
                                    } else {
                                        point.startingSum += sValue;
                                        thisTmpScores.set(aScore.id, sValue);
                                        aScore.isActiveMul[l] = false;
                                    }
                                }
                            }
                        } else if (!aChoice.isSelectableMultiple) {
                            if (aScore.isActive) {
                                if (point.belowZeroNotAllowed && point.startingSum + scoreVal < 0) {
                                    if (aChoice.forcedActivated) {
                                        delete aChoice.forcedActivated;
                                        tmpActivatedMap.set(aChoice.id, {multiple: aChoice.multipleUseVariable, activatedFrom: aChoice.activatedFrom});
                                    }
                                    deselectObject(aChoice, aRow, newOptions);
                                } else {
                                    point.startingSum += scoreVal;
                                    thisTmpScores.set(aScore.id, scoreVal);
                                    delete aScore.isActive;
                                }
                            }
                        }
                        if (aScore.setValue) delete aScore.setValue;
                        if (aScore.appliedDiscount && typeof aScore.discounts !== 'undefined') {
                            for (let k = 0; k < aScore.discounts.length; k++) {
                                const dc = aScore.discounts[k];

                                if (dc.state === ACTIVE && dc.count !== DISABLED) {
                                    const cMap = choiceMap.get(dc.id);

                                    if (typeof cMap !== 'undefined') {
                                        const dChoice = cMap.choice;

                                        if (!addSet.has(dChoice)) {
                                            removeSet.add(dChoice);
                                        }
                                    }
                                }
                            }
                        }
                    } else {
                        if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                            const mul = aChoice.multipleUseVariable;
                            if (typeof aScore.isActiveMul === 'undefined') aScore.isActiveMul = [];
                            for (let l = mul - 1; l >= 0; l--) {
                                if (!aScore.isActiveMul[l]) {
                                    const sValue = aScore.multiplyByTimes ? scoreVal * (l + 1) : scoreVal;
                                    if (point.belowZeroNotAllowed && point.startingSum + sValue < 0) {
                                        if (aChoice.forcedActivated) {
                                            aChoice.numMultipleTimesMinus--;
                                            await selectedOneLess(aChoice, aRow, newOptions);

                                            const tmpAct = tmpActivatedMap.get(aChoice.id);
                                            if (typeof tmpAct !== 'undefined') {
                                                tmpAct.multiple += 1;
                                            } else {
                                                tmpActivatedMap.set(aChoice.id, {multiple: 1, activatedFrom: aChoice.activatedFrom});
                                            }
                                        } else {
                                            await selectedOneLess(aChoice, aRow, newOptions);
                                        }
                                        break;
                                    } else {
                                        point.startingSum -= sValue;
                                        thisTmpScores.set(aScore.id, sValue);
                                        aScore.isActiveMul[l] = true;
                                    }
                                }
                            }
                        } else if (!aChoice.isSelectableMultiple) {
                            if (!aScore.isActive) {
                                if (point.belowZeroNotAllowed && point.startingSum - scoreVal < 0) {
                                    if (aChoice.forcedActivated) {
                                        delete aChoice.forcedActivated;
                                        tmpActivatedMap.set(aChoice.id, {multiple: aChoice.multipleUseVariable, activatedFrom: aChoice.activatedFrom});
                                    }
                                    await deselectObject(aChoice, aRow, newOptions);
                                } else {
                                    point.startingSum -= scoreVal;
                                    thisTmpScores.set(aScore.id, scoreVal);
                                    aScore.isActive = true;
                                }
                            }
                        }
                        if (aScore.appliedDiscount && typeof aScore.discounts !== 'undefined') {
                            for (let k = 0; k < aScore.discounts.length; k++) {
                                const dc = aScore.discounts[k];

                                if (dc.state === ACTIVE && dc.count !== DISABLED) {
                                    const cMap = choiceMap.get(dc.id);

                                    if (typeof cMap !== 'undefined') {
                                        const dChoice = cMap.choice;

                                        addSet.add(dChoice);
                                    }
                                }
                            }
                        }
                    }
                    if (!isChanged) {
                        isChanged = true;
                    }
                    changedScores.add(aScore.idx);
                }
            }
            if (isChangedExp && !isChanged) {
                if (aChoice.isSelectableMultiple && aChoice.isMultipleUseVariable && typeof aChoice.numMultipleTimesMinus !== 'undefined') {
                    const mul = aChoice.multipleUseVariable;

                    for (let l = mul - 1; l >= 0; l--) {
                        if (typeof aScore.isActiveMul !== 'undefined' && aScore.isActiveMul[l]) {
                            const sValue = aScore.multiplyByTimes ? expVal * (l + 1) : expVal;
                            isChanged = true;
                            changedScores.add(aScore.idx);
                            if (point.belowZeroNotAllowed && point.startingSum + sValue < 0) {
                                if (aChoice.forcedActivated) {
                                    aChoice.numMultipleTimesMinus--;
                                    await selectedOneLess(aChoice, aRow, newOptions);

                                    const tmpAct = tmpActivatedMap.get(aChoice.id);
                                    if (typeof tmpAct !== 'undefined') {
                                        tmpAct.multiple += 1;
                                    } else {
                                        tmpActivatedMap.set(aChoice.id, {multiple: 1, activatedFrom: aChoice.activatedFrom});
                                    }
                                } else {
                                    await selectedOneLess(aChoice, aRow, newOptions);
                                }
                                break;
                            } else {
                                point.startingSum += sValue;
                                thisTmpScores.set(aScore.id, sValue);
                            }
                        }
                    }
                } else if (!aChoice.isSelectableMultiple) {
                    if (aScore.isActive) {
                        if (point.belowZeroNotAllowed && point.startingSum + expVal < 0) {
                            if (aChoice.forcedActivated) {
                                delete aChoice.forcedActivated;
                                tmpActivatedMap.set(aChoice.id, {multiple: aChoice.multipleUseVariable, activatedFrom: aChoice.activatedFrom});
                            }
                            await deselectObject(aChoice, aRow, newOptions);
                        } else {
                            point.startingSum += expVal;
                            thisTmpScores.set(aScore.id, expVal);
                        }
                        isChanged = true;
                        changedScores.add(aScore.idx);
                    }
                }
            }
        }
        if (removeSet.size > 0) {
            const arr = Array.from(removeSet);

            for (let i = 0; i < arr.length; i++) {
                const dChoice = arr[i];

                if (!addSet.has(dChoice)) await updateCount(aChoice, dChoice);
            }
        }
        if (addSet.size > 0) {
            const arr = Array.from(addSet);

            for (let i = 0; i < arr.length; i++) {
                const dChoice = arr[i];

                await addCount(aChoice, dChoice);
            }
        }
        if (isChanged) {
            scoreUpdate.length === 0 ? scoreUpdate.push(`Scores Updated On: ${aChoice.title}`) : scoreUpdate.push(`, ${aChoice.title}`);
            await selectUpdateScore(aChoice, aRow, thisTmpScores, count + 1, changedScores, scoreUpdate, options);
        }
    }
    if (count === 0) {
        if (scoreUpdate.length > 0 && !app.hideScoresUpdated) {
            const tempDiv = document.createElement('div');

            tempDiv.innerHTML = scoreUpdate.join('');
            snackbarVariables.labelText = tempDiv.textContent || '';
            snackbarVariables.isOpen = true;
        }
        scoreUpdate.splice(0);
    }
}

export async function activateTempChoices(options: ChoiceOptions) {
    if (isActivating) return;
    let isActivated = false;
    for (const [id, val] of tmpActivatedMap) {
        if (deselectQue.has(id)) continue;

        const cMap = choiceMap.get(id);
        if (typeof cMap === 'undefined') continue;

        const aRow = cMap.row;
        const aChoice = cMap.choice;
        const newOption = {...options};

        newOption.isForced = true;
        newOption.isAllowDeselect = val.isAllowDeselect;
        newOption.fromTemp = true;

        if (val.multiple === 0) {
            if (aChoice.isSelectDelayed || aChoice.isFadeTransition) {
                selectObject(aChoice, aRow, newOption);
            } else {
                await selectObject(aChoice, aRow, newOption);
            }
            if (aChoice.isActive) isActivated = true;
        } else {
            const num = aChoice.multipleUseVariable;
            for (let i = 0; i < val.multiple; i++) {
                if (aChoice.isSelectDelayed || aChoice.isFadeTransition) {
                    selectedOneMore(aChoice, aRow, newOption);
                }
                await selectedOneMore(aChoice, aRow, newOption);
            }
            if (aChoice.multipleUseVariable > num) isActivated = true;
        }
    }

    if (isActivated) await activateTempChoices(options);
}

function clearWordDialog() {
    wordDialog.currentDialog = 'none';
    wordDialog.context = '';
    wordDialog.cFunc = () => {};
    wordDialog.isDeselect = false;
    wordDialog.isForced = false;
    wordDialog.isWord = false;
    wordDialog.prevText = '';
    wordDialog.title = '';
}

function clearImgDialog() {
    imgDialog.currentDialog = 'none';
    delete imgDialog.data;
    imgDialog.imgProp = '';
    imgDialog.isDeselect = false;
    imgDialog.isForced = false;
}

function openWordDialog(localChoice: Choice | SelectableAddon, options: {isWord?: boolean, isDeselect?: boolean, isForced?: boolean}): Promise<{ status: 'accept'; wordText: string } | { status: 'cancel' } | { status: 'deselect' }> {
    return new Promise((resolve) => {
        let done = false;
        wordDialog.context = localChoice.wordPromptText || '';
        wordDialog.prevText = localChoice.wordChangeSelect || '';
        wordDialog.isWord = options.isWord;
        wordDialog.isDeselect = options.isDeselect;
        wordDialog.isForced = options.isForced;
        wordDialog.currentDialog = 'dlgCommon';
        wordDialog.cFunc = (e, wordText) => {
            if (done) return;
            done = true;
            clearWordDialog();
            if (e.detail.action === 'accept') {
                resolve({ status: 'accept', wordText: wordText || '' });
            } else if (e.detail.action === 'deselect') {
                resolve({ status: 'deselect' });
            } else {
                resolve({ status: 'cancel' });
            }
        };
    });
}

function openImgDialog(localChoice: Choice | SelectableAddon, options: {isDeselect?: boolean, isForced?: boolean}): Promise<{ status: 'accept'; wordText: string } | { status: 'cancel' } | { status: 'deselect' }> {
    return new Promise((resolve) => {
        let done = false;
        imgDialog.currentDialog = 'appImageUpload';
        imgDialog.data = localChoice;
        imgDialog.imgProp = 'image';
        imgDialog.isDeselect = options.isDeselect;
        imgDialog.isForced = options.isForced;
        imgDialog.cFunc = (e) => {
            if (done) return;
            done = true;
            clearImgDialog();
            if (e.detail.action === 'deselect') {
                resolve({ status: 'deselect' });
            } else {
                resolve({ status: 'cancel' });
            }
        }
    });
}

function delayProc(ms: number) {
    return new Promise(res => setTimeout(res, ms));
}

async function deselectDiscountOther(localChoice: Choice | SelectableAddon) {
    if (!localChoice.discountOther) return;
    if (typeof localChoice.discountOperator === 'undefined' || typeof localChoice.discountValue === 'undefined') return;

    if (localChoice.isDisChoices) {
        const dList = new Set<string>();
        if (typeof localChoice.discountRows !== 'undefined') {
            for (let i = 0; i < localChoice.discountRows.length; i++) {
                const dRow = rowMap.get(localChoice.discountRows[i]);
                if (typeof dRow !== 'undefined') {
                    for (let j = 0; j < dRow.objects.length; j++) {
                        const dChoice = dRow.objects[j];
                        await deselectDiscount(localChoice, dChoice);
                        dList.add(dChoice.id);
                    }
                }
            }
        }
        if (typeof localChoice.discountChoices !== 'undefined') {
            for (let i = 0; i < localChoice.discountChoices.length; i++) {
                if (!dList.has(localChoice.discountChoices[i])) {
                    const cMap = choiceMap.get(localChoice.discountChoices[i]);
                    if (typeof cMap !== 'undefined') {
                        await deselectDiscount(localChoice, cMap.choice);
                    }
                }
            }
        }
    } else {
        if (typeof localChoice.discountGroups !== 'undefined') {
            for (let i = 0; i < localChoice.discountGroups.length; i++) {
                const groupData = groupMap.get(localChoice.discountGroups[i]);
                if (typeof groupData !== 'undefined') {
                    for (let j = 0; j < groupData.elements.length; j++) {
                        const cMap = choiceMap.get(groupData.elements[j]);
                        if (typeof cMap !== 'undefined') {
                            await deselectDiscount(localChoice, cMap.choice);
                        }
                    }
                }
            }
        }
    }
}

function selectDiscountOther(localChoice: Choice | SelectableAddon) {
    if (!localChoice.discountOther) return;
    if (typeof localChoice.discountOperator === 'undefined' || typeof localChoice.discountValue === 'undefined') return;

    if (localChoice.isDisChoices) {
        const dList = new Set<string>();
        if (typeof localChoice.discountRows !== 'undefined') {
            for (let i = 0; i < localChoice.discountRows.length; i++) {
                const dRow = rowMap.get(localChoice.discountRows[i]);
                if (typeof dRow !== 'undefined') {
                    for (let j = 0; j < dRow.objects.length; j++) {
                        const dChoice = dRow.objects[j];
                        selectDiscount(localChoice, dChoice);
                        dList.add(dChoice.id);
                    }
                }
            }
        }
        if (typeof localChoice.discountChoices !== 'undefined') {
            for (let i = 0; i < localChoice.discountChoices.length; i++) {
                if (!dList.has(localChoice.discountChoices[i])) {
                    const cMap = choiceMap.get(localChoice.discountChoices[i]);
                    if (typeof cMap !== 'undefined') {
                        selectDiscount(localChoice, cMap.choice);
                    }
                }
            }
        }
    } else {
        if (typeof localChoice.discountGroups !== 'undefined') {
            for (let i = 0; i < localChoice.discountGroups.length; i++) {
                const groupData = groupMap.get(localChoice.discountGroups[i]);
                if (typeof groupData !== 'undefined') {
                    for (let j = 0; j < groupData.elements.length; j++) {
                        const cMap = choiceMap.get(groupData.elements[j]);
                        if (typeof cMap !== 'undefined') {
                            selectDiscount(localChoice, cMap.choice);
                        }
                    }
                }
            }
        }
    }
}

async function deselectCalculateScore(localChoice: Choice | SelectableAddon, tmpScores: SvelteMap<string, number>, options: {isMultiple: boolean, isPos: boolean, selNum: number}) {
    const countSet = new Set<Choice | SelectableAddon>();
    const key = options.isPos ? 'isActiveMul' : 'isActiveMulMinus';
    for (let i = 0; i < localChoice.scores.length; i++) {
        const score = localChoice.scores[i];
        let isActive = false;
        if (options.isMultiple) {
            if (typeof score[key] === 'undefined') score[key] = [];
            isActive = options.isPos ? !!score[key][options.selNum] : !score[key][options.selNum];
        } else {
            isActive = !!score.isActive;
        }
        if (isActive) {
            const point = pointTypeMap.get(score.id);
            if (typeof point !== 'undefined') {
                let val = score.value;
                if (typeof score.discountScore !== 'undefined' && typeof score.discounts !== 'undefined') {
                    if (score.appliedDiscount) val = score.discountScore;
                    for (let j = 0; j < score.discounts.length; j++) {
                        const dc = score.discounts[j];

                        if (dc.state === ACTIVE || (dc.state === FULL && localChoice.isSelectableMultiple)) {
                            const cMap = choiceMap.get(dc.id);

                            if (typeof cMap !== 'undefined') {
                                const dChoice = cMap.choice;

                                if (dChoice.useDiscountCount && typeof dChoice.discountCount !== 'undefined' && typeof dChoice.appliedDisChoices !== 'undefined' && deselectQue.has(dChoice.id)) {
                                    const inCount = localChoice.isSelectableMultiple && dChoice.countPerSelection && options.selNum + 1 >= dChoice.appliedDisChoices.filter(id => id === localChoice.id).length;

                                    if (inCount) {
                                        score.appliedDiscount = true;
                                        val = score.discountScore;
                                    }

                                    if (!options.isMultiple || options.selNum === 0 || inCount) countSet.add(dChoice);
                                }
                            }
                        }
                    }
                } else if (options.isMultiple && score.useExpression && score.mulValue && score.mulValue[options.selNum + 1]) {
                    val = score.mulValue[options.selNum];
                }
                val = point.allowFloat ? val : Math.floor(val);
                if (options.isMultiple && score.multiplyByTimes) {
                    val = val * (options.selNum + 1);
                }
                point.startingSum += val;
                let tmpScore = tmpScores.get(score.id);
                if (typeof tmpScore !== 'undefined') {
                    tmpScores.set(score.id, -val + tmpScore);
                } else {
                    tmpScores.set(score.id, -val);
                }
                if (options.isMultiple) {
                    if (options.isPos) {
                        if (score[key]) score[key].splice(options.selNum, 1);
                        if (score.mulValue) score.mulValue.splice(options.selNum, 1);
                        if (options.selNum === 0) delete score.setValue;
                    } else if (score[key]) {
                        score[key][options.selNum] = true;
                    }
                } else {
                    delete score.isActive;
                    delete score.setValue;
                }
            }
        } else {
            delete score.setValue;
        }

        delete score.isChangeDiscount;
        delete score.tmpDisScore;
    }

    if (countSet.size > 0) {
        const arr = Array.from(countSet);

        for (let i = 0; i < arr.length; i++) {
            const dChoice = arr[i];

            await removeCount(localChoice, dChoice);
        }
    }
}

async function selectCalculateScore(localChoice: Choice | SelectableAddon, tmpScores: SvelteMap<string, number>, options: {isMultiple: boolean, isPos: boolean, selNum: number}) {
    const countSet = new Set<Choice | SelectableAddon>();
    const key = options.isPos ? 'isActiveMul' : 'isActiveMulMinus';
    for (let i = 0; i < localChoice.scores.length; i++) {
        const score = localChoice.scores[i];
        let isInactive = false;
        if (options.isMultiple) {
            if (typeof score[key] === 'undefined') score[key] = [];
            isInactive = !score[key][options.selNum];
        } else {
            isInactive = !score.isActive;
        }

        if (checkRequirements(score.requireds) && isInactive) {
            const point = pointTypeMap.get(score.id);
            if (typeof point !== 'undefined') {
                let val = score.value;
                if (score.useExpression && score.setValue) {
                    expDiscount(point, score);
                }

                if (score.discountIsOn && score.appliedDiscount && typeof score.discountScore !== 'undefined' && typeof score.discounts !== 'undefined') {
                    val = score.discountScore;
                    for (let j = 0; j < score.discounts.length; j++) {
                        const dc = score.discounts[j];

                        if (dc.state === ACTIVE) {
                            const cMap = choiceMap.get(dc.id);

                            if (typeof cMap !== 'undefined') {
                                const dChoice = cMap.choice;

                                if (dChoice.useDiscountCount && typeof dChoice.discountCount !== 'undefined') {
                                    countSet.add(dChoice);
                                }
                            }
                        }
                    }
                }
                val = point.allowFloat ? val : Math.floor(val);
                if (options.isMultiple && score[key]) {
                    if (score.multiplyByTimes) {
                        val = val * (options.selNum + 1);
                    }
                    if (options.isPos) {
                        score[key][options.selNum] = true;
                    } else {
                        score[key].splice(options.selNum, 1);
                    }
                } else {
                    score.isActive = true;
                }
                point.startingSum -= val;
                const tmpScore = tmpScores.get(score.id);
                if (typeof tmpScore !== 'undefined') {
                    tmpScores.set(score.id, val + tmpScore);
                } else {
                    tmpScores.set(score.id, val);
                }
            }
        }
    }

    if (countSet.size > 0) {
        const arr = Array.from(countSet);

        for (let i = 0; i < arr.length; i++) {
            const dChoice = arr[i];

            await addCount(localChoice, dChoice);
        }
    }
}

async function deselectActivateOther(localChoice: Choice | SelectableAddon, options: ChoiceOptions) {
    if (!localChoice.activateOtherChoice || typeof localChoice.activateThisChoice === 'undefined') return;
    const isAct = isActivating;
    if (!isAct) isActivating = true;
    const selNum = Math.abs(localChoice.multipleUseVariable - 1);
    const forceAct = new Map<string, {choice: Choice | SelectableAddon, row: Row, num: number}>();
    if (localChoice.isActivateRandom) {
        if (typeof localChoice.activatedRandomMul !== 'undefined' && typeof localChoice.activatedRandomMul[selNum] !== 'undefined') {
            for (let i = 0; i < localChoice.activatedRandomMul[selNum].length; i++) {
                const cID = localChoice.activatedRandomMul[selNum][i].split('/ON#');
                const cMap = choiceMap.get(cID[0]);
                if (typeof cMap !== 'undefined') {
                    const fRow = cMap.row;
                    const fChoice = cMap.choice;
                    const forceNum = cID.length > 1 ? Number(cID[1]) : 0;
                    if (fChoice.isActive) {
                        forceAct.set(fChoice.id, {choice: fChoice, row: fRow, num: forceNum});
                    } else {
                        await deselectTempActivate(localChoice, fChoice, forceNum);
                    }
                }
            }
            localChoice.activatedRandomMul.splice(selNum, 1);
        } else if (typeof localChoice.activatedRandom !== 'undefined') {
            for (let i = 0; i < localChoice.activatedRandom.length; i++) {
                const cMap = choiceMap.get(localChoice.activatedRandom[i]);
                if (typeof cMap !== 'undefined') {
                    const fRow = cMap.row;
                    const fChoice = cMap.choice;
                    if (fChoice.isActive) {
                        forceAct.set(fChoice.id, {choice: fChoice, row: fRow, num: 0});
                    } else {
                        await deselectTempActivate(localChoice, fChoice, 0);
                    }
                }
            }
            delete localChoice.activatedRandom;
        }
    } else {
        const list = localChoice.activateThisChoice.split(',');
        for (let i = 0; i < list.length; i++) {
            const item = list[i].split('/ON#');
            const forceNum = item.length > 1 ? parseInt(item[1]) : 0;
            const cMap = choiceMap.get(item[0]);
            if (typeof cMap !== 'undefined') {
                const fRow = cMap.row;
                const fChoice = cMap.choice;
                if (fChoice.isActive) {
                    forceAct.set(fChoice.id, {choice: fChoice, row: fRow, num: forceNum});
                } else {
                    await deselectTempActivate(localChoice, fChoice, forceNum);
                }
            } else {
                const groupData = groupMap.get(item[0]);
                if (typeof groupData !== 'undefined') {
                    const groupEle = groupData.elements;
                    for (let j = 0; j < groupEle.length; j++) {
                        const cMap = choiceMap.get(groupEle[j]);
                        if (typeof cMap !== 'undefined') {
                            const fRow = cMap.row;
                            const fChoice = cMap.choice;
                            if (fChoice.isActive) {
                                forceAct.set(fChoice.id, {choice: fChoice, row: fRow, num: forceNum});
                            } else {
                                await deselectTempActivate(localChoice, fChoice, forceNum);
                            }
                        }
                    }
                }
            }
        }
    }

    for (const [_, val] of forceAct) {
        if (val.choice.isDeselectDelayed || val.choice.isFadeTransition) {
            deselectForceActivate(localChoice, val.choice, val.row, val.num, options);
        } else {
            await deselectForceActivate(localChoice, val.choice, val.row, val.num, options);
        }
    }
    if (!isAct) isActivating = false;
}

