function getSelectedObjectName() {
        let titles: string[] = [];
        let idArray = Array.from(activatedMap.keys());
        let titleText: string = '';

        idArray.sort((a, b) => {
            let aMap = choiceMap.get(a);
            let bMap = choiceMap.get(b);

            if (typeof aMap !== 'undefined' && typeof bMap !== 'undefined') {
                if (aMap.row.index !== bMap.row.index) return aMap.row.index - bMap.row.index;
                return aMap.choice.index - bMap.choice.index;
            }

            return 0;
        });

        if (seperateChoices) {
            let prevRowId = '';

            for (let i = 0; i < idArray.length; i++) {
                let cMap = choiceMap.get(idArray[i]);

                if (typeof cMap !== 'undefined') {
                    const row = cMap.row;
                    const choice = cMap.choice;

                    if (choice.title !== '') {
                        if (row.id !== prevRowId) {
                            if (prevRowId !== '') titles.push('\n');
                            titles.push(`**${row.title !== '' ? row.title : row.debugTitle || ''}**\n`);
                            if (choice.isSelectableMultiple) {
                                titles.push(`${choice.title}(x${choice.multipleUseVariable})`);
                            } else {
                                titles.push(`${choice.title}`);
                            }
                            prevRowId = row.id;
                        } else {
                            if (choice.isSelectableMultiple) {
                                titles.push(`, ${choice.title}(x${choice.multipleUseVariable})`);
                            } else {
                                titles.push(`, ${choice.title}`);
                            }
                        }
                    }
                }
            }
            titleText = titles.join('');
        } else {
            for (let i = 0; i < idArray.length; i++) {
                let cMap = choiceMap.get(idArray[i]);

                if (typeof cMap !== 'undefined') {
                    const choice = cMap.choice;

                    if (choice.title !== '') {
                        if (choice.isSelectableMultiple) {
                            titles.push(`${choice.title}(x${choice.multipleUseVariable})`);
                        } else {
                            titles.push(`${choice.title}`);
                        }
                    }
                }
            }
            titleText = titles.join(', ');
        }
        const tempDiv = document.createElement('div');
        tempDiv.innerHTML = titleText;

        return tempDiv.textContent;
    }

