    font-size: 1rem;
    font-size: var(--mdc-typography-subtitle1-font-size, 1rem);
    font-weight: 400;
    font-weight: var(--mdc-typography-subtitle1-font-weight, 400);
    letter-spacing: 0.009375em;
    letter-spacing: var(--mdc-typography-subtitle1-letter-spacing, 0.009375em);
    text-decoration: inherit;
    text-decoration: var(--mdc-typography-subtitle1-text-decoration, inherit);
    text-transform: inherit;
    text-transform: var(--mdc-typography-subtitle1-text-transform, inherit);
    outline: none;
    min-height: 38px;
    padding: 8px 16px 2px;
    transition: background-color 0.15s ease, border-color 0.15s ease, border-width 0.15s ease;
}
.rich-button {
    width: 30px;
    font-size: 20px;
    color: inherit;
}
.tiptap-submenu {
    position: absolute;
    z-index: 1;
    box-shadow: 0 3px 5px -1px rgba(0,0,0,0.2),0 6px 10px 0 rgba(0,0,0,0.14),0 1px 18px 0 rgba(0,0,0,0.12);
}
.tiptap-active {
    color: rgb(0, 152, 247);
}
.tiptap-wrapper {
    resize: vertical;
    overflow-y: auto;
}
.ProseMirror {
    height: 100%;
    overflow-wrap: break-word;
    outline: none;
}
.font-size {
    overflow-y: auto;
    width: 80px;
    height: 256px;
}
.line-height {
    overflow-y: auto;
    width: 100px;
    height: 256px;
}
.link-menu {
    width: 300px;
}
.align-menu {
    width: 120px;
}
.tiptap-active {
    border-radius: 4px;
}
.picture-input {
    width: 100%;
    margin: 0 auto;
    text-align: center;
}
.preview-container {
    width: 100%;
    box-sizing: border-box;
    margin: 0 auto;
    cursor: pointer;
    overflow: hidden;
    transform: translate3d(0, 0, 0);
}
.picture-preview {
    width: 100%;
    height: 100%;
    position: relative;
    z-index: 10001;
    box-sizing: border-box;
    background-color: rgba(200,200,200,0.25);
}
.picture-preview.dragging-over {
    filter: brightness(0.5);
}
.picture-inner {
    position: relative;
    z-index: 10002;
    pointer-events: none;
    box-sizing: border-box;
    margin: 1em auto;
    padding: 0.5em;
    border: 0.3em dashed rgba(66,66,66,0.15);
    border-radius: 8px;
    width: calc(100% - 2.5em);
    height: calc(100% - 2.5em);
    display: table;
}
.picture-inner .picture-inner-text {
    display: table-cell;
    vertical-align: middle;
    text-align: center;
    font-size: 2em;
    line-height: 1.5;
}
.picture-input input[type="file"] {
    display: none;
}
.text-prewrap {
    white-space: pre-wrap;
}
.category-slot {
    border: 2px solid #838386;
    border-radius: 4px;
    cursor: pointer;
    height: 100px;
}
.category-slot:hover {
    border-color: green;
}
.category-text {
    text-align: center;
    font-size: 2rem;
    max-width: 100%;
    height: 50px;
    line-height: 50px;
}
.category-text span {
    max-width: 100%;
    white-space: nowrap;
    overflow-x: hidden;
    text-overflow: ellipsis;
    display: inline-block;
}
.ind1 {
	padding-top: 5px;
	font-size: 18px;
}
.ind2 {
	padding-top: 5px;
	font-size: 18px;
}
.ind3 {
	font-size: 16px;
	line-height: 25px;
}
.indicator {
	position: absolute;
	top: 50%;
	left: 50%;
	padding-left: 2px;
	transform: translate(-50%,-50%);
	width: 150px;
	height: 150px;
	background: transparent;
	border: 3px solid var(--track);
	border-radius: 50%;
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	text-align: center;
	font-family: var(--font);
	color: var(--color);
	letter-spacing: 3px;
	text-transform: uppercase;
	text-shadow: 0 0 10px var(--shadow);
	box-shadow: 0 0 20px rgba(0,0,0,.5);
}
.indicator:before {
	content: "";
	position: absolute;
	top: -3px;
	left: -3px;
	width: 104%;
	height: 104%;
	border: 3px solid transparent;
	border-top: 3px solid var(--circle);
	border-right: 3px solid var(--circle);
	border-radius: 50%;
	animation: animateC 2s linear infinite;
}
.indicator > div {
	max-width:120px;
}
#dnd-action-dragged-el {
    opacity: 0.5 !important;
    font-size: 1rem !important;
    align-items: middle !important;
    background: none !important;
}
#dnd-action-dragged-el .smui-accordion__header__icon {
    display: none;
}
#dnd-action-dragged-el .smui-paper__content {
    display: none;
}
#dnd-action-dragged-el .smui-accordion__header__title {
    background: none;
}
@keyframes scrollText {
    0% {
        transform: translateX(150px)
    }
    100% {
        transform: translateX(-100%)
    }
}
@keyframes animateC {
	0% {
		transform:rotate(0deg);
	}
	100% {
		transform:rotate(360deg);
	}
}

{#if bCreatorMode && (row.isEditModeOn || choice.isEditModeOn) && !row.isResultRow && !row.isGroupRow}
    <div class={objectWidthClass()}>
