            return;
        const bg = mix(a11yColor.bgHex);
        const ft = mix(hex, bg);
        if (!ft)
            return;
        const cft = colord(ft);
        return {
            ...a11yColor,
            trueColors: {
                textColor: hex,
                bgColor: a11yColor.bgHex
            },
            contrast: cft.contrast(bg)
        };
    }
}

export const defaultTexts = {
    label: {
        h: 'hue channel',
        s: 'saturation channel',
        v: 'brightness channel',
        r: 'red channel',
        g: 'green channel',
        b: 'blue channel',
        a: 'alpha channel',
        hex: 'hex color',
        withoutColor: 'without color'
    },
    color: {
        rgb: 'rgb',
        hsv: 'hsv',
        hex: 'hex'
    },
    changeTo: 'change to '
};
export const defaultA11yTexts = {
    contrast: 'contrast :',
    nbGradeSummary: (count) => count ? `⚠️ ${count} contrast grade${count && 's'} fail` : 'Contrast grade information',
    guidelines: `Learn more at <a href="https://webaim.org/articles/contrast/" target="_blank">WebAIM contrast guide</a>`
};

// list taken from https://github.com/nico3333fr/van11y-accessible-modal-tooltip-aria/blob/1a83366c65358222483be849fbb768c31cefaf4d/src/van11y-accessible-modal-tooltip-aria.es6.js#L47
export const FOCUSABLE_ELEMENTS = "a[href], area[href], input:not([type='hidden']):not([disabled]), select:not([disabled]), textarea:not([disabled]), button:not([disabled]), iframe, object, embed, *[tabindex], *[contenteditable]";
// code adapted from https://gist.github.com/JulienPradet/20dbb7ca06cbd9e2ec499bb2206aab55#file-trapfocus-ts-L1-L44
function trapFocusListener(trapFocusElement) {
    return function (event) {
        if (event.target === window) {
            return;
        }
        const eventTarget = event.target;
        if (!trapFocusElement.contains(eventTarget)) {
            return;
        }
        const focusable = trapFocusElement.querySelectorAll(FOCUSABLE_ELEMENTS);
        const first = focusable[0];
        const last = focusable[focusable.length - 1];
        function isNext(event) {
            return event.code === 'Tab' && !event.shiftKey;
        }
        function isPrevious(event) {
            return event.code === 'Tab' && event.shiftKey;
        }
        if (isNext(event) && event.target === last) {
            event.preventDefault();
            first.focus();
        }
        else if (isPrevious(event) && event.target === first) {
            event.preventDefault();
            last.focus();
        }
    };
}
export const trapFocus = (node) => {
    const first = node.querySelector(FOCUSABLE_ELEMENTS);
    if (first)
        first.focus();
    const listener = trapFocusListener(node);
    document.addEventListener('keydown', listener);
    return {
        destroy() {
            document.removeEventListener('keydown', listener);
        }
    };
};

