        }
        styles.push(`border-radius: ${objectImageStyle.objectImgBorderRadiusTopLeft}${suffix} ${objectImageStyle.objectImgBorderRadiusTopRight}${suffix} ${objectImageStyle.objectImgBorderRadiusBottomRight}${suffix} ${objectImageStyle.objectImgBorderRadiusBottomLeft}${suffix};`);
        if (objectImageStyle.objectImgOverflowIsOn) {
            styles.push(`overflow: hidden;`);
        }
        if (objectImageStyle.objectImgBorderIsOn) {
            const borderColor = isEnabled ? (isActive && filterStyle.selImgBorderColorIsOn && filterStyle.selFilterImgBorderColor) || objectImageStyle.objectImgBorderColor : (filterStyle.reqImgBorderColorIsOn && filterStyle.reqFilterImgBorderColor) || objectImageStyle.objectImgBorderColor;
            styles.push(`border: ${objectImageStyle.objectImgBorderWidth}px ${objectImageStyle.objectImgBorderStyle} ${hexToRgba(borderColor)};`);
        }

        return styles.join(' ');
    });

    let scoreText = $derived.by(() => {
        const style: string[] = [];

        style.push(`font-family: '${textStyle.scoreText}'; font-size: ${textStyle.scoreTextSize}%; text-align: ${textStyle.scoreTextAlign};`);
        if (!isEnabled && filterStyle.reqScoreTextColorIsOn) {
            style.push(`color: ${hexToRgba(filterStyle.reqFilterSTextColor)};`);
        } else if (choice.isActive && filterStyle.selScoreTextColorIsOn) {
            style.push(`color: ${hexToRgba(filterStyle.selFilterSTextColor)};`);
        } else {
            style.push(`color: ${hexToRgba(textStyle.scoreTextColor)};`);
        }

        return style.join(' ');
    });

    $effect(() => {
        if (mainDiv) options.mainDiv = mainDiv;
        if (isBackpack) options.isBackpack = isBackpack;
    });

    function setFilters(bgStyles: BgStyles, filters: Filters) {
        if (isEnabled) {
            if (isActive) {
                if (filterStyle.selFilterBlurIsOn) {
                    filters.blur = ` blur(${filterStyle.selFilterBlur}px)`;
                }
                if (filterStyle.selFilterBrightIsOn) {
                    filters.brightness = ` brightness(${filterStyle.selFilterBright}%)`;
                }
                if (filterStyle.selFilterContIsOn) {
                    filters.contrast = ` contrast(${filterStyle.selFilterCont}%)`;
                }
                if (filterStyle.selFilterGrayIsOn) {
                    filters.grayscale = ` grayscale(${filterStyle.selFilterGray}%)`;
                }
                if (filterStyle.selFilterHueIsOn) {
                    filters.hueRotate = ` hue-rotate(${filterStyle.selFilterHue}deg)`;
                }
                if (filterStyle.selFilterInvertIsOn) {
                    filters.invert = ` invert(${filterStyle.selFilterInvert}%)`;
                }
                if (filterStyle.selFilterOpacIsOn) {
                    filters.opacity = ` opacity(${filterStyle.selFilterOpac}%)`;
                }
                if (filterStyle.selFilterSaturIsOn) {
                    filters.saturate = ` saturate(${filterStyle.selFilterSatur})`;
                }
                if (filterStyle.selFilterSepiaIsOn) {
                    filters.sepia = ` sepia(${filterStyle.selFilterGray}%)`;
                }
                if (filterStyle.selBgColorIsOn) {
                    bgStyles.bgColor = `background-color: ${hexToRgba(filterStyle.selFilterBgColor)};`;
                    if (!filterStyle.selOverlayOnImage) bgStyles.bgImage = '';
                }
                if (objectStyle.objectGradientIsOn && objectStyle.objectGradientOnSelect) {
                    const gradient = objectStyle.objectGradientOnSelect.split(');')[0];
                    bgStyles.bgImage = `background-image: linear-gradient(${gradient});`;
                }
            } else {
                if (filterStyle.unselFilterBlurIsOn) {
                    filters.blur = ` blur(${filterStyle.unselFilterBlur}px)`;
                }
                if (filterStyle.unselFilterBrightIsOn) {
                    filters.brightness = ` brightness(${filterStyle.unselFilterBright}%)`;
                }
                if (filterStyle.unselFilterContIsOn) {
                    filters.contrast = ` contrast(${filterStyle.unselFilterCont}%)`;
                }
                if (filterStyle.unselFilterGrayIsOn) {
                    filters.grayscale = ` grayscale(${filterStyle.unselFilterGray}%)`;
                }
                if (filterStyle.unselFilterHueIsOn) {
                    filters.hueRotate = ` hue-rotate(${filterStyle.unselFilterHue}deg)`;
                }
                if (filterStyle.unselFilterInvertIsOn) {
                    filters.invert = ` invert(${filterStyle.unselFilterInvert}%)`;
                }
                if (filterStyle.unselFilterOpacIsOn) {
                    filters.opacity = ` opacity(${filterStyle.unselFilterOpac}%)`;
                }
                if (filterStyle.unselFilterSaturIsOn) {
                    filters.saturate = ` saturate(${filterStyle.unselFilterSatur})`;
                }
                if (filterStyle.unselFilterSepiaIsOn) {
                    filters.sepia = ` sepia(${filterStyle.unselFilterGray}%)`;
                }
                if (objectStyle.objectGradientIsOn && objectStyle.objectGradient) {
                    const gradient = objectStyle.objectGradient.split(');')[0];
                    bgStyles.bgImage = `background-image: linear-gradient(${gradient});`;
                }
            }
            if (app.isPointerCursor && !choice.isNotSelectable && (!choice.isSelectableMultiple || (choice.allowSelectByClick && choice.multipleUseVariable === 0))) {
                bgStyles.cursor = `cursor: pointer;`;
            }
        } else {
            if (filterStyle.reqFilterBlurIsOn) {
                filters.blur = ` blur(${filterStyle.reqFilterBlur}px)`;
            }
            if (filterStyle.reqFilterBrightIsOn) {
                filters.brightness = ` brightness(${filterStyle.reqFilterBright}%)`;
            }
            if (filterStyle.reqFilterContIsOn) {
                filters.contrast = ` contrast(${filterStyle.reqFilterCont}%)`;
            }
            if (filterStyle.reqFilterGrayIsOn) {
                filters.grayscale = ` grayscale(${filterStyle.reqFilterGray}%)`;
            }
            if (filterStyle.reqFilterHueIsOn) {
                filters.hueRotate = ` hue-rotate(${filterStyle.reqFilterHue}deg)`;
            }
            if (filterStyle.reqFilterInvertIsOn) {
                filters.invert = ` invert(${filterStyle.reqFilterInvert}%)`;
            }
            if (filterStyle.reqFilterOpacIsOn) {
                filters.opacity = ` opacity(${filterStyle.reqFilterOpac}%)`;
            }
            if (filterStyle.reqFilterSaturIsOn) {
                filters.saturate = ` saturate(${filterStyle.reqFilterSatur})`;
            }
            if (filterStyle.reqFilterSepiaIsOn) {
                filters.sepia = ` sepia(${filterStyle.reqFilterGray}%)`;
            }
            if (filterStyle.reqBgColorIsOn) {
                bgStyles.bgColor = `background-color: ${hexToRgba(filterStyle.reqFilterBgColor)};`;
                if (!filterStyle.reqOverlayOnImage) bgStyles.bgImage = '';
            }
            if (objectStyle.objectGradientIsOn && objectStyle.objectGradientOnReq) {
                const gradient = objectStyle.objectGradientOnReq.split(');')[0];
                bgStyles.bgImage = `background-image: linear-gradient(${gradient});`;
            }
        }
    }

    function objectWidthClass() {
        if (isSearch) return 'col-sm-6 col-12';
        const objectWidth = row.overrideWidth ? row.objectWidth : (choice.objectWidth || row.objectWidth);
        const objectWidthNum = objectWidthToNum(objectWidth);
        const objectsPerRowNum = app.objectsPerRow === 'col-6' ? 2 : app.objectsPerRow === 'col-4' ? 3 : 4;
        if ($winWidth > 1280) {
            return objectWidth;
        } else if ($winWidth > app.smallerScreenPx) {
            if (app.objectsPerRow === 'default') return fixedWidth(objectWidth);
            switch(objectWidthNum) {
                case 1: return 'col-12';
                case 2: return 'col-6';
                case 3: return objectsPerRowNum > 2 ? 'col-4' : app.objectsPerRow;
                case 4: return objectsPerRowNum > 3 ? 'col-3' : app.objectsPerRow;
                default: return app.objectsPerRow;
            }
        } else if ($winWidth > 480) {
            return objectWidthNum === 1 ? 'col-12' : 'col-6';
        } else {
            return 'col-12';
        }
    }

    async function handleCounter(isSel: boolean) {
        if (row.isInfoRow) return;

        let origRow = row;

        options.isOverDlg = false;
        options.isOverImg = false;
        options.linkedObjects = [];

        if (row.isResultRow || row.isGroupRow) {
            const cMap = choiceMap.get(choice.id);

            if (typeof cMap !== 'undefined') {
                origRow = cMap.row;
            }
        }

        if (isSel) {
            if (!choice.isNotSelectable) await selectedOneMore(choice, origRow, options);
        } else {
            if (!choice.selectOnce) await selectedOneLess(choice, origRow, options);
        }
    }

    function activateObject(e?: MouseEvent) {
        if (row.isInfoRow) return;

        const target = e && e.target ? e.target as HTMLElement : null
        let origRow = row;

        options.isOverDlg = false;
        options.isOverImg = false;
        options.linkedObjects = [];
        if (target && choice.addons && choice.addons.length > 0) {
            if (closestByClassPrefix(target, 'addon-', 'addon')) return;
        }

        if (row.isResultRow || row.isGroupRow) {
            const cMap = choiceMap.get(choice.id);

            if (typeof cMap !== 'undefined') {
                origRow = cMap.row;
            }
        }

        if (choice.isSelectableMultiple) {
            if (choice.allowSelectByClick && choice.multipleUseVariable === 0) {
                if (target) {
                    if (closestByClassPrefix(target, 'multi-', 'choice-')) return;
                }
                selectedOneMore(choice, origRow, options);
            }
        } else {
            if (choice.isActive) {
                if (!choice.selectOnce && !choice.forcedActivated) deselectObject(choice, origRow, options);
            } else if (!choice.isNotSelectable) {
                selectObject(choice, origRow, options);
            }
        }
    }

    function copyTooltip(e: Event) {
        navigator.clipboard.writeText(choice.imageSourceTooltip).then(() => {
            snackbarVariables.labelText = 'Tooltip copied to clipboard.';
            snackbarVariables.isOpen = true;
        }).catch(() => {
            console.log(choice.imageSourceTooltip);
            snackbarVariables.labelText = 'Tooltip text logged to developer console.';
            snackbarVariables.isOpen = true;
        });
    }
</script>

{#if !data.hideCounterUntilSelect || data.multipleUseVariable !== 0}
    <div class="d-row justify-space-around w-100 multi-counter">
        {#if !data.hideCounter}
            <IconButton class="counter-icons" disabled={!minusEnabled} onclickcapture={clickCounterMinus}>
                <i class="mdi mdi-minus" style={multiChoiceButton}></i>
            </IconButton>
        {/if}
        <div translate="no" style={multiChoiceText} onclickcapture={clickNumber}>
            {multipleNum}
        </div>
        {#if !data.hideCounter}
            <IconButton class="counter-icons" disabled={!plusEnabled} onclickcapture={clickCounterPlus}>
                <i class="mdi mdi-plus" style={multiChoiceButton}></i>
            </IconButton>
        {/if}
    </div>
    {#if data.useSlider}
        <div class="px-5 w-100 multi-slider">
            <Slider bind:value={sliderNum} min={data.numMultipleTimesMinus} max={data.numMultipleTimesPluss} step={1} class="mx-2" onpointerup={handleSliderUp} disabled={!plusEnabled && !minusEnabled} discrete />
        </div>
    {/if}
{/if}

<script lang="ts">
    import IconButton from '@smui/icon-button';
    import type { Row, Choice, SelectableAddon } from '$lib/store/types';
    import { pointTypeMap, dlgVariables, getStyling, hexToRgba } from '$lib/store/store.svelte';
    import Slider from '@smui/slider';

    const { isEnabled, row, choice, addon, selectedOneMore, selectedOneLess }: { isEnabled: boolean, row: Row, choice: Choice, addon?: SelectableAddon, selectedOneMore: () => Promise<void>, selectedOneLess: () => Promise<void> } = $props();

    let sliderNum = $state(0);
    let data = $derived(addon ? addon : choice);
    let multipleNum = $derived.by(() => {
        if (data.isMultipleUseVariable) {
            return data.multipleUseVariable;
        } else {
            if (typeof data.multipleScoreId !== 'undefined') {
                let point = pointTypeMap.get(data.multipleScoreId);
                if (typeof point !== 'undefined') {
                    return point.startingSum;
                }
            }
            return 0;
        }
    });
    let enabled = $derived(isEnabled && !row.isInfoRow);
    let plusEnabled = $derived(enabled && !data.isNotSelectable);
    let minusEnabled = $derived(enabled && !data.selectOnce);
    let textStyle = $derived(getStyling('privateTextIsOn', row, choice));
    let filterStyle = $derived(getStyling('privateFilterIsOn', row, choice));
    let multiChoiceStyle = $derived(getStyling('privateMultiChoiceIsOn', row, choice));
    let multiChoiceText = $derived.by(() => {
        const style: string[] = [];
        let color = hexToRgba(textStyle.scoreTextColor);

        style.push(`font-family: '${multiChoiceStyle.multiChoiceTextFont}'; font-size: ${multiChoiceStyle.multiChoiceTextSize}%; align-content: center;`);

        if (!isEnabled) {
            if (filterStyle.reqScoreTextColorIsOn)  {
                color = hexToRgba(filterStyle.reqFilterSTextColor);
            }
        } else if (data.isActive) {
            if (filterStyle.selScoreTextColorIsOn) {
                color = hexToRgba(filterStyle.selFilterSTextColor);
            }
        }

        style.push(`color: ${color}`);

        return style.join(' ');
    });
    let multiChoiceButton = $derived.by(() => {
        let color = hexToRgba(textStyle.scoreTextColor);

        if (!isEnabled) {
            if (filterStyle.reqScoreTextColorIsOn)  {
                color = hexToRgba(filterStyle.reqFilterSTextColor);
            }
        } else if (data.isActive) {
            if (filterStyle.selScoreTextColorIsOn) {
                color = hexToRgba(filterStyle.selFilterSTextColor);
            }
        }

        return `font-size: ${multiChoiceStyle.multiChoiceCounterSize}%; color: ${color};`;
    });

    $effect(() => {
        if (data.useSlider) {
            sliderNum = multipleNum;
        }
    });

    function clickCounterPlus(e: Event) {
        selectedOneMore();
    }

    function clickCounterMinus(e: Event) {
        selectedOneLess();
    }

    async function handleSliderUp() {
        const loop = sliderNum - multipleNum;
        for (let i = 0; i < Math.abs(loop); i++) {
            if (loop > 0) {
                await selectedOneMore();
            } else {
                await selectedOneLess();
            }
        }
        if (document.activeElement) {
            (document.activeElement as HTMLElement).blur();
        }
    }

    function clickNumber(e: Event) {
        if (enabled) {
            dlgVariables.currentDialog = 'selectDialog';
            dlgVariables.choice = data;
            dlgVariables.func = handleManually;
        }
    }

    async function handleManually(num: number) {
        const loop = num - data.multipleUseVariable;
        for (let i = 0; i < Math.abs(loop); i++) {
            if (loop > 0) {
                await selectedOneMore();
            } else {
                await selectedOneLess();
            }
        }
    }

</script>

{#if isShowReq}
    {#if required.type === 'gid'}
        {#each globalRequireds as globalRequired}
            {#if globalRequired.showRequired}
                {#key replaceText(getChoiceTitle(globalRequired))}
                    <div class="req text-prewrap" style={scoreText}>
                        {@html DOMPurify.sanitize(replaceText(getChoiceTitle(globalRequired)), sanitizeArg)}
                    </div>
                {/key}
            {/if}
        {/each}
    {:else}
        {#key reqTitle}
            <div class="req text-prewrap" style={scoreText}>
                {@html DOMPurify.sanitize(reqTitle, sanitizeArg)}
            </div>
        {/key}
    {/if}
{/if}

<script lang="ts">
    import DOMPurify from 'dompurify';
    import type { Requireds } from '$lib/store/types';
    import { app, globalReqMap, replaceText, sanitizeArg, checkReq, checkRequirements, getChoiceTitle } from '$lib/store/store.svelte';

    const { required, scoreText }: { required: Requireds; scoreText?: string; } = $props();

    let globalRequireds = $derived.by(() => {
        let globalReq = globalReqMap.get(required.reqId);
        if (typeof globalReq !== 'undefined' && typeof app.globalRequirements !== 'undefined') {
            return globalReq.requireds;
        }
        return [];
    });
    let isShowReq = $derived.by(() => {
        let result = false;
        if (required.showRequired) {
            result = true;
            if (required.hideRequired2) {
                result = checkRequirements(required.requireds);
            }
            if (required.hideRequired) {
                if (required.requireds.length > 0) {
                    result = checkRequirements(required.requireds) && !checkReq(required);
                } else {
                    result = !checkReq(required);
                }
            }
        }
        return result;
    });
    let reqTitle = $derived(replaceText(getChoiceTitle(required)));
</script>

{#if isPointtypeActivated() && checkRequirements(score.requireds)}
    <div class="row m-0">
        <div class="col-12 p-0 m-0 d-flex align-items-center justify-{textAlign}" style={scoreText}>
            {#key scoreWholeText}
                <p class="m-0 d-flex text-prewrap align-items-center">
                    {#if scoreIcon}
                        {#if iconBeforeTextL}<img src={iconImage} class="me-1" style="width: {iconWidth}px; height: {iconHeight}px;" alt="">{/if}
                        {@html DOMPurify.sanitize(scoreBeforeText, sanitizeArg)}{#if iconBeforeTextR}<img src={iconImage} class="mx-1" style="width: {iconWidth}px; height: {iconHeight}px;" alt="">{/if}
                        {@html DOMPurify.sanitize(scoreValueText, sanitizeArg)}{#if iconAfterTextL}<img src={iconImage} class="mx-1" style="width: {iconWidth}px; height: {iconHeight}px;" alt="">{/if}
                        {@html DOMPurify.sanitize(scoreAfterText, sanitizeArg)}{#if iconAfterTextR}<img src={iconImage} class="ms-1" style="width: {iconWidth}px; height: {iconHeight}px;" alt="">{/if}
                    {:else}
                        {@html DOMPurify.sanitize(`${scoreFullText}`, sanitizeArg)}
                    {/if}
                </p>
            {/key}
        </div>
    </div>
{/if}

<script lang="ts">
    import DOMPurify from 'dompurify';
    import { checkActivated, checkRequirements, getStyling, globalReqMap, pointTypeMap, sanitizeArg, variableMap, hexToRgba, choiceMap, calcStackDiscount } from '$lib/store/store.svelte';
    import type { Addon, Choice, Row, Score } from '$lib/store/types';
    import { evaluate } from '@antv/expr';
    import { DISABLED, ACTIVE } from '$lib/store/constants';

    let { score, row, choice, addon }: { score: Score; row?: Row; choice: Choice; addon?: Addon; } = $props();
    let data = $derived(addon ? addon : choice);
    let textStyle = $derived(getStyling('privateTextIsOn', row, choice));
    let filterStyle = $derived(getStyling('privateFilterIsOn', row, choice));
    let pointType = $derived(pointTypeMap.get(score.id));
    let isEnabled = $derived(checkRequirements(data.requireds));
    let discountTexts = $derived.by(() => {
        const result = { before: '', after: '', replace: false, show: false, hideVal: false, hideIcon: false };
        const beforeTexts: string[] = [];
        const afterTexts: string[] = [];
        if (!score.discountIsOn || !score.appliedDiscount || typeof score.discounts === 'undefined') return result;
        for (let i = 0; i < score.discounts.length; i++) {
            const dc = score.discounts[i];

            if (dc.state === ACTIVE && dc.showDiscount) {
                result.show = true;
                if (dc.beforeText !== '') {
                    if (!dc.consolidate || dc.consolidate && beforeTexts.indexOf(dc.beforeText) === DISABLED) beforeTexts.push(dc.beforeText);
                }
                if (dc.afterText !== '') {
                    if (!dc.consolidate || dc.consolidate && afterTexts.indexOf(dc.afterText) === DISABLED) afterTexts.push(dc.afterText);
                }
                if (dc.replaceText) result.replace = true;
                if (dc.hideValue) result.hideVal = true;
                if (dc.hideIcon) result.hideIcon = true;
                if (!dc.stackable) break;
            }
        }
        if (beforeTexts.length > 0) {
            result.before = beforeTexts.join(' ');
        }
        if (afterTexts.length > 0) {
            result.after = afterTexts.join(' ');
        }

        return result;
    });
    let scoreAfterText = $derived.by(() => {
        let text = [];
        if (score.discountIsOn && score.appliedDiscount && discountTexts.show) {
            if (!discountTexts.replace) text.push(`${score.afterText}`);
            if (discountTexts.after !== '') text.push(`${discountTexts.after}`);
        } else {
            text.push(`${score.afterText}`);
        }
        return text.join(' ');
    });
    let scoreBeforeText = $derived.by(() => {
        let text = [];
        if (score.discountIsOn && score.appliedDiscount && discountTexts.show) {
            if (!discountTexts.replace) text.push(`${score.beforeText}`);
            if (discountTexts.before !== '') text.push(`${discountTexts.before}`);
        } else {
            text.push(`${score.beforeText}`);
        }
        return text.join(' ');
    });
    let scoreValueText = $derived.by(() => {
        if (score.hideValue) return '';

        let value = score.value;
        if (score.isRandom && !score.setValue) {
            return scoreRandomValue;
        }
        if (!score.setValue && score.useExpression && score.expValue) {
            const point = pointTypeMap.get(score.id);
            if (typeof point !== 'undefined') {
                try {
                    const replaced = score.expValue.replace(/\{([^{}]+)\}/g, (_, vStr) => {
                        const vPoint = pointTypeMap.get(vStr);
                        if (typeof vPoint !== 'undefined') {
                            return `${vPoint.startingSum}`;
                        }
                        throw new Error(`Undefined variable: "${vStr}"`);
                    });
                    value = evaluate(replaced);
                } catch (e) {
                    console.error(e);
                }
            }
        }
        if (discountTexts.show && score.appliedDiscount) {
            if (discountTexts.replace && discountTexts.hideVal) return '';
            if (typeof score.discountScore !== 'undefined') value = score.discountScore;
        }
        value = Math.abs(value);
        if (!pointType?.allowFloat) {
            value = Math.floor(value);
        } else {
            value = value % 1 === 0 ? value : parseFloat(value.toFixed(typeof pointType.decimalPlaces !== 'undefined' ? pointType.decimalPlaces : 2));
        }
        if (data.isSelectableMultiple && data.isMultipleUseVariable && score.multiplyByTimes && score.displayMulScore) {
            value = value * (data.multipleUseVariable + 1);
        }
        if (pointType?.plussOrMinusAdded) {
            let prefix = pointType.plussOrMinusInverted ? (checkNegative ? '-' : '+') : (checkNegative ? '+' : '-');
            return `${prefix}${value}`;
        }
        return `${value}`;
    });
    let scoreRandomValue = $derived.by(() => {
        let maxVal = 0;
        let minVal = 0;
        let isMaxNegative = false;
        let isMinNegative = false;
        if (score.useExpression) {
            if (score.expMaxValue) {
                try {
                    const replaced = score.expMaxValue.replace(/\{([^{}]+)\}/g, (_, vStr) => {
                        const vPoint = pointTypeMap.get(vStr);
                        if (typeof vPoint !== 'undefined') {
                            return `${vPoint.startingSum}`;
                        }
                        throw new Error(`Undefined variable: "${vStr}"`);
                    });
                    maxVal = evaluate(replaced);
                    isMaxNegative = maxVal < 0;
                } catch (e) {
                    console.error(e);
                }
            }
            if (score.expMinValue) {
                try {
                    const replaced = score.expMinValue.replace(/\{([^{}]+)\}/g, (_, vStr) => {
                        const vPoint = pointTypeMap.get(vStr);
                        if (typeof vPoint !== 'undefined') {
                            return `${vPoint.startingSum}`;
                        }
                        throw new Error(`Undefined variable: "${vStr}"`);
                    });
                    minVal = evaluate(replaced);
                    isMinNegative = minVal < 0;
                } catch (e) {
                    console.error(e);
                }
            }
        } else if (typeof score.maxValue !== 'undefined' && typeof score.minValue !== 'undefined') {
            isMaxNegative = score.maxValue < 0;
            isMinNegative = score.minValue < 0;
            maxVal = Math.abs(score.maxValue);
            minVal = Math.abs(score.minValue);
        }
        if (!pointType?.allowFloat) {
            maxVal = Math.floor(maxVal);
            minVal = Math.floor(minVal);
        } else {
            maxVal = maxVal % 1 === 0 ? maxVal : parseFloat(maxVal.toFixed(typeof pointType.decimalPlaces !== 'undefined' ? pointType.decimalPlaces : 2));
            minVal = minVal % 1 === 0 ? minVal : parseFloat(minVal.toFixed(typeof pointType.decimalPlaces !== 'undefined' ? pointType.decimalPlaces : 2));
        }
        if (pointType?.plussOrMinusAdded) {
            let maxPrefix = pointType.plussOrMinusInverted ? (isMaxNegative ? '-' : '+') : (isMaxNegative ? '+' : '-');
            let minPrefix = pointType.plussOrMinusInverted ? (isMinNegative ? '-' : '+') : (isMinNegative ? '+' : '-');
            return isMaxNegative ? `${maxPrefix}${maxVal} ~ ${minPrefix}${minVal}` : `${minPrefix}${minVal} ~ ${maxPrefix}${maxVal}`;
        }
        return isMaxNegative ? `${maxVal} ~ ${minVal}` : `${minVal} ~ ${maxVal}`;
    });
    let checkNegative = $derived.by(() => {
        if (score.discountShow) {
            return (typeof score.discountScore !== 'undefined' && score.appliedDiscount ? score.discountScore : score.value) < 0;
        }
        return score.value < 0;
    });
    let scoreFullText = $derived.by(() => {
        let result = '';
        if (scoreBeforeText) result += scoreBeforeText;
        if (scoreValueText) result += (result ? ' ' : '') + scoreValueText;
        if (scoreAfterText) result += (result ? ' ' : '') + scoreAfterText;

        return result;
    });
    let scoreText = $derived.by(() => {
        const style: string[] = [];
        let color = hexToRgba(textStyle.scoreTextColor);

        style.push(`font-family: '${textStyle.scoreText}'; font-size: ${textStyle.scoreTextSize}%;`);

        if (pointType && pointType.pointColorsIsOn) {
            if (checkNegative) {
                color = hexToRgba(pointType.positiveColor);
            } else {
                color = hexToRgba(pointType.negativeColor);
            }
        }
        if (!isEnabled) {
            if (filterStyle.reqScoreTextColorIsOn)  {
                color = hexToRgba(filterStyle.reqFilterSTextColor);
            }
        } else if (data.isActive) {
            if (filterStyle.selScoreTextColorIsOn) {
                color = hexToRgba(filterStyle.selFilterSTextColor);
            }
        }
        style.push(`color: ${color};`);

        return style.join(' ');
    });
    let scoreIcon = $derived.by(() => {
        if (!pointType || !pointType.iconIsOn) return false;
        if (score.appliedDiscount && discountTexts.show) {
            if (discountTexts.replace && discountTexts.hideIcon) return false;
        }
        return true;
    });
    let isNegIcon = $derived(pointType?.negativeIconIsOn && !checkNegative);
    let imageSidePlacement = $derived.by(() => {
        if (!pointType) return false;
        if (isNegIcon) {
            return pointType.useSeperatePosition ? !!pointType.negativeImageSidePlacementInChoice : !!pointType.negativeImageSidePlacement;
        }
        return pointType.useSeperatePosition ? !!pointType.imageSidePlacementInChoice : !!pointType.imageSidePlacement;
    });
    let imageOnSide = $derived.by(() => {
        if (!pointType) return false;
        if (isNegIcon) {
            return pointType.useSeperatePosition ? !!pointType.negativeImageOnSideInChoice : !!pointType.negativeImageOnSide;
        }
        return pointType.useSeperatePosition ? !!pointType.imageOnSideInChoice : !!pointType.imageOnSide;
    });
    let textAlign = $derived.by(() => {
        const align = textStyle.scoreTextAlign;

        if (align === 'left') return 'start';
        if (align === 'right') return 'end';
        if (align === 'justify') return 'space-between';
        return 'center';
    });
    let iconImage = $derived((isNegIcon ? pointType?.negativeImage : pointType?.image) || '');
    let iconWidth = $derived((isNegIcon ? pointType?.negativeIconWidth : pointType?.iconWidth) || 0);
    let iconHeight = $derived((isNegIcon ? pointType?.negativeIconHeight : pointType?.iconHeight) || 0);
    let iconBeforeTextL = $derived(!imageSidePlacement && !imageOnSide);
    let iconBeforeTextR = $derived(!imageSidePlacement && imageOnSide);
    let iconAfterTextL = $derived(imageSidePlacement && !imageOnSide);
    let iconAfterTextR = $derived(imageSidePlacement && imageOnSide);
    let scoreWholeText = $derived(`${scoreBeforeText} ${scoreValueText} ${scoreAfterText}`);

    function isPointtypeActivated() {
        if (score.showScore) {
            if (typeof pointType !== 'undefined') {
                if (pointType.isNotShownObjects) {
                    if (typeof pointType.activatedId !== 'undefined' && pointType.activatedId !== '') {
                        let globalReq = globalReqMap.get(pointType.activatedId);
                        let variable = variableMap.get(pointType.activatedId);
                        if (typeof globalReq !== 'undefined') {
                            return checkRequirements(globalReq.requireds);
                        }
                        if (typeof variable !== 'undefined') {
                            return variable.isTrue;
                        }
                        return checkActivated(pointType.activatedId);
                    }
                    return false;
                }
            }
            return true;
        }
        return false;
    }
</script>

